INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82fca041-925c-4dff-ac4d-4c9020c34624', '銅雀妓二首 一', '銅雀妓二首 一', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["金鳳隣銅雀，漳河望鄴城。","君王無處所，臺榭若平生。","舞席紛何就，歌梁儼未傾。","西陵松檟冷，誰見綺羅情。"]', '["金鳳隣銅雀，漳河望鄴城。","君王無处所，台榭若平生。","舞席紛何就，歌梁儼未傾。","西陵松檟冷，誰见綺羅情。"]', '诗', 'shi', '', NULL, '銅雀妓二首 一 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef84f609-2fad-4a57-8adf-6a78b1d23130', '銅雀妓二首 二', '銅雀妓二首 二', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["妾本深宮妓，層城閉九重。","君王歡愛盡，歌舞爲誰容。","錦衾不復襞，羅衣誰再縫。","高臺西北望，流涕向青松。"]', '["妾本深宮妓，層城閉九重。","君王歡愛尽，歌舞爲誰容。","錦衾不复襞，羅衣誰再縫。","高台西北望，流涕向青松。"]', '诗', 'shi', '', NULL, '銅雀妓二首 二 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('123842a3-3c92-4df0-91fa-b266cb60ab70', '羈遊餞別', '羈游餞別', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["客心懸隴路，遊子倦江干。","槿豐朝砌靜，篠密夜窗寒。","琴聲銷別恨，風景駐離歡。","寧覺山川遠，悠悠旅思難。"]', '["客心懸隴路，游子倦江干。","槿豐朝砌静，篠密夜窗寒。","琴声銷別恨，风景駐離歡。","寧覺山川远，悠悠旅思难。"]', '诗', 'shi', '', NULL, '羈遊餞別 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('112d4450-e99b-40e9-9240-2394ca67fdf0', '易陽早發', '易陽早發', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["飭裝侵曉月，奔策候殘星。","危閣尋丹障，回梁屬翠屏。","雲間迷樹影，霧裏失峰形。","復此涼飆至，空山飛夜螢。"]', '["飭裝侵晓月，奔策候殘星。","危閣尋丹障，回梁屬翠屏。","云间迷樹影，霧裏失峰形。","复此涼飆至，空山飞夜螢。"]', '诗', 'shi', '', NULL, '易陽早發 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b578bf5-9e4e-43e7-8338-ca5415237316', '焦岸早行和陸四', '焦岸早行和陸四', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["侵星違旅館，乘月戒征儔。","複嶂迷晴色，虛巖辨暗流。","猿吟山漏曉，螢散野風秋。","故人渺何際，鄉關雲霧浮。"]', '["侵星違旅館，乘月戒征儔。","複嶂迷晴色，虛巖辨暗流。","猿吟山漏晓，螢散野风秋。","故人渺何際，乡关云霧浮。"]', '诗', 'shi', '', NULL, '焦岸早行和陸四 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86ff7450-35ec-4af2-b942-6b4db15ca262', '深灣夜宿', '深灣夜宿', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["津塗臨巨壑，村宇架危岑。","堰絕灘聲隱，風交樹影深。","江童暮理楫，山女夜調砧。","此時故鄉遠，寧知遊子心。"]', '["津塗臨巨壑，村宇架危岑。","堰絕灘声隐，风交樹影深。","江童暮理楫，山女夜調砧。","此时故乡远，寧知游子心。"]', '诗', 'shi', '', NULL, '深灣夜宿 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79640c79-b07a-49c2-a4a3-f37b4e501646', '傷裴錄事喪子', '傷裴錄事喪子', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["蘭階霜候早，松露穸臺深。","魄散珠胎沒，芳銷玉樹沈。","露文晞宿草，煙照慘平林。","芝焚空歡息，流恨滿籝金。"]', '["蘭階霜候早，松露穸台深。","魄散珠胎沒，芳銷玉樹沈。","露文晞宿草，煙照慘平林。","芝焚空歡息，流恨满籝金。"]', '诗', 'shi', '', NULL, '傷裴錄事喪子 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc836dc1-04ee-4d2c-837c-c7d3e8ba0e21', '泥谿', '泥谿', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["弭櫂凌奔壑，低鞭躡峻岐。","江濤出岸險，峰磴入雲危。","溜急船文亂，巖斜騎影移。","水煙籠翠渚，山照落丹崖。","風生蘋浦葉，露泣竹潭枝。","泛水雖云美，勞歌誰復知。"]', '["弭櫂凌奔壑，低鞭躡峻岐。","江濤出岸險，峰磴入云危。","溜急船文亂，巖斜騎影移。","水煙籠翠渚，山照落丹崖。","风生蘋浦葉，露泣竹潭枝。","泛水雖云美，勞歌誰复知。"]', '诗', 'shi', '', NULL, '泥谿 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67a82adc-0139-4386-bd11-09c4ac4a0a6d', '三月曲水宴得煙字', '三月曲水宴得煙字', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["彭澤官初去，河陽賦始傳。","田園歸舊國，詩酒間長筵。","列室窺丹洞，分樓瞰紫煙。","縈回亙津渡，出沒控郊鄽。","鳳琴調上客，龍轡儼羣仙。","松石偏宜古，藤蘿不記年。","重簷交密樹，複磴擁危泉。","抗石晞南嶺，乘沙眇北川。","傅巖來築處，磻谿入釣前。","日斜真趣遠，幽思夢涼蟬。"]', '["彭澤官初去，河陽賦始傳。","田园归旧国，诗酒间长筵。","列室窺丹洞，分楼瞰紫煙。","縈回亙津渡，出沒控郊鄽。","鳳琴調上客，龙轡儼羣仙。","松石偏宜古，藤蘿不記年。","重簷交密樹，複磴擁危泉。","抗石晞南嶺，乘沙眇北川。","傅巖来築处，磻谿入釣前。","日斜真趣远，幽思梦涼蟬。"]', '诗', 'shi', '', NULL, '三月曲水宴得煙字 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3111901b-f614-494c-a769-1885fd1e0176', '秋日仙遊觀贈道士', '秋日仙游观贈道士', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["石圖分帝宇，銀牒洞靈宮。","回丹縈岫室，複翠上巖櫳。","霧濃金竈靜，雲暗玉壇空。","野花常捧露，山葉自吟風。","林泉明月在，詩酒故人同。","待余逢石髓，從爾命飛鴻。"]', '["石圖分帝宇，銀牒洞靈宮。","回丹縈岫室，複翠上巖櫳。","霧濃金竈静，云暗玉壇空。","野花常捧露，山葉自吟风。","林泉明月在，诗酒故人同。","待余逢石髓，從爾命飞鴻。"]', '诗', 'shi', '', NULL, '秋日仙遊觀贈道士 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77543371-3de1-4684-814a-3f3b5a132eb6', '晚留鳳州', '晚留鳳州', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["寶雞辭舊役，仙鳳歷遺墟。","去此近城闕，青山明月初。"]', '["寶雞辞旧役，仙鳳歷遺墟。","去此近城闕，青山明月初。"]', '诗', 'shi', '', NULL, '晚留鳳州 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91cc3eca-d031-43bf-bbbd-4a48954453a7', '羈春', '羈春', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["客心千里倦，春事一朝歸。","還傷北園裏，重見落花飛。"]', '["客心千里倦，春事一朝归。","還傷北园裏，重见落花飞。"]', '诗', 'shi', '', NULL, '羈春 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94022239-90f0-406b-a62a-3edfdbbe7ada', '林塘懷友', '林塘懷友', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["芳屏畫春草，仙杼織朝霞。","何如山水路，對面即飛花。"]', '["芳屏畫春草，仙杼织朝霞。","何如山水路，对面即飞花。"]', '诗', 'shi', '', NULL, '林塘懷友 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c5b2983-2eb6-4928-b442-8c706ed3652a', '山扉夜坐', '山扉夜坐', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["抱琴開野室，攜酒對情人。","林塘花月下，別似一家春。"]', '["抱琴开野室，携酒对情人。","林塘花月下，別似一家春。"]', '诗', 'shi', '', NULL, '山扉夜坐 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a9c7db2-1ad2-41ef-b966-8eb981c8d58e', '春莊', '春莊', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["山中蘭葉徑，城外李桃園。","豈知人事靜，不覺鳥聲喧。"]', '["山中蘭葉徑，城外李桃园。","豈知人事静，不覺鸟声喧。"]', '诗', 'shi', '', NULL, '春莊 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74e2c332-55d9-4955-8045-adbad8a66851', '春遊', '春游', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["客念紛無極，春淚倍成行。","今朝花樹下，不覺戀年光。"]', '["客念紛無極，春泪倍成行。","今朝花樹下，不覺戀年光。"]', '诗', 'shi', '', NULL, '春遊 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7ac2288-f018-4b60-975b-029396f304a4', '春園', '春园', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["山泉兩處晚，花柳一園春。","還持千日醉，共作百年人。"]', '["山泉兩处晚，花柳一园春。","還持千日醉，共作百年人。"]', '诗', 'shi', '', NULL, '春園 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df5055a0-1521-437c-9a6e-ae3df8c1d153', '林泉獨飲', '林泉独饮', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["丘壑經塗賞，花柳遇時春。","相逢今不醉，物色自輕人。"]', '["丘壑經塗賞，花柳遇时春。","相逢今不醉，物色自轻人。"]', '诗', 'shi', '', NULL, '林泉獨飲 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f765cfa-622b-4c8d-b9f3-f13440de01de', '登城春望', '登城春望', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["物外山川近，晴初景靄新。","芳郊花柳遍，何處不宜春。"]', '["物外山川近，晴初景靄新。","芳郊花柳遍，何处不宜春。"]', '诗', 'shi', '', NULL, '登城春望 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('358c696a-cc60-46d0-9aaf-96c0d08e5e9e', '他鄉敘興', '他乡敘兴', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["綴葉歸煙晚，乘花落照春。","邊城琴酒處，俱是越鄉人。"]', '["綴葉归煙晚，乘花落照春。","邊城琴酒处，俱是越乡人。"]', '诗', 'shi', '', NULL, '他鄉敘興 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9b7ad02-abcc-4a88-ac7f-f1c1204f994b', '夜興', '夜兴', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["野煙含夕渚，山月照秋林。","還將中散興，來偶步兵琴。"]', '["野煙含夕渚，山月照秋林。","還將中散兴，来偶步兵琴。"]', '诗', 'shi', '', NULL, '夜興 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('501f2ee5-f8ba-469f-9a59-45c6be0bb91d', '臨江二首 一', '臨江二首 一', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["泛泛東流水，飛飛北上塵。","歸驂將別櫂，俱是倦遊人。"]', '["泛泛东流水，飞飞北上塵。","归驂將別櫂，俱是倦游人。"]', '诗', 'shi', '', NULL, '臨江二首 一 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e369ad64-e4aa-48b2-94fa-8909ff3b9e0f', '臨江二首 二', '臨江二首 二', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["去驂嘶別路，歸櫂隱寒洲。","江臯木葉下，應想故城秋。"]', '["去驂嘶別路，归櫂隐寒洲。","江臯木葉下，應想故城秋。"]', '诗', 'shi', '', NULL, '臨江二首 二 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('578be3ae-14e8-40ad-83b3-0164a3317373', '江亭夜月送別二首 一', '江亭夜月送別二首 一', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["江送巴南水，山橫塞北雲。","津亭秋月夜，誰見泣離羣。"]', '["江送巴南水，山橫塞北云。","津亭秋月夜，誰见泣離羣。"]', '诗', 'shi', '', NULL, '江亭夜月送別二首 一 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fbe30ba-00aa-4f75-ae59-29d303e71ef4', '江亭夜月送別二首 二', '江亭夜月送別二首 二', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["亂煙籠碧砌，飛月向南端。","寂寂離亭掩，江山此夜寒。"]', '["亂煙籠碧砌，飞月向南端。","寂寂離亭掩，江山此夜寒。"]', '诗', 'shi', '', NULL, '江亭夜月送別二首 二 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49b5b38a-d039-4ad1-a75e-dcae900e9dbe', '別人四首 一', '別人四首 一', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["久客逢餘閏，他鄉別故人。","自然堪下淚，誰忍望征塵。"]', '["久客逢餘閏，他乡別故人。","自然堪下泪，誰忍望征塵。"]', '诗', 'shi', '', NULL, '別人四首 一 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e76c634e-4174-4cf1-80f3-c61f8c96b541', '別人四首 二', '別人四首 二', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["江上風煙積，山幽雲霧多。","送君南浦外，還望將如何。"]', '["江上风煙積，山幽云霧多。","送君南浦外，還望將如何。"]', '诗', 'shi', '', NULL, '別人四首 二 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8d6e176-904e-405b-a98c-7043314a33c3', '別人四首 三', '別人四首 三', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["桂軺雖不駐，蘭筵幸未開。","林塘風月賞，還待故人來。"]', '["桂軺雖不駐，蘭筵幸未开。","林塘风月賞，還待故人来。"]', '诗', 'shi', '', NULL, '別人四首 三 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5704085a-1f6b-4812-98de-4c01adda584f', '別人四首 四', '別人四首 四', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["霜華淨天末，霧色籠江際。","客子常畏人，何爲久留滯。"]', '["霜华淨天末，霧色籠江際。","客子常畏人，何爲久留滯。"]', '诗', 'shi', '', NULL, '別人四首 四 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d629eb3-160f-4d7c-8cd9-6e1b46b26d6a', '贈李十四四首 一', '贈李十四四首 一', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["野客思茅宇，山人愛竹林。","琴尊唯待處，風月自相尋。"]', '["野客思茅宇，山人愛竹林。","琴尊唯待处，风月自相尋。"]', '诗', 'shi', '', NULL, '贈李十四四首 一 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58378cfd-0162-4e68-9c99-d1b54158ce62', '贈李十四四首 二', '贈李十四四首 二', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["小徑偏宜草，空庭不厭花。","平生詩與酒，自得會仙家。"]', '["小徑偏宜草，空庭不厭花。","平生诗與酒，自得會仙家。"]', '诗', 'shi', '', NULL, '贈李十四四首 二 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c77888f7-108b-49df-b80c-76ade79ba0e8', '贈李十四四首 三', '贈李十四四首 三', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["亂竹開三徑，飛花滿四鄰。","從來揚子宅，別有尚玄人。"]', '["亂竹开三徑，飞花满四鄰。","從来揚子宅，別有尚玄人。"]', '诗', 'shi', '', NULL, '贈李十四四首 三 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3d2eb67-d9ba-49a8-b1ec-20e573372744', '贈李十四四首 四', '贈李十四四首 四', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["風筵調桂軫，月徑引藤杯。","直當花院裏，書齋望曉開。"]', '["风筵調桂軫，月徑引藤杯。","直當花院裏，书斋望晓开。"]', '诗', 'shi', '', NULL, '贈李十四四首 四 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8529e91c-0ece-4d64-8e96-2211d69e7d72', '早春野望', '早春野望', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["江曠春潮白，山長曉岫青。","他鄉臨睨極，花柳映邊亭。"]', '["江曠春潮白，山长晓岫青。","他乡臨睨極，花柳映邊亭。"]', '诗', 'shi', '', NULL, '早春野望 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('463e1ff1-7a19-4fe0-a5c5-51908a0762a7', '山中', '山中', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["長江悲已滯，萬里念將歸。","況屬高風晚，山山黃葉飛。"]', '["长江悲已滯，万里念將归。","況屬高风晚，山山黄葉飞。"]', '诗', 'shi', '', NULL, '山中 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32db4913-daec-4876-99a7-be5aca59f036', '冬郊行望', '冬郊行望', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["桂密巖花白，梨疎林葉紅。","江臯寒望盡，歸念斷征篷。"]', '["桂密巖花白，梨疎林葉紅。","江臯寒望尽，归念斷征篷。"]', '诗', 'shi', '', NULL, '冬郊行望 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bafe8f0-4495-43ad-ae2d-6396736f7d71', '寒夜思友三首 一', '寒夜思友三首 一', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["久別侵懷抱，他鄉變容色。","月下調鳴琴，相思此何極。"]', '["久別侵懷抱，他乡变容色。","月下調鳴琴，相思此何極。"]', '诗', 'shi', '', NULL, '寒夜思友三首 一 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6a82d61-a77d-4561-afd4-37fa8309278a', '寒夜思友三首 二', '寒夜思友三首 二', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["雲間征思斷，月下歸愁切。","鴻雁西南飛，如何故人別。"]', '["云间征思斷，月下归愁切。","鴻雁西南飞，如何故人別。"]', '诗', 'shi', '', NULL, '寒夜思友三首 二 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b567b237-5a30-4794-9842-f0089386da68', '寒夜思友三首 三', '寒夜思友三首 三', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["朝朝翠山下，夜夜蒼江曲。","復此遙相思，清尊湛芳綠。"]', '["朝朝翠山下，夜夜蒼江曲。","复此遙相思，清尊湛芳綠。"]', '诗', 'shi', '', NULL, '寒夜思友三首 三 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ca4310e-22e4-442f-bae3-e0d169dcdc88', '始平晚息', '始平晚息', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["觀闕長安近，江山蜀路賒。","客行朝復夕，無處是鄉家。"]', '["观闕长安近，江山蜀路賒。","客行朝复夕，無处是乡家。"]', '诗', 'shi', '', NULL, '始平晚息 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7753d7f2-10d6-4fd4-a5d0-9d48d026fbf4', '扶風晝屆離京浸遠', '扶风晝屆離京浸远', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["帝里金莖去，扶風石柱來。","山川殊未已，行路方悠哉。"]', '["帝里金莖去，扶风石柱来。","山川殊未已，行路方悠哉。"]', '诗', 'shi', '', NULL, '扶風晝屆離京浸遠 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbfe3479-e867-4d6a-90e2-f9f11ecb5be3', '普安建陰題壁', '普安建陰題壁', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["江漢深無極，梁岷不可攀。","山川雲霧裏，遊子幾時還。"]', '["江漢深無極，梁岷不可攀。","山川云霧裏，游子幾时還。"]', '诗', 'shi', '', NULL, '普安建陰題壁 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8829209-71a5-40d8-9c6b-c444f4d5ab48', '九日', '九日', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["九日重陽節，開門有菊花。","不知來送酒，若箇是陶家。"]', '["九日重陽節，开门有菊花。","不知来送酒，若箇是陶家。"]', '诗', 'shi', '', NULL, '九日 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d89a5f6c-27c6-48fb-9204-1fafb7a7e4e1', '秋江送別二首 一', '秋江送別二首 一', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["早是他鄉值早秋，江亭明月帶江流。","已覺逝川傷別念，復看津樹隱離舟。"]', '["早是他乡值早秋，江亭明月带江流。","已覺逝川傷別念，复看津樹隐離舟。"]', '诗', 'shi', '', NULL, '秋江送別二首 一 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14d385f5-268a-4d8b-818c-cc4d84563be3', '秋江送別二首 二', '秋江送別二首 二', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["歸舟歸騎儼成行，江南江北互相望。","誰謂波瀾纔一水，已覺山川是兩鄉。"]', '["归舟归騎儼成行，江南江北互相望。","誰謂波瀾纔一水，已覺山川是兩乡。"]', '诗', 'shi', '', NULL, '秋江送別二首 二 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3d9312f-1c3b-4234-b66e-1163a08c82fa', '蜀中九日', '蜀中九日', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["九月九日望鄉臺，他席他鄉送客杯。","人情已厭南中苦，鴻雁那從北地來。"]', '["九月九日望乡台，他席他乡送客杯。","人情已厭南中苦，鴻雁那從北地来。"]', '诗', 'shi', '', NULL, '蜀中九日 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c378da46-b638-4e25-9f2c-09ca7e4d04cd', '寒夜懷友雜體二首 一', '寒夜懷友杂體二首 一', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["北山煙霧始茫茫，南津霜月正蒼蒼。","秋深客思紛無已，復值征鴻中夜起。"]', '["北山煙霧始茫茫，南津霜月正蒼蒼。","秋深客思紛無已，复值征鴻中夜起。"]', '诗', 'shi', '', NULL, '寒夜懷友雜體二首 一 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11c281c6-bae3-42d3-9ec8-170d627b158f', '寒夜懷友雜體二首 二', '寒夜懷友杂體二首 二', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["複閣重樓向浦開，秋風明月度江來。","故人故情懷故宴，相望相思不相見。"]', '["複閣重楼向浦开，秋风明月度江来。","故人故情懷故宴，相望相思不相见。"]', '诗', 'shi', '', NULL, '寒夜懷友雜體二首 二 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eba1605b-fbab-43b6-af79-c40f7f28fcf9', '落花落', '落花落', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["落花落，落花紛漠漠。","綠葉青跗映丹萼，與君裴回上金閣。","影拂粧階玳瑁筵，香飄舞館茱萸幙。","落花飛，撩亂入中帷。","落花春正滿，春人歸不歸。","落花度，氛氳遶高樹。","落花春已繁，春人春不顧。","綺閣青臺靜且閑，羅袂紅巾復往還。","盛年不再得，高枝難重攀。","試復旦遊落花裏，暮宿落花間。","與君落花院，臺上起雙鬟。"]', '["落花落，落花紛漠漠。","綠葉青跗映丹萼，與君裴回上金閣。","影拂粧階玳瑁筵，香飄舞館茱萸幙。","落花飞，撩亂入中帷。","落花春正满，春人归不归。","落花度，氛氳遶高樹。","落花春已繁，春人春不顧。","綺閣青台静且闲，羅袂紅巾复往還。","盛年不再得，高枝难重攀。","試复旦游落花裏，暮宿落花间。","與君落花院，台上起雙鬟。"]', '诗', 'shi', '', NULL, '落花落 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b3fc205-5d00-4e15-96cf-476ccb4a3b9b', '九日懷封元寂', '九日懷封元寂', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["九日郊原望，平野遍霜威。","蘭氣添新酌，花香染別衣。","九秋良會少，千里故人稀。","今日龍山外，當憶雁書歸。"]', '["九日郊原望，平野遍霜威。","蘭氣添新酌，花香染別衣。","九秋良會少，千里故人稀。","今日龙山外，當憶雁书归。"]', '诗', 'shi', '', NULL, '九日懷封元寂 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e36b53f-264d-403d-8cd4-fb941c395269', '出境遊山二首 一', '出境游山二首 一', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["源水終無路，山阿若有人。","驅羊先動石，走兔欲投巾。","洞晚秋泉冷，巖朝古樹新。","峰斜連鳥翅，磴疊上魚鱗。","化鶴千齡早，元龜六代春。","浮雲今可駕，滄海自成塵。"]', '["源水終無路，山阿若有人。","驱羊先动石，走兔欲投巾。","洞晚秋泉冷，巖朝古樹新。","峰斜連鸟翅，磴叠上鱼鱗。","化鹤千齡早，元龟六代春。","浮云今可駕，滄海自成塵。"]', '诗', 'shi', '', NULL, '出境遊山二首 一 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b5379c3-6035-4744-977b-190900ec42f0', '出境遊山二首 二', '出境游山二首 二', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["振翮凌霜吹，正月佇天潯。","回鑣凌翠壑，飛軫控青岑。","巖深靈竈沒，澗毀石渠沈。","宮闕雲間近，江山物外臨。","玉壇棲暮夜，珠洞結秋陰。","蕭蕭離俗影，擾擾望鄉心。","誰意山遊好屢傷人事侵。"]', '["振翮凌霜吹，正月佇天潯。","回鑣凌翠壑，飞軫控青岑。","巖深靈竈沒，澗毀石渠沈。","宮闕云间近，江山物外臨。","玉壇棲暮夜，珠洞結秋陰。","蕭蕭離俗影，擾擾望乡心。","誰意山游好屢傷人事侵。"]', '诗', 'shi', '', NULL, '出境遊山二首 二 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19724209-4e31-4e6f-ad5c-df587abd403e', '河陽橋代竇郎中佳人答楊中舍', '河陽橋代竇郎中佳人答楊中舍', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["披風聽鳥長河路，臨津織女遙相妬。","判知秋夕帶啼還，那及春朝攜手度。"]', '["披风听鸟长河路，臨津织女遙相妬。","判知秋夕带啼還，那及春朝携手度。"]', '诗', 'shi', '', NULL, '河陽橋代竇郎中佳人答楊中舍 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('335f1ed5-c9d8-4cfb-a36e-26bfd12d17ab', '晦日宴高氏林亭同用華字', '晦日宴高氏林亭同用华字', '8c5d508d-2dd0-42b7-aa06-85706b3c2795', '唐', '["上序披林館，中京視物華。","竹窗低露葉，梅逕起風花。","景落春臺霧，池侵舊渚沙。","綺筵歌吹晚，暮雨泛香車。"]', '["上序披林館，中京視物华。","竹窗低露葉，梅逕起风花。","景落春台霧，池侵旧渚沙。","綺筵歌吹晚，暮雨泛香车。"]', '诗', 'shi', '', NULL, '晦日宴高氏林亭同用華字 王勔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78a53054-7cc2-4aca-b6da-94a906ce6943', '奉教追赴九成宮途中口號', '奉教追赴九成宮途中口號', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["委質承仙翰，衹命遄遙策。","事偶從梁遊，人非背淮客。","長驅歷川阜，迥眺窮原澤。","鬱鬱桑柘繁，油油禾黍積。","雨餘林氣靜，日下山光夕。","未攀叢桂巖，猶倦飄蓬陌。","行當奉麾蓋，慰此勞行役。"]', '["委質承仙翰，衹命遄遙策。","事偶從梁游，人非背淮客。","长驱歷川阜，迥眺窮原澤。","鬱鬱桑柘繁，油油禾黍積。","雨餘林氣静，日下山光夕。","未攀叢桂巖，猶倦飄蓬陌。","行當奉麾蓋，慰此勞行役。"]', '诗', 'shi', '', NULL, '奉教追赴九成宮途中口號 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df61c665-a241-4f93-ba1c-1e18e72dea57', '秋山望月酬李騎曹', '秋山望月酬李騎曹', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["愁客坐山隈，懷抱自悠哉。","況復高秋夕，明月正裴回。","亭亭出迥岫，皎皎映層臺。","色帶銀河滿，光含玉露開。","淡雲籠影度，虛暈抱輪回。","谷邃涼陰靜，山空夜響哀。","寒催數雁過，風送一螢來。","獨軫離居恨，遙想故人杯。"]', '["愁客坐山隈，懷抱自悠哉。","況复高秋夕，明月正裴回。","亭亭出迥岫，皎皎映層台。","色带銀河满，光含玉露开。","淡云籠影度，虛暈抱輪回。","谷邃涼陰静，山空夜响哀。","寒催數雁過，风送一螢来。","独軫離居恨，遙想故人杯。"]', '诗', 'shi', '', NULL, '秋山望月酬李騎曹 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35fd0090-a805-41be-8086-41eaa191aff4', '和同府李祭酒休沐田居', '和同府李祭酒休沐田居', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["列位簪纓序，隱居林野躅。","徇物爽全直，棲真昧均俗。","若人兼吏隱，率性夷榮辱。","地藉朱邸基，家在青山足。","暫弭西園蓋，言事東臯粟。","築室俯澗濱，開扉面巖曲。","庭幽引夕霧，簷迥通晨旭。","迎秋谷黍黃，含露園葵綠。","勝情狎蘭杜，雅韻鏘金玉。","伊我懷丘園，願心從所欲。"]', '["列位簪纓序，隐居林野躅。","徇物爽全直，棲真昧均俗。","若人兼吏隐，率性夷榮辱。","地藉朱邸基，家在青山足。","暫弭西园蓋，言事东臯粟。","築室俯澗濱，开扉面巖曲。","庭幽引夕霧，簷迥通晨旭。","迎秋谷黍黄，含露园葵綠。","勝情狎蘭杜，雅韻鏘金玉。","伊我懷丘园，願心從所欲。"]', '诗', 'shi', '', NULL, '和同府李祭酒休沐田居 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e90e59e8-8270-4ff1-9ee8-ffce5a1bcc34', '扈從還洛呈侍從羣官', '扈從還洛呈侍從羣官', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["四海帝王家，兩都周漢室。","觀風昔來幸，御氣今旋蹕。","雷奮六合開，天行萬乘出。","玄冥奉時駕，白拒參戎律。","後隊咽笳簫，前驅嚴罕罼。","輝光射東井，禁令橫西秩。","帳殿別陽秋，旌門臨甲乙。","將交洛城雨，稍遠長安日。","邙鞏雲外來，咸秦霧中失。","孟冬霜霰下，是月農功畢。","天道向歸餘，皇情美陰隲。","行存名嶽禮，逓問高年疾。","祝鳥既開羅，調人更張瑟。","登原采謳誦，俯谷求才術。","邑罕懸磬貧，山無挂瓢逸。","施恩浹寰宇，展義該文質。","德澤盛軒遊，哀矜深禹恤。","申歌地廬駭，獻壽衢尊溢。","瑞色抱氤氳，寒光變蕭飋。","宗枝旦奭輔，侍從王劉匹。","竝輯蛟龍書，同簪鳳皇筆。","陶甄荷吹萬，頌歎歸明一。","歡與道路長，顧隨談笑密。","叨承廊廟選，謬齒夔龍弼。","喜構大廈成，慙非棟隆吉。"]', '["四海帝王家，兩都周漢室。","观风昔来幸，御氣今旋蹕。","雷奮六合开，天行万乘出。","玄冥奉时駕，白拒參戎律。","後隊咽笳簫，前驱嚴罕罼。","輝光射东井，禁令橫西秩。","帳殿別陽秋，旌门臨甲乙。","將交洛城雨，稍远长安日。","邙鞏云外来，咸秦霧中失。","孟冬霜霰下，是月農功畢。","天道向归餘，皇情美陰隲。","行存名嶽禮，逓问高年疾。","祝鸟既开羅，調人更張瑟。","登原采謳誦，俯谷求才術。","邑罕懸磬貧，山無挂瓢逸。","施恩浹寰宇，展義該文質。","德澤盛軒游，哀矜深禹恤。","申歌地廬駭，獻壽衢尊溢。","瑞色抱氤氳，寒光变蕭飋。","宗枝旦奭輔，侍從王劉匹。","竝輯蛟龙书，同簪鳳皇笔。","陶甄荷吹万，頌歎归明一。","歡與道路长，顧隨談笑密。","叨承廊廟選，謬齒夔龙弼。","喜構大廈成，慙非棟隆吉。"]', '诗', 'shi', '', NULL, '扈從還洛呈侍從羣官 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6589cbe8-a115-4fd3-ab1d-d1f3d7b2f446', '奉使築朔方六州城率爾而作', '奉使築朔方六州城率爾而作', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["奉詔受邊服，總徒築朔方。","驅彼犬羊族，正此戎夏疆。","子來多悅豫，王事寧怠遑。","三旬無愆期，百雉鬱相望。","雄視沙漠垂，有截北海陽。","二庭已頓顙，五嶺盡來王。","驅車登崇墉，顧眄凌大荒。","千里何蕭條，草木自悲涼。","憑軾訊古今，慨焉感興亡。","漢障緣河遠，秦城入海長。","顧無廟堂策，貽此中夏殃。","道隱前業衰，運開今化昌。","制爲百王式，舉合千載防。","馬牛被路隅，鋒鏑銷戰場。","豈不懷賢勞，所圖在永康。","王事何爲者，稱代陳頌章。"]', '["奉詔受邊服，總徒築朔方。","驱彼犬羊族，正此戎夏疆。","子来多悅豫，王事寧怠遑。","三旬無愆期，百雉鬱相望。","雄視沙漠垂，有截北海陽。","二庭已頓顙，五嶺尽来王。","驱车登崇墉，顧眄凌大荒。","千里何蕭條，草木自悲涼。","憑軾訊古今，慨焉感兴亡。","漢障緣河远，秦城入海长。","顧無廟堂策，貽此中夏殃。","道隐前業衰，運开今化昌。","制爲百王式，舉合千載防。","马牛被路隅，鋒鏑銷戰場。","豈不懷賢勞，所圖在永康。","王事何爲者，稱代陳頌章。"]', '诗', 'shi', '', NULL, '奉使築朔方六州城率爾而作 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc92d6eb-f194-40f1-a5a7-26ec7a527bfc', '早發苦竹館', '早發苦竹館', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["合沓巖嶂深，朦朧煙霧曉。","荒阡下樵客，野猿驚山鳥。","開門聽潺湲，入徑尋窈窕。","棲鼯抱寒木，流螢飛暗篠。","早霞稍霏霏，殘月猶皎皎。","行看遠星稀，漸覺遊氛少。","我行撫軺傳，兼得傍林沼。","貪玩水石奇，不知川路渺。","徒憐野心曠，詎惻浮年小。","方解寵辱情，永託累塵表。"]', '["合沓巖嶂深，朦朧煙霧晓。","荒阡下樵客，野猿驚山鸟。","开门听潺湲，入徑尋窈窕。","棲鼯抱寒木，流螢飞暗篠。","早霞稍霏霏，殘月猶皎皎。","行看远星稀，漸覺游氛少。","我行撫軺傳，兼得傍林沼。","貪玩水石奇，不知川路渺。","徒怜野心曠，詎惻浮年小。","方解寵辱情，永託累塵表。"]', '诗', 'shi', '', NULL, '早發苦竹館 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f79d5adb-0fd2-4ca3-a6a9-48fedfeb1804', '安輯嶺表事平罷歸', '安輯嶺表事平罷归', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["雲端想京縣，帝鄉如可見。","天涯望越臺，海路幾悠哉。","六月飛鵬去，三年瑞雉來。","境遙銅柱出，山險石門開。","自我違瀍洛，瞻途屢揮霍。","朝朝寒路多，夜夜征衣薄。","白簡承朝憲，朱方撫夷落。","既弘天覆廣，且諭皇恩博。","皇恩溢外區，憬俗詠來蘇。","聲朔臣天子，壇場拜老夫。","降宮韜將略，黃石寢兵符。","返斾收龍虎，空營集鳥烏。","日落澄氛靄，憑高視襟帶。","東甌抗於越，南斗臨吳會。","春色繞邊陲，飛花出荒外。","卉服紛如積，長川思遊客。","風生丹桂晚，雲起蒼梧夕。","去舳艤清江，歸軒趨紫陌。","衣裳會百蠻，琛賮委重關。","不學金刀使，空持寶劒還。"]', '["云端想京縣，帝乡如可见。","天涯望越台，海路幾悠哉。","六月飞鵬去，三年瑞雉来。","境遙銅柱出，山險石门开。","自我違瀍洛，瞻途屢揮霍。","朝朝寒路多，夜夜征衣薄。","白簡承朝憲，朱方撫夷落。","既弘天覆廣，且諭皇恩博。","皇恩溢外區，憬俗詠来蘇。","声朔臣天子，壇場拜老夫。","降宮韜將略，黄石寢兵符。","返斾收龙虎，空營集鸟烏。","日落澄氛靄，憑高視襟带。","东甌抗於越，南斗臨吳會。","春色繞邊陲，飞花出荒外。","卉服紛如積，长川思游客。","风生丹桂晚，云起蒼梧夕。","去舳艤清江，归軒趨紫陌。","衣裳會百蠻，琛賮委重关。","不学金刀使，空持寶劒還。"]', '诗', 'shi', '', NULL, '安輯嶺表事平罷歸 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a947bd17-9765-4ca7-919e-8de26cb89824', '鷓鴣', '鷓鴣', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["可憐鷓鴣飛，飛向樹南枝。","南枝日照暖，北枝霜露滋。","露滋不堪棲，使我常夜啼。","願逢雲中鶴，銜我向寥廓。","願作城上烏，一年生九雛。","何不舊巢住，枝弱不得去。","何意道苦辛，客子常畏人。"]', '["可怜鷓鴣飞，飞向樹南枝。","南枝日照暖，北枝霜露滋。","露滋不堪棲，使我常夜啼。","願逢云中鹤，銜我向寥廓。","願作城上烏，一年生九雛。","何不旧巢住，枝弱不得去。","何意道苦辛，客子常畏人。"]', '诗', 'shi', '', NULL, '鷓鴣 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d23adbb-2751-4d4a-b607-f7aa13d1eb95', '清明日龍門遊泛', '清明日龙门游泛', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["晴曉國門通，都門藹將發。","紛紛洛陽道，南望伊川闕。","衍漾乘和風，清明送芬月。","林窺二山動，水見千龕越。","羅袂罥楊絲，香橈犯苔髮。","羣心行樂未，唯恐流芳歇。"]', '["晴晓国门通，都门藹將發。","紛紛洛陽道，南望伊川闕。","衍漾乘和风，清明送芬月。","林窺二山动，水见千龕越。","羅袂罥楊絲，香橈犯苔髮。","羣心行乐未，唯恐流芳歇。"]', '诗', 'shi', '', NULL, '清明日龍門遊泛 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e7c7697-beed-47e7-b0df-0ba27f744fa2', '雲', '云', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["大梁白雲起，氛氳殊未歇。","錦文觸石來，蓋影凌天發。","煙煴萬年樹，掩映三秋月。","會入大風歌，從龍赴圓闕。"]', '["大梁白云起，氛氳殊未歇。","錦文觸石来，蓋影凌天發。","煙煴万年樹，掩映三秋月。","會入大风歌，從龙赴圓闕。"]', '诗', 'shi', '', NULL, '雲 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fba190c6-e609-4ba2-bda2-1ca828b71bc0', '擬古東飛伯勞西飛燕', '擬古东飞伯勞西飞燕', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["傳書青鳥迎簫鳳，巫嶺荆臺數通夢。","誰家窈窕住園樓，五馬千金照陌頭。","羅裙玉珮當軒出，點翠施紅競春日。","佳人二八盛舞歌，羞將百萬呈雙蛾。","庭前芳樹朝夕改，空駐妍華欲誰待。"]', '["傳书青鸟迎簫鳳，巫嶺荆台數通梦。","誰家窈窕住园楼，五马千金照陌头。","羅裙玉珮當軒出，点翠施紅競春日。","佳人二八盛舞歌，羞將百万呈雙蛾。","庭前芳樹朝夕改，空駐妍华欲誰待。"]', '诗', 'shi', '', NULL, '擬古東飛伯勞西飛燕 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e88ad76-f833-462a-9795-8b4b998d85d7', '寶劒篇', '寶劒篇', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["吳山開，越溪涸，三金合冶成寶鍔。","淬綠水，鑒紅雲，五采焰起光氛氳。","背上銘爲萬年字，胸前點作七星文。","龜甲參差白虹色，轆轤宛轉黃金飾。","駭犀中斷寧方利，駿馬羣騑未擬直。","風霜凜凜匣上清，精氣遙遙斗間明。","避災朝穿晉帝屋，逃亂夜入楚王城。","一朝運偶逢大仙，虎吼龍鳴騰上天。","東皇提昇紫微座，西皇佩下赤城田。","承平久息干戈事，僥幸得充文武備。","除災辟患宜君王，益壽延齡後天地。"]', '["吳山开，越溪涸，三金合冶成寶鍔。","淬綠水，鑒紅云，五采焰起光氛氳。","背上銘爲万年字，胸前点作七星文。","龟甲參差白虹色，轆轤宛轉黄金飾。","駭犀中斷寧方利，駿马羣騑未擬直。","风霜凜凜匣上清，精氣遙遙斗间明。","避災朝穿晉帝屋，逃亂夜入楚王城。","一朝運偶逢大仙，虎吼龙鳴腾上天。","东皇提昇紫微座，西皇佩下赤城田。","承平久息干戈事，僥幸得充文武備。","除災辟患宜君王，益壽延齡後天地。"]', '诗', 'shi', '', NULL, '寶劒篇 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dca19e8f-f8ce-40ce-a7f9-be985ba6d438', '汾陰行', '汾陰行', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["君不見昔日西京全盛時，汾陰后土親祭祠。","齋宮宿寢設儲供，撞鐘鳴鼓樹羽旂。","漢家五葉才且雄，賓延萬靈朝九戎。","栢梁賦詩高宴罷，詔書法駕幸河東。","河東太守親掃除，奉迎至尊導鑾輿。","五營夾道列容衞，三河縱觀空里閭。","回旌駐蹕降靈場，焚香奠醑邀百祥。","金鼎發色正焜煌，靈祇煒燁攄景光。","埋玉陳牲禮神畢，舉麾上馬乘輿出。","彼汾之曲嘉可遊，木蘭爲楫桂爲舟。","櫂歌微吟綵鷁浮，簫鼓哀鳴白雲秋。","歡娛宴洽賜羣后，家家復除戶牛酒。","聲明動天樂無有，千秋萬歲南山壽。","自從天子向秦關，玉輦金車不復還。","珠簾羽扇長寂寞，鼎湖龍髯安可攀。","千齡人事一朝空，四海爲家此路窮。","豪雄意氣今何在，壇場宮館盡蒿篷。","路逢故老長歎息，世事回環不可測。","昔時青樓對歌舞，今日黃埃聚荆棘。","山川滿目淚沾衣，富貴榮華能幾時。","不見秪今汾水上，唯有年年秋雁飛。"]', '["君不见昔日西京全盛时，汾陰后土親祭祠。","斋宮宿寢設儲供，撞鐘鳴鼓樹羽旂。","漢家五葉才且雄，賓延万靈朝九戎。","栢梁賦诗高宴罷，詔书法駕幸河东。","河东太守親掃除，奉迎至尊導鑾輿。","五營夾道列容衞，三河縱观空里閭。","回旌駐蹕降靈場，焚香奠醑邀百祥。","金鼎發色正焜煌，靈祇煒燁攄景光。","埋玉陳牲禮神畢，舉麾上马乘輿出。","彼汾之曲嘉可游，木蘭爲楫桂爲舟。","櫂歌微吟綵鷁浮，簫鼓哀鳴白云秋。","歡娛宴洽賜羣后，家家复除戶牛酒。","声明动天乐無有，千秋万歲南山壽。","自從天子向秦关，玉輦金车不复還。","珠簾羽扇长寂寞，鼎湖龙髯安可攀。","千齡人事一朝空，四海爲家此路窮。","豪雄意氣今何在，壇場宮館尽蒿篷。","路逢故老长歎息，世事回环不可測。","昔时青楼对歌舞，今日黄埃聚荆棘。","山川满目泪沾衣，富貴榮华能幾时。","不见秪今汾水上，唯有年年秋雁飞。"]', '诗', 'shi', '', NULL, '汾陰行 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02c1a865-1cbf-48b0-aefd-4285bd77b47c', '中宗降誕日長寧公主滿月侍宴應制', '中宗降誕日长寧公主满月侍宴應制', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["神龍見像日，仙鳳養雛年。","大火乘天正，明珠對月圓。","作新金篋裏，歌奏玉筐前。","今日宜孫慶，還參祝壽篇。"]', '["神龙见像日，仙鳳養雛年。","大火乘天正，明珠对月圓。","作新金篋裏，歌奏玉筐前。","今日宜孫慶，還參祝壽篇。"]', '诗', 'shi', '', NULL, '中宗降誕日長寧公主滿月侍宴應制 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bad3565-fdda-4c12-a919-f2e68eccf285', '奉和送金城公主適西蕃應制', '奉和送金城公主適西蕃應制', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["漢帝撫戎臣，絲言命錦輪。","還將弄機女，遠嫁織皮人。","曲怨關山月，妝消道路塵。","所嗟穠李樹，空對小榆春。"]', '["漢帝撫戎臣，絲言命錦輪。","還將弄機女，远嫁织皮人。","曲怨关山月，妝消道路塵。","所嗟穠李樹，空对小榆春。"]', '诗', 'shi', '', NULL, '奉和送金城公主適西蕃應制 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cab413fe-a5b5-439b-8065-6fc0a4ca5ea1', '侍宴長寧公主東莊應制', '侍宴长寧公主东莊應制', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["別業臨青甸，鳴鑾降紫霄。","長筵鵷鷺集，仙管鳳皇調。","樹接南山近，煙含北渚遙。","承恩咸已醉，戀賞未還鑣。"]', '["別業臨青甸，鳴鑾降紫霄。","长筵鵷鷺集，仙管鳳皇調。","樹接南山近，煙含北渚遙。","承恩咸已醉，戀賞未還鑣。"]', '诗', 'shi', '', NULL, '侍宴長寧公主東莊應制 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('861e4eb6-926b-40a2-bf90-7307c462f092', '立春日侍宴內殿出剪綵花應制', '立春日侍宴內殿出剪綵花應制', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["早聞年欲至，剪綵學芳辰。","綴綠奇能似，裁紅巧逼真。","花從篋裏發，葉向手中春。","不與時光競，何名天上人。"]', '["早闻年欲至，剪綵学芳辰。","綴綠奇能似，裁紅巧逼真。","花從篋裏發，葉向手中春。","不與时光競，何名天上人。"]', '诗', 'shi', '', NULL, '立春日侍宴內殿出剪綵花應制 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8e4e120-548e-44df-8fec-df4ee2c5d575', '奉和人日清暉閣宴羣臣遇雪應制', '奉和人日清暉閣宴羣臣遇雪應制', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["三陽偏勝節，七日最靈辰。","行慶傳芳蟻，升高綴綵人。","階前蓂候月，樓上雪驚春。","今日銜天造，還疑上漢津。"]', '["三陽偏勝節，七日最靈辰。","行慶傳芳蟻，升高綴綵人。","階前蓂候月，楼上雪驚春。","今日銜天造，還疑上漢津。"]', '诗', 'shi', '', NULL, '奉和人日清暉閣宴羣臣遇雪應制 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f774630e-0941-4652-aa31-5a72a42d2f7e', '奉和春日遊苑喜雨應制', '奉和春日游苑喜雨應制', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["仙蹕九成臺，香筵萬壽杯。","一旬初降雨，二月早聞雷。","葉向朝隮密，花含宿潤開。","幸承天澤豫，無使日光催。"]', '["仙蹕九成台，香筵万壽杯。","一旬初降雨，二月早闻雷。","葉向朝隮密，花含宿潤开。","幸承天澤豫，無使日光催。"]', '诗', 'shi', '', NULL, '奉和春日遊苑喜雨應制 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3e06bae-060c-4d38-b3df-d7ccfbb2f921', '春日侍宴幸芙蓉園應制', '春日侍宴幸芙蓉园應制', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["年光竹裏遍，春色杏間遙。","煙氣籠青閣，流文蕩畫橋。","飛花隨蝶舞，豔曲伴鸎嬌。","今日陪歡豫，還疑陟紫霄。"]', '["年光竹裏遍，春色杏间遙。","煙氣籠青閣，流文蕩畫橋。","飞花隨蝶舞，豔曲伴鸎嬌。","今日陪歡豫，還疑陟紫霄。"]', '诗', 'shi', '', NULL, '春日侍宴幸芙蓉園應制 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('257cdf45-5dc4-4c49-91b9-eec1c7ca19f4', '甘露殿侍宴應制', '甘露殿侍宴應制', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["月宇臨丹地，雲窗網碧紗。","御筵陳桂醑，天酒酌榴花。","水向浮橋直，城連禁苑斜。","承恩恣歡賞，歸路滿煙霞。"]', '["月宇臨丹地，云窗網碧紗。","御筵陳桂醑，天酒酌榴花。","水向浮橋直，城連禁苑斜。","承恩恣歡賞，归路满煙霞。"]', '诗', 'shi', '', NULL, '甘露殿侍宴應制 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64d4a78b-bd8a-4e7f-a318-ff3247a1463d', '奉和七夕兩儀殿會宴應制', '奉和七夕兩儀殿會宴應制', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["靈匹三秋會，仙期七夕過。","查來人泛海，橋渡鵲填河。","帝縷升銀閣，天機罷玉梭。","誰言七襄詠，重入五弦歌。"]', '["靈匹三秋會，仙期七夕過。","查来人泛海，橋渡鵲填河。","帝縷升銀閣，天機罷玉梭。","誰言七襄詠，重入五弦歌。"]', '诗', 'shi', '', NULL, '奉和七夕兩儀殿會宴應制 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bcb4b16-cfc5-41f2-9b76-d97691ddf526', '奉和九月九日登慈恩寺浮圖應制', '奉和九月九日登慈恩寺浮圖應制', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["瑞塔千尋起，仙輿九日來。","萸房陳寶席，菊橤散花臺。","御氣鵬霄近，升高鳳野開。","天歌將梵樂，空裏共裴回。"]', '["瑞塔千尋起，仙輿九日来。","萸房陳寶席，菊橤散花台。","御氣鵬霄近，升高鳳野开。","天歌將梵乐，空裏共裴回。"]', '诗', 'shi', '', NULL, '奉和九月九日登慈恩寺浮圖應制 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6dde6faf-6d1e-4df6-ad52-1a892bf48f0c', '閏九月九日幸總持寺登浮圖應制', '閏九月九日幸總持寺登浮圖應制', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["閏節開重九，真遊下大千。","花寒仍薦菊，座晚更披蓮。","剎鳳回雕輦，帆虹間綵旃。","還將西梵曲，助入南薰弦。"]', '["閏節开重九，真游下大千。","花寒仍薦菊，座晚更披蓮。","剎鳳回雕輦，帆虹间綵旃。","還將西梵曲，助入南薰弦。"]', '诗', 'shi', '', NULL, '閏九月九日幸總持寺登浮圖應制 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bad29f0-8b21-4bb4-80cf-6670e004b5ec', '奉和驪山高頂寓目應制', '奉和驪山高頂寓目應制', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["步輦陟山巔，山高入紫煙。","忠臣還捧日，聖后欲捫天。","迥識平陵樹，低看華嶽蓮。","帝鄉應不遠，空見白雲懸。"]', '["步輦陟山巔，山高入紫煙。","忠臣還捧日，聖后欲捫天。","迥識平陵樹，低看华嶽蓮。","帝乡應不远，空见白云懸。"]', '诗', 'shi', '', NULL, '奉和驪山高頂寓目應制 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa99a2ab-bb6e-4e8c-ad08-0fcc2bfa840a', '遊禁苑陪幸臨渭亭遇雪應制', '游禁苑陪幸臨渭亭遇雪應制', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["同雲接野煙，飛雪暗長天。","拂樹添梅色，過樓助粉妍。","光含班女扇，韻入楚王弦。","六出迎仙藻，千箱荅瑞年。"]', '["同云接野煙，飞雪暗长天。","拂樹添梅色，過楼助粉妍。","光含班女扇，韻入楚王弦。","六出迎仙藻，千箱荅瑞年。"]', '诗', 'shi', '', NULL, '遊禁苑陪幸臨渭亭遇雪應制 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8501300f-e169-44da-9f2e-cc04cf778bd3', '幸白鹿觀應制', '幸白鹿观應制', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["駐蹕三天路，回旃萬仞谿。","真庭羣帝饗，洞府百靈棲。","玉酒仙壚釀，金方暗壁題。","佇看青鳥入，還陟紫雲梯。"]', '["駐蹕三天路，回旃万仞谿。","真庭羣帝饗，洞府百靈棲。","玉酒仙壚釀，金方暗壁題。","佇看青鸟入，還陟紫云梯。"]', '诗', 'shi', '', NULL, '幸白鹿觀應制 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80cf1172-9318-4cf0-8741-6dc63a19d038', '送沙門弘景道俊玄奘還荆州應制', '送沙门弘景道俊玄奘還荆州應制', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["三乘歸淨域，萬騎餞通莊。","就日離亭近，彌天別路長。","荆南旋杖鉢，渭北限津梁。","何日紆真果，還來入帝鄉。"]', '["三乘归淨域，万騎餞通莊。","就日離亭近，彌天別路长。","荆南旋杖鉢，渭北限津梁。","何日紆真果，還来入帝乡。"]', '诗', 'shi', '', NULL, '送沙門弘景道俊玄奘還荆州應制 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1c288ba-f606-4a59-a850-e7df1ebe42be', '酬杜五弟晴朝獨坐見贈', '酬杜五弟晴朝独坐见贈', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["平明坐虛館，曠望幾悠哉。","宿霧分空盡，朝光度隙來。","影低藤架密，香動藥闌開。","未展山陽會，空留池上杯。"]', '["平明坐虛館，曠望幾悠哉。","宿霧分空尽，朝光度隙来。","影低藤架密，香动藥闌开。","未展山陽會，空留池上杯。"]', '诗', 'shi', '', NULL, '酬杜五弟晴朝獨坐見贈 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffac2fd4-e154-4eeb-ada3-3cc1735bea48', '同賦山居七夕', '同賦山居七夕', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["明月青山夜，高天白露秋。","花庭開粉席，雲岫敞針樓。","石類支機影，池似泛槎流。","暫驚河女鵲，終狎野人鷗。"]', '["明月青山夜，高天白露秋。","花庭开粉席，云岫敞針楼。","石類支機影，池似泛槎流。","暫驚河女鵲，終狎野人鷗。"]', '诗', 'shi', '', NULL, '同賦山居七夕 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19987413-f4a9-43da-a091-327aebde5c73', '送崔主簿赴滄州', '送崔主簿赴滄州', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["紫陌追隨日，青門相見時。","宦遊從此去，離別幾年期。","芳桂尊中酒，幽蘭下調詞。","他鄉有明月，千里照相思。"]', '["紫陌追隨日，青门相见时。","宦游從此去，離別幾年期。","芳桂尊中酒，幽蘭下調词。","他乡有明月，千里照相思。"]', '诗', 'shi', '', NULL, '送崔主簿赴滄州 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7a91fc6-d915-414f-b66b-a2e7f3485026', '寒食清明日早赴王門率成', '寒食清明日早赴王门率成', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["遊客趨梁邸，朝光入楚臺。","槐煙乘曉散，榆火應春開。","日帶晴虹上，花隨早蝶來。","雄風乘令節，餘吹拂輕灰。"]', '["游客趨梁邸，朝光入楚台。","槐煙乘晓散，榆火應春开。","日带晴虹上，花隨早蝶来。","雄风乘令節，餘吹拂轻灰。"]', '诗', 'shi', '', NULL, '寒食清明日早赴王門率成 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ef951ff-84bb-4221-b9ef-21978e8ececa', '和周記室從駕曉發合璧宮', '和周記室從駕晓發合璧宮', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["濯龍春苑曙，翠鳳曉旗舒。","野色開煙後，山光澹月餘。","風長笳響咽，川迥騎行疎。","珠履陪仙駕，金聲振屬車。"]', '["濯龙春苑曙，翠鳳晓旗舒。","野色开煙後，山光澹月餘。","风长笳响咽，川迥騎行疎。","珠履陪仙駕，金声振屬车。"]', '诗', 'shi', '', NULL, '和周記室從駕曉發合璧宮 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7611627b-e638-44c1-90ff-df0a944989bb', '和杜侍御太清臺宿直旦有懷', '和杜侍御太清台宿直旦有懷', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["貂冠朝彩振，烏署曉光分。","欲嘯遷喬侶，先飛擲地文。","庭虛麥雨潤，林靜蕙風薰。","嵇駕終難仰，梁鳧且自羣。"]', '["貂冠朝彩振，烏署晓光分。","欲嘯遷喬侶，先飞擲地文。","庭虛麦雨潤，林静蕙风薰。","嵇駕終难仰，梁鳧且自羣。"]', '诗', 'shi', '', NULL, '和杜侍御太清臺宿直旦有懷 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5697d96-9c66-41cb-838d-11214b237e7a', '和杜學士江南初霽羈懷', '和杜学士江南初霽羈懷', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["大江開宿雨，征櫂下春流。","霧卷晴山出，風恬晚浪收。","岸花明水樹，川鳥亂沙洲。","羈眺傷千里，勞歌動四愁。"]', '["大江开宿雨，征櫂下春流。","霧卷晴山出，风恬晚浪收。","岸花明水樹，川鸟亂沙洲。","羈眺傷千里，勞歌动四愁。"]', '诗', 'shi', '', NULL, '和杜學士江南初霽羈懷 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0b41c44-e9c8-4729-936f-4bb2b9f22dd1', '晚景悵然簡二三子', '晚景悵然簡二三子', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["楚客秋悲動，梁臺夕望賒。","梧桐稍下葉，山桂欲開花。","氣引迎寒露，光收向晚霞。","長歌白水曲，空對綠池華。"]', '["楚客秋悲动，梁台夕望賒。","梧桐稍下葉，山桂欲开花。","氣引迎寒露，光收向晚霞。","长歌白水曲，空对綠池华。"]', '诗', 'shi', '', NULL, '晚景悵然簡二三子 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2024129c-f316-45ba-9804-f5ef95b019f1', '送李邕', '送李邕', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["落日荒郊外，風景正淒淒。","離人席上起，征馬路傍嘶。","別酒傾壺贈，行書掩淚題。","殷勤御溝水，從此各東西。"]', '["落日荒郊外，风景正淒淒。","離人席上起，征马路傍嘶。","別酒傾壺贈，行书掩泪題。","殷勤御溝水，從此各东西。"]', '诗', 'shi', '', NULL, '送李邕 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2eba40c5-1327-4592-abd3-eb22bfa16b1c', '又送別', '又送別', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["岐路方爲客，芳尊暫解顏。","人隨轉蓬去，春伴落梅還。","白雲度汾水，黃河遶晉關。","離心不可問，宿昔鬢成斑。"]', '["岐路方爲客，芳尊暫解顏。","人隨轉蓬去，春伴落梅還。","白云度汾水，黄河遶晉关。","離心不可问，宿昔鬢成斑。"]', '诗', 'shi', '', NULL, '又送別 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d9c9f88-bcc3-4149-8ae0-60c2e182465b', '餞駱四二首 一', '餞駱四二首 一', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["平生何以樂，斗酒夜相逢。","曲中驚別緒，醉裏失愁容。","星月懸秋漢，風霜入曙鐘。","明日臨溝水，青山幾萬重。"]', '["平生何以乐，斗酒夜相逢。","曲中驚別緒，醉裏失愁容。","星月懸秋漢，风霜入曙鐘。","明日臨溝水，青山幾万重。"]', '诗', 'shi', '', NULL, '餞駱四二首 一 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db2da569-09f8-42ad-bd3a-996529f5b1b7', '餞駱四二首 二', '餞駱四二首 二', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["甲第驅車入，良宵秉燭遊。","人追竹林會，酒獻菊花秋。","霜吹飄無已，星河漫不流。","重嗟歡賞地，翻召別離憂。"]', '["甲第驱车入，良宵秉燭游。","人追竹林會，酒獻菊花秋。","霜吹飄無已，星河漫不流。","重嗟歡賞地，翻召別離憂。"]', '诗', 'shi', '', NULL, '餞駱四二首 二 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9a8ab76-a369-4b8e-a6b9-1770b8018d6e', '春日遊苑喜雨應詔', '春日游苑喜雨應詔', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["園樓春正歸，入苑弄芳菲。","密雨迎僊步，低雲拂御衣。","危花霑易落，度鳥濕難飛。","膏澤登千庾，歡情徧九圍。"]', '["园楼春正归，入苑弄芳菲。","密雨迎僊步，低云拂御衣。","危花霑易落，度鸟濕难飞。","膏澤登千庾，歡情徧九圍。"]', '诗', 'shi', '', NULL, '春日遊苑喜雨應詔 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95702f89-19a0-448b-a0fe-cc656f44a783', '九日應制得歡字', '九日應制得歡字', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["令節三秋晚，重陽九日歡。","仙杯還泛菊，寶饌且調蘭。","御氣雲霄近，乘高宇宙寬。","今朝萬壽引，宜向曲中彈。"]', '["令節三秋晚，重陽九日歡。","仙杯還泛菊，寶饌且調蘭。","御氣云霄近，乘高宇宙寬。","今朝万壽引，宜向曲中彈。"]', '诗', 'shi', '', NULL, '九日應制得歡字 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0e0af00-bcf4-4b3b-92e5-02a6fb564296', '二月奉教作', '二月奉教作', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["柳陌鸎初囀，梅梁燕始歸。","和風泛紫若，柔露濯青薇。","日豔臨花影，霞翻入浪暉。","乘春重遊豫，淹賞玩芳菲。"]', '["柳陌鸎初囀，梅梁燕始归。","和风泛紫若，柔露濯青薇。","日豔臨花影，霞翻入浪暉。","乘春重游豫，淹賞玩芳菲。"]', '诗', 'shi', '', NULL, '二月奉教作 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('072c18d5-eac6-4a4d-a788-8655a0358639', '三月奉教作', '三月奉教作', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["銀井桐花發，金堂草色齊。","韶光愛日宇，淑氣滿風蹊。","蝶影將花亂，虹文向水低。","芳春隨意晚，佳賞日無暌。"]', '["銀井桐花發，金堂草色齊。","韶光愛日宇，淑氣满风蹊。","蝶影將花亂，虹文向水低。","芳春隨意晚，佳賞日無暌。"]', '诗', 'shi', '', NULL, '三月奉教作 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71061eb6-20eb-4e17-91df-cef021034b8e', '四月奉教作', '四月奉教作', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["暄籥三春謝，炎鍾九夏初。","潤浮梅雨夕，涼散麥風餘。","葉暗庭幃滿，花殘院錦疎。","勝情多賞託，尊酒狎林箊。"]', '["暄籥三春謝，炎鍾九夏初。","潤浮梅雨夕，涼散麦风餘。","葉暗庭幃满，花殘院錦疎。","勝情多賞託，尊酒狎林箊。"]', '诗', 'shi', '', NULL, '四月奉教作 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3b5afe9-9af2-4597-ab55-31db2e3ad545', '五月奉教作', '五月奉教作', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["綠樹炎氛滿，朱樓夏景長。","池含凍雨氣，山映火雲光。","果院新櫻熟，花庭曙槿芳。","欲逃三伏暑，還泛十旬觴。"]', '["綠樹炎氛满，朱楼夏景长。","池含凍雨氣，山映火云光。","果院新櫻熟，花庭曙槿芳。","欲逃三伏暑，還泛十旬觴。"]', '诗', 'shi', '', NULL, '五月奉教作 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('516fe641-8a97-40eb-b164-4e44b9128dc7', '六月奉教作', '六月奉教作', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["養日暫裴回，畏景尚悠哉。","避暑移琴席，追涼□□□。","竹風依扇動，桂酒溢壺開。","勞餌□飛雪，自可□□□。"]', '["養日暫裴回，畏景尚悠哉。","避暑移琴席，追涼□□□。","竹风依扇动，桂酒溢壺开。","勞餌□飞雪，自可□□□。"]', '诗', 'shi', '', NULL, '六月奉教作 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afc65b07-68d3-4ff6-9fd6-a53e1ee89ba0', '八月奉教作', '八月奉教作', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["黃葉秋風起，蒼葭曉露團。","鶴鳴初警候，雁上欲凌寒。","月鏡如開匣，雲纓似綴冠。","清尊對旻序，高宴有餘歡。"]', '["黄葉秋风起，蒼葭晓露團。","鹤鳴初警候，雁上欲凌寒。","月镜如开匣，云纓似綴冠。","清尊对旻序，高宴有餘歡。"]', '诗', 'shi', '', NULL, '八月奉教作 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f383c99-e796-4e52-84d5-ff71677c9761', '九月奉教作', '九月奉教作', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["曲池朝下雁，幽砌夕吟蛩。","葉徑蘭芳盡，花潭菊氣濃。","寒催四序律，霜度九秋鐘。","還當明月夜，飛蓋遠相從。"]', '["曲池朝下雁，幽砌夕吟蛩。","葉徑蘭芳尽，花潭菊氣濃。","寒催四序律，霜度九秋鐘。","還當明月夜，飞蓋远相從。"]', '诗', 'shi', '', NULL, '九月奉教作 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('930b9d56-1168-4035-936f-01e03b082803', '十月奉教作', '十月奉教作', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["白藏初送節，玄律始迎冬。","林枯黃葉盡，水耗綠池空。","霜待臨庭月，寒隨入牖風。","別有歡娛地，歌舞應絲桐。"]', '["白藏初送節，玄律始迎冬。","林枯黄葉尽，水耗綠池空。","霜待臨庭月，寒隨入牖风。","別有歡娛地，歌舞應絲桐。"]', '诗', 'shi', '', NULL, '十月奉教作 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f5738cb-d473-4ce1-9437-7c2bd18b83da', '十一月奉教作', '十一月奉教作', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["凝陰結暮序，嚴氣肅長飆。","霜犯狐裘夕，寒侵獸火朝。","冰深遙架浦，雪凍近封條。","平原已從獵，日暮整還鑣。"]', '["凝陰結暮序，嚴氣肅长飆。","霜犯狐裘夕，寒侵獸火朝。","冰深遙架浦，雪凍近封條。","平原已從獵，日暮整還鑣。"]', '诗', 'shi', '', NULL, '十一月奉教作 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f36a8c6-04ac-4cfd-9974-0b84358a32ed', '十二月奉教作', '十二月奉教作', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["玉燭年行盡，銅史漏猶長。","池冷凝宵凍，庭寒積曙霜。","蘭心未動色，梅館欲含芳。","裴回臨歲晚，顧步佇春光。"]', '["玉燭年行尽，銅史漏猶长。","池冷凝宵凍，庭寒積曙霜。","蘭心未动色，梅館欲含芳。","裴回臨歲晚，顧步佇春光。"]', '诗', 'shi', '', NULL, '十二月奉教作 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7af8ce3e-3a5b-4ed5-9ce3-fa1bc19fd69e', '和麴典設扈從東郊憶弟使往安西冬至日恨不得同申拜慶', '和麴典設扈從东郊憶弟使往安西冬至日恨不得同申拜慶', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["玉關方叱馭，桂苑正陪輿。","桓嶺嗟分翼，姜川限饋魚。","雪花含□晚，雲葉帶荆舒。","重此西流詠，彌傷南至初。"]', '["玉关方叱馭，桂苑正陪輿。","桓嶺嗟分翼，姜川限饋鱼。","雪花含□晚，云葉带荆舒。","重此西流詠，彌傷南至初。"]', '诗', 'shi', '', NULL, '和麴典設扈從東郊憶弟使往安西冬至日恨不得同申拜慶 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d0d13d4-83a6-4177-aa0e-5e588f78f796', '馬武騎挽歌二首 一', '马武騎挽歌二首 一', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["五日皆休沐，三泉獨不歸。","池臺金闕是，尊酒玳筵非。","巷靜遊禽入，門閑過客稀。","唯餘昔年鳳，尚繞故樓飛。"]', '["五日皆休沐，三泉独不归。","池台金闕是，尊酒玳筵非。","巷静游禽入，门闲過客稀。","唯餘昔年鳳，尚繞故楼飞。"]', '诗', 'shi', '', NULL, '馬武騎挽歌二首 一 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('064ab8b3-6898-4e84-aa78-408fe2be7ac9', '馬武騎挽歌二首 二', '马武騎挽歌二首 二', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["昔下天津館，嘗過帝子家。","夜傾金屋酒，春舞玉臺花。","試馬依紅埒，吹簫弄紫霞。","誰言東郭路，翻枉北門車。"]', '["昔下天津館，嘗過帝子家。","夜傾金屋酒，春舞玉台花。","試马依紅埒，吹簫弄紫霞。","誰言东郭路，翻枉北门车。"]', '诗', 'shi', '', NULL, '馬武騎挽歌二首 二 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3239b301-a418-45b5-87b8-00492651e264', '武三思挽歌', '武三思挽歌', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["玉匣金爲縷，銀鉤石作銘。","短歌傷薤曲，長暮泣松扃。","事往昏朝霧，人亡折夜星。","忠賢良可惜，圖畫入丹青。"]', '["玉匣金爲縷，銀鉤石作銘。","短歌傷薤曲，长暮泣松扃。","事往昏朝霧，人亡折夜星。","忠賢良可惜，圖畫入丹青。"]', '诗', 'shi', '', NULL, '武三思挽歌 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3607ff5a-e037-4337-a24d-24f1e1759221', '天官崔侍郎夫人吳氏挽歌', '天官崔侍郎夫人吳氏挽歌', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["寵服當年盛，芳魂此地窮。","劒飛龍匣在，人去鵲巢空。","簟愴孤生竹，琴哀半死桐。","唯當青史上，千載仰嬪風。"]', '["寵服當年盛，芳魂此地窮。","劒飞龙匣在，人去鵲巢空。","簟愴孤生竹，琴哀半死桐。","唯當青史上，千載仰嬪风。"]', '诗', 'shi', '', NULL, '天官崔侍郎夫人吳氏挽歌 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1364291-6d58-466c-b46f-faae0adf59aa', '日', '日', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["旦出扶桑路，遙升若木枝。","雲間五色滿，霞際九光披。","東陸蒼龍駕，南郊赤羽馳。","傾心比葵藿，朝夕奉光曦。"]', '["旦出扶桑路，遙升若木枝。","云间五色满，霞際九光披。","东陸蒼龙駕，南郊赤羽驰。","傾心比葵藿，朝夕奉光曦。"]', '诗', 'shi', '', NULL, '日 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0485ad4-b598-4e69-99ca-bcce11ca3832', '月', '月', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["桂滿三五夕，蓂開二八時。","清輝飛鵲鑑，新影學蛾眉。","皎潔臨疎牖，玲瓏鑒薄帷。","願言從愛客，清夜幸同嬉。"]', '["桂满三五夕，蓂开二八时。","清輝飞鵲鑑，新影学蛾眉。","皎潔臨疎牖，玲瓏鑒薄帷。","願言從愛客，清夜幸同嬉。"]', '诗', 'shi', '', NULL, '月 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7afa7030-e4d8-4ce0-a3ae-540aef6b119d', '星', '星', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["蜀郡靈槎轉，豐城寶劒新。","將軍臨北塞，天子入西秦。","未作三台輔，寧爲五老臣。","今宵潁川曲，誰識聚賢人。"]', '["蜀郡靈槎轉，豐城寶劒新。","將軍臨北塞，天子入西秦。","未作三台輔，寧爲五老臣。","今宵潁川曲，誰識聚賢人。"]', '诗', 'shi', '', NULL, '星 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3d0326f-748b-47ef-b48f-7f919dc51fca', '風', '风', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["落日生蘋末，搖揚徧遠林。","帶花疑鳳舞，向竹似龍吟。","月動臨秋扇，松清入夜琴。","若至蘭臺下，還拂楚王襟。"]', '["落日生蘋末，搖揚徧远林。","带花疑鳳舞，向竹似龙吟。","月动臨秋扇，松清入夜琴。","若至蘭台下，還拂楚王襟。"]', '诗', 'shi', '', NULL, '風 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fc3e743-366e-48da-b287-47f1377afdea', '雲', '云', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["英英大梁國，郁郁秘書臺。","碧落從龍起，青山觸石來。","官名光邃古，蓋影耿輕埃。","飛感高歌發，威加四海回。"]', '["英英大梁国，郁郁秘书台。","碧落從龙起，青山觸石来。","官名光邃古，蓋影耿轻埃。","飞感高歌發，威加四海回。"]', '诗', 'shi', '', NULL, '雲 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36b348f8-723b-46ac-ad1f-718975d7c9b3', '煙', '煙', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["瑞氣凌青閣，空濛上翠微。","迥浮雙闕路，遙拂九仙衣。","桑柘迎寒色，松篁暗晚暉。","還當紫霄上，時接彩鸞飛。"]', '["瑞氣凌青閣，空濛上翠微。","迥浮雙闕路，遙拂九仙衣。","桑柘迎寒色，松篁暗晚暉。","還當紫霄上，时接彩鸾飞。"]', '诗', 'shi', '', NULL, '煙 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9beca84-e112-4d0e-ad6d-38bdf19cb73c', '露', '露', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["滴瀝明花苑，葳蕤泫竹叢。","玉垂丹棘上，珠湛綠荷中。","夜警千年鶴，朝零七月風。","願凝仙掌內，長奉未央宮。"]', '["滴瀝明花苑，葳蕤泫竹叢。","玉垂丹棘上，珠湛綠荷中。","夜警千年鹤，朝零七月风。","願凝仙掌內，长奉未央宮。"]', '诗', 'shi', '', NULL, '露 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14c5e015-a89f-4d2e-940e-6a6f5a73a5e1', '霧', '霧', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["曹公迷楚澤，漢帝出平城。","涿鹿妖氛靜，丹山霽色明。","類煙飛稍重，方雨散還輕。","倘入非熊兆，寧思玄豹情。"]', '["曹公迷楚澤，漢帝出平城。","涿鹿妖氛静，丹山霽色明。","類煙飞稍重，方雨散還轻。","倘入非熊兆，寧思玄豹情。"]', '诗', 'shi', '', NULL, '霧 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d75523f4-e43d-4058-9ab5-fd687da6eeaf', '雨', '雨', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["西北雲膚起，東南雨足來。","靈童出海見，神女向臺回。","斜影風前合，圓文水上開。","十旬無破塊，九土信康哉。"]', '["西北云膚起，东南雨足来。","靈童出海见，神女向台回。","斜影风前合，圓文水上开。","十旬無破塊，九土信康哉。"]', '诗', 'shi', '', NULL, '雨 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b64674e-d343-4280-aa6a-7f627a3199f0', '雪', '雪', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["瑞雪驚千里，同雲暗九霄。","地疑明月夜，山似白雲朝。","逐舞花光動，臨歌扇影飄。","大周天闕路，今日海神朝。"]', '["瑞雪驚千里，同云暗九霄。","地疑明月夜，山似白云朝。","逐舞花光动，臨歌扇影飄。","大周天闕路，今日海神朝。"]', '诗', 'shi', '', NULL, '雪 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa89d51f-0825-4ca4-b1bf-2ba82f6df85f', '山', '山', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["地鎮標神秀，峩峩上翠氛。","泉飛一道帶，峰出半天雲。","古壁丹青色，新花綺繡紋。","已開封禪所，希謁聖明君。"]', '["地鎮標神秀，峩峩上翠氛。","泉飞一道带，峰出半天云。","古壁丹青色，新花綺繡紋。","已开封禪所，希謁聖明君。"]', '诗', 'shi', '', NULL, '山 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e35050b4-a0a9-4139-9cef-988035c989b7', '石', '石', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["宗子維城固，將軍飲羽威。","巖花鑑裏發，雲葉錦中飛。","入宋星初隕，過湘燕早歸。","倘因持補極，寧復想支機。"]', '["宗子維城固，將軍饮羽威。","巖花鑑裏發，云葉錦中飞。","入宋星初隕，過湘燕早归。","倘因持補極，寧复想支機。"]', '诗', 'shi', '', NULL, '石 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0517344d-0a33-4886-b6ef-8500130c0843', '原', '原', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["王粲銷憂日，江淹起恨年。","帶川遙綺錯，分隰迥阡眠。","□□橫周甸，莓苔闕晉田。","方知急難響，長在脊令篇。"]', '["王粲銷憂日，江淹起恨年。","带川遙綺錯，分隰迥阡眠。","□□橫周甸，莓苔闕晉田。","方知急难响，长在脊令篇。"]', '诗', 'shi', '', NULL, '原 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4ca0c33-b893-44d1-8595-7843bb245d6b', '野', '野', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["鳳出秦郊迥，鶉飛楚塞空。","蒼梧雲影去，涿鹿霧光通。","草暗少原綠，花明入蜀紅。","誰言版築士，猶處傅巖中。"]', '["鳳出秦郊迥，鶉飞楚塞空。","蒼梧云影去，涿鹿霧光通。","草暗少原綠，花明入蜀紅。","誰言版築士，猶处傅巖中。"]', '诗', 'shi', '', NULL, '野 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff79eefc-5a5c-47ad-8ff8-4ca20623c199', '田', '田', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["貢禹懷書日，張衡作賦辰。","杏花開鳳軫，菖葉布龍鱗。","瑞麥兩岐秀，嘉禾同穎新。","寧知帝王力，擊壤自安貧。"]', '["貢禹懷书日，張衡作賦辰。","杏花开鳳軫，菖葉布龙鱗。","瑞麦兩岐秀，嘉禾同穎新。","寧知帝王力，擊壤自安貧。"]', '诗', 'shi', '', NULL, '田 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ec0acdd-6c4a-44bc-b3c4-b747333038e8', '道', '道', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["銅駝分鞏洛，劒閣低臨邛。","紫徼三千里，青樓十二重。","玉關塵似雪，金穴馬如龍。","今日中衢上，堯尊更可逢。"]', '["銅駝分鞏洛，劒閣低臨邛。","紫徼三千里，青楼十二重。","玉关塵似雪，金穴马如龙。","今日中衢上，堯尊更可逢。"]', '诗', 'shi', '', NULL, '道 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('449c1e29-4d2f-4c39-844f-ed9c871fe86b', '海', '海', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["習坎疏丹壑，朝宗合紫微。","三山巨鰲湧，萬里大鵬飛。","樓寫春雲色，珠含明月輝。","會因添霧露，方逐衆川歸。"]', '["習坎疏丹壑，朝宗合紫微。","三山巨鰲湧，万里大鵬飞。","楼寫春云色，珠含明月輝。","會因添霧露，方逐衆川归。"]', '诗', 'shi', '', NULL, '海 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d781f001-b6ff-4295-a46e-29549cd91b3a', '江', '江', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["日夕三江望，靈潮萬里回。","霞津錦浪動，月浦練花開。","湍似黃牛去，濤從白馬來。","英靈已傑出，誰識卿雲才。"]', '["日夕三江望，靈潮万里回。","霞津錦浪动，月浦練花开。","湍似黄牛去，濤從白马来。","英靈已傑出，誰識卿云才。"]', '诗', 'shi', '', NULL, '江 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f3275bc-c175-405d-b572-283f14ee0393', '河', '河', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["源出崑崙中，長波接漢空。","桃花來馬頰，竹箭入龍宮。","德水千年變，榮光五色通。","若披蘭葉檢，□□□□□。"]', '["源出崑崙中，长波接漢空。","桃花来马頰，竹箭入龙宮。","德水千年变，榮光五色通。","若披蘭葉檢，□□□□□。"]', '诗', 'shi', '', NULL, '河 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4948865b-2700-46bc-9db5-3d99ec79887d', '洛', '洛', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["九洛韶光媚，三川物候新。","花明丹鳳浦，日映玉雞津。","元禮期仙客，陳王覩麗人。","神龜方錫瑞，綠字重來臻。"]', '["九洛韶光媚，三川物候新。","花明丹鳳浦，日映玉雞津。","元禮期仙客，陳王覩丽人。","神龟方錫瑞，綠字重来臻。"]', '诗', 'shi', '', NULL, '洛 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ac89ae6-497f-4c7f-9f72-b394e87da15f', '城', '城', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["四塞稱天府，三河建洛都。","飛雲靄層闕，白日麗南隅。","獨下仙人鳳，羣驚御史烏。","何辭一萬里，邊徼捍匈奴。"]', '["四塞稱天府，三河建洛都。","飞云靄層闕，白日丽南隅。","独下仙人鳳，羣驚御史烏。","何辞一万里，邊徼捍匈奴。"]', '诗', 'shi', '', NULL, '城 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58adb9ca-7b50-420b-8216-a08ac25142b8', '門', '门', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["奕奕彤闈下，煌煌紫禁隈。","阿房萬戶列，閶闔九重開。","疏廣遺榮去，于公待駟來。","詎知金馬側，方朔有奇才。"]', '["奕奕彤闈下，煌煌紫禁隈。","阿房万戶列，閶闔九重开。","疏廣遺榮去，于公待駟来。","詎知金马側，方朔有奇才。"]', '诗', 'shi', '', NULL, '門 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c8547d4-2957-40a2-b8a7-641533a0dfd5', '市', '市', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["闤闠開三市，旗亭起百尋。","漸離初擊筑，司馬正彈琴。","細柳龍鱗映，長槐兔月陰。","徒知觀衞玉，詎肯挂秦[金]。"]', '["闤闠开三市，旗亭起百尋。","漸離初擊筑，司马正彈琴。","細柳龙鱗映，长槐兔月陰。","徒知观衞玉，詎肯挂秦[金]。"]', '诗', 'shi', '', NULL, '市 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2eec472e-c0a4-4f1b-acfa-fc7c70bfa613', '井', '井', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["玉甃談仙客，銅臺賞魏君。","蜀都宵映火，杞國旦生雲。","向日蓮花淨，含風李樹薰。","已開千里國，還聚五星文。"]', '["玉甃談仙客，銅台賞魏君。","蜀都宵映火，杞国旦生云。","向日蓮花淨，含风李樹薰。","已开千里国，還聚五星文。"]', '诗', 'shi', '', NULL, '井 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8a983e7-7949-46b4-850a-0ee9bd8b1dc5', '宅', '宅', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["寂寞蓬蒿徑，喧喧湫隘廬。","屢逢長者轍，時引故人車。","孟母遷鄰罷，將軍辭第初。","誰憐草玄處，獨對一牀書。"]', '["寂寞蓬蒿徑，喧喧湫隘廬。","屢逢长者轍，时引故人车。","孟母遷鄰罷，將軍辞第初。","誰怜草玄处，独对一牀书。"]', '诗', 'shi', '', NULL, '宅 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a90fe0d-cdca-4791-a39d-2f7267de596a', '池', '池', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["綵櫂浮太液，清觸醉習家。","詩情對明月，雲曲拂流霞。","煙散龍形淨，波含鳳影斜。","安仁動秋興，魚鳥思空賒。"]', '["綵櫂浮太液，清觸醉習家。","诗情对明月，云曲拂流霞。","煙散龙形淨，波含鳳影斜。","安仁动秋兴，鱼鸟思空賒。"]', '诗', 'shi', '', NULL, '池 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('643e4251-5f95-42f7-a47b-3cd8f22a5788', '樓', '楼', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["百尺重城際，千尋大道隈。","漢宮井幹起，吳國落星開。","笛怨綠珠去，簫隨弄玉來。","銷憂聊暇日，誰識仲宣才。"]', '["百尺重城際，千尋大道隈。","漢宮井幹起，吳国落星开。","笛怨綠珠去，簫隨弄玉来。","銷憂聊暇日，誰識仲宣才。"]', '诗', 'shi', '', NULL, '樓 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88e4583d-fed2-475f-94b3-a84942ca27e5', '橋', '橋', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["烏鵲填應滿，黃公去不歸。","勢疑虹始見，形似雁初飛。","妙應七星制，高分半月輝。","秦王空構石，仙島遠難依。"]', '["烏鵲填應满，黄公去不归。","勢疑虹始见，形似雁初飞。","妙應七星制，高分半月輝。","秦王空構石，仙島远难依。"]', '诗', 'shi', '', NULL, '橋 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84c62f31-3a77-4034-92f0-20969583331b', '經', '經', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["漢室鴻儒盛，鄒堂大義明。","五千道德闡，三百禮儀成。","青紫方拾芥，黃金徒滿籝。","誰知懷逸辯，重席冠羣英。"]', '["漢室鴻儒盛，鄒堂大義明。","五千道德闡，三百禮儀成。","青紫方拾芥，黄金徒满籝。","誰知懷逸辯，重席冠羣英。"]', '诗', 'shi', '', NULL, '經 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57dc272c-0712-4be2-b101-039370e751d8', '史', '史', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["馬記天官設，班圖地里新。","善談方亹亹，青簡見彬彬。","方朔初聞漢，荆軻昔向秦。","正辭堪載筆，終翼作良臣。"]', '["马記天官設，班圖地里新。","善談方亹亹，青簡见彬彬。","方朔初闻漢，荆軻昔向秦。","正辞堪載笔，終翼作良臣。"]', '诗', 'shi', '', NULL, '史 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e8a2600-17dc-42a7-877f-a9bd9903fbc8', '詩', '诗', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["都尉仙鳧遠，梁王駟馬來。","扇中紈素製，機上錦紋回。","天子三章傳，陳王七步才。","緇衣久擅美，祖德信悠哉。"]', '["都尉仙鳧远，梁王駟马来。","扇中紈素製，機上錦紋回。","天子三章傳，陳王七步才。","緇衣久擅美，祖德信悠哉。"]', '诗', 'shi', '', NULL, '詩 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c9991b7-27bc-475d-ab9b-0bd823a3a262', '賦', '賦', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["布義孫卿子，登高楚屈平。","銅臺初下筆，樂觀正飛纓。","乍有凌雲勢，時聞擲地聲。","造端長體物，無復大夫名。"]', '["布義孫卿子，登高楚屈平。","銅台初下笔，乐观正飞纓。","乍有凌云勢，时闻擲地声。","造端长體物，無复大夫名。"]', '诗', 'shi', '', NULL, '賦 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f94dca29-03ac-46b6-819f-735420ba9e15', '書', '书', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["削簡龍文見，臨池鳥跡舒。","河圖八卦出，洛範九疇初。","垂露春光滿，崩雲骨氣餘。","請君看入木，一寸乃非虛。"]', '["削簡龙文见，臨池鸟跡舒。","河圖八卦出，洛範九疇初。","垂露春光满，崩云骨氣餘。","請君看入木，一寸乃非虛。"]', '诗', 'shi', '', NULL, '書 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6264d50d-694c-4bc9-ba05-478b7112b38b', '檄', '檄', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["羽檄本宣明，由來□木聲。","聯翩至漢國，迢遞入燕營。","毛義持書去，張儀韞璧行。","曹風雖覺愈，陳草始知名。"]', '["羽檄本宣明，由来□木声。","聯翩至漢国，迢遞入燕營。","毛義持书去，張儀韞璧行。","曹风雖覺愈，陳草始知名。"]', '诗', 'shi', '', NULL, '檄 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78336beb-4303-44ee-9bdb-a73a60d10632', '紙', '紙', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["妙跡蔡侯施，芳名左伯馳。","雲飛錦綺落，花發縹紅披。","舒卷隨幽顯，廉方合軌儀。","莫驚反掌字，當取葛洪規。"]', '["妙跡蔡侯施，芳名左伯驰。","云飞錦綺落，花發縹紅披。","舒卷隨幽显，廉方合軌儀。","莫驚反掌字，當取葛洪規。"]', '诗', 'shi', '', NULL, '紙 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49ff9409-dfa1-453f-bda0-99338c887827', '筆', '笔', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["握管門庭側，含毫山水隈。","霜輝簡上發，錦字夢中開。","鸚鵡摛文至，麒麟絕句來。","何當遇良史，左右振奇才。"]', '["握管门庭側，含毫山水隈。","霜輝簡上發，錦字梦中开。","鸚鵡摛文至，麒麟絕句来。","何當遇良史，左右振奇才。"]', '诗', 'shi', '', NULL, '筆 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aaa3bb77-c811-4b28-9f52-7483ae920a58', '硯', '硯', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["左思裁賦日，王充作論年。","光隨錦文發，形帶石巖圓。","積潤循毫裏，開池小學前。","君苗徒見爇，誰詠士衡篇。"]', '["左思裁賦日，王充作論年。","光隨錦文發，形带石巖圓。","積潤循毫裏，开池小学前。","君苗徒见爇，誰詠士衡篇。"]', '诗', 'shi', '', NULL, '硯 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e63a4bef-7dd3-4b75-bdda-864a939129e2', '墨', '墨', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["長安分石炭，上黨結松心。","遶畫蠅初落，含滋綬更深。","悲絲光易染，疊素彩還沈。","別有張芝學，書池幸見臨。"]', '["长安分石炭，上黨結松心。","遶畫蠅初落，含滋綬更深。","悲絲光易染，叠素彩還沈。","別有張芝学，书池幸见臨。"]', '诗', 'shi', '', NULL, '墨 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7957a3ac-59fb-4e4b-9077-a7235a312295', '劒', '劒', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["我有昆吾劒，求趨夫子庭。","白虹時切玉，紫氣夜干星。","鍔上芙蓉動，匣中霜雪明。","倚天持報國，畫地取雄名。"]', '["我有昆吾劒，求趨夫子庭。","白虹时切玉，紫氣夜干星。","鍔上芙蓉动，匣中霜雪明。","倚天持報国，畫地取雄名。"]', '诗', 'shi', '', NULL, '劒 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84bc68a8-84c6-46a6-a266-318f3806426a', '刀', '刀', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["列辟鳴鸞至，惟良佩犢旋。","帶環疑寫月，引鑑似含泉。","入夢華梁上，含鋒彩筆前。","莫驚開百鍊，特擬定三邊。"]', '["列辟鳴鸾至，惟良佩犢旋。","带环疑寫月，引鑑似含泉。","入梦华梁上，含鋒彩笔前。","莫驚开百鍊，特擬定三邊。"]', '诗', 'shi', '', NULL, '刀 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03cc350a-cb78-45b5-b965-2d68e098b9fa', '箭', '箭', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["漢甸初收羽，燕城忽解圍。","影隨流水急，光帶落星飛。","夏列三成範，堯沈九日輝。","斷蛟雲夢澤，希爲識忘歸。"]', '["漢甸初收羽，燕城忽解圍。","影隨流水急，光带落星飞。","夏列三成範，堯沈九日輝。","斷蛟云梦澤，希爲識忘归。"]', '诗', 'shi', '', NULL, '箭 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfd16646-8adb-4141-9611-cd1676ceaaf0', '彈', '彈', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["俠客持蘇合，佳遊滿帝鄉。","避丸深可誚，求炙遂難忘。","金迸疑星落，珠沈似月光。","誰知少孺子，將此見吳王。"]', '["俠客持蘇合，佳游满帝乡。","避丸深可誚，求炙遂难忘。","金迸疑星落，珠沈似月光。","誰知少孺子，將此见吳王。"]', '诗', 'shi', '', NULL, '彈 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('941b344e-9012-4f27-8e13-8794df431dc4', '弩', '弩', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["挺質本軒皇，申威振遠方。","機張驚雉雊，玉彩耀星芒。","高鳥行應盡，清猿坐見傷。","蘇秦六百步，持此說韓王。"]', '["挺質本軒皇，申威振远方。","機張驚雉雊，玉彩耀星芒。","高鸟行應尽，清猿坐见傷。","蘇秦六百步，持此说韓王。"]', '诗', 'shi', '', NULL, '弩 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fc25265-ce6b-4c35-9045-4bc74c6c9435', '旗', '旗', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["桂影承宵月，虹輝接曙雲。","縱橫齊八陣，舒卷引三軍。","日薄蛟龍影，風翻鳥隼文。","誰知懷勇志，蟠地幾繽紛。"]', '["桂影承宵月，虹輝接曙云。","縱橫齊八陣，舒卷引三軍。","日薄蛟龙影，风翻鸟隼文。","誰知懷勇志，蟠地幾繽紛。"]', '诗', 'shi', '', NULL, '旗 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43cc3e5d-0580-449f-89dc-2286e97384f5', '旌', '旌', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["告善康莊側，求賢市肆中。","擁麾分彩雉，持節曳丹虹。","影麗天山雪，光搖朔塞風。","方知美周政，抗斾賦車攻。"]', '["告善康莊側，求賢市肆中。","擁麾分彩雉，持節曳丹虹。","影丽天山雪，光搖朔塞风。","方知美周政，抗斾賦车攻。"]', '诗', 'shi', '', NULL, '旌 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d441de9-4d5b-4adb-89de-8278f360645d', '戈', '戈', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["富父舂喉日，殷辛漂杵年。","曉霜含白刃，落影駐雕鋋。","夕擯金門側，朝提玉塞前。","願隨龍影度，橫□陣雲邊。"]', '["富父舂喉日，殷辛漂杵年。","晓霜含白刃，落影駐雕鋋。","夕擯金门側，朝提玉塞前。","願隨龙影度，橫□陣云邊。"]', '诗', 'shi', '', NULL, '戈 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6eed09b-5530-419e-871a-53f46e97aa20', '鼓', '鼓', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["舜日諧鼗響，堯年韻土聲。","向樓疑吹擊，震谷似雷驚。","仙鶴排門起，靈鼉帶水鳴。","樂云行已奏，禮曰冀相成。"]', '["舜日諧鼗响，堯年韻土声。","向楼疑吹擊，震谷似雷驚。","仙鹤排门起，靈鼉带水鳴。","乐云行已奏，禮曰冀相成。"]', '诗', 'shi', '', NULL, '鼓 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a45418e-84c6-4d19-abdf-77cace7ed5d6', '弓', '弓', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["桃文稱辟惡，桑質表初生。","宛轉雕鞬際，依稀半月明。","遙彎落雁影，虛引怯猿聲。","徒切烏號思，攀龍遂不成。"]', '["桃文稱辟惡，桑質表初生。","宛轉雕鞬際，依稀半月明。","遙彎落雁影，虛引怯猿声。","徒切烏號思，攀龙遂不成。"]', '诗', 'shi', '', NULL, '弓 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c3f21a1-9339-41ed-b1e3-be98739609b1', '琴', '琴', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["名士竹林隈，鳴琴寶匣開。","風前中散至，月下步兵來。","淮海多爲室，梁岷舊作臺。","子期如可聽，山水響餘哀。"]', '["名士竹林隈，鳴琴寶匣开。","风前中散至，月下步兵来。","淮海多爲室，梁岷旧作台。","子期如可听，山水响餘哀。"]', '诗', 'shi', '', NULL, '琴 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e74207a-974e-402e-9f3b-6ee6cd3f8800', '琴', '琴', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["隱士竹林隈，英聲寳匣開。","風前緑綺弄，月下白雲來。","淮海多為室，梁岷舊作臺。","子期如可聴，山水響餘哀。"]', '["隐士竹林隈，英声寳匣开。","风前緑綺弄，月下白云来。","淮海多為室，梁岷旧作台。","子期如可聴，山水响餘哀。"]', '诗', 'shi', '', NULL, '琴 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('985a9b93-e0e1-413f-870b-de79f53da0e2', '瑟', '瑟', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["伏羲初製法，素女昔傳名。","流水嘉魚躍，叢臺舞鳳驚。","嘉賓飲未極，君子娛俱幷。","倘入丘之戶，應知由也情。"]', '["伏羲初製法，素女昔傳名。","流水嘉鱼躍，叢台舞鳳驚。","嘉賓饮未極，君子娛俱幷。","倘入丘之戶，應知由也情。"]', '诗', 'shi', '', NULL, '瑟 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82711625-5102-4f21-9239-8eebc9080ea4', '琵琶', '琵琶', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["朱絲聞岱谷，鑠質本多端。","半月分弦出，叢花拂面安。","將軍曾制曲，司馬屢陪觀。","本是胡中樂，希君馬上彈。"]', '["朱絲闻岱谷，鑠質本多端。","半月分弦出，叢花拂面安。","將軍曾制曲，司马屢陪观。","本是胡中乐，希君马上彈。"]', '诗', 'shi', '', NULL, '琵琶 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00ca9ba7-1c54-487b-b0dd-27cc35401090', '箏', '箏', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["蒙恬芳軌設，遊楚妙彈開。","新曲帳中發，清音指下來。","鈿裝模六律，柱列配三才。","莫聽西秦奏，箏箏有剩哀。"]', '["蒙恬芳軌設，游楚妙彈开。","新曲帳中發，清音指下来。","鈿裝模六律，柱列配三才。","莫听西秦奏，箏箏有剩哀。"]', '诗', 'shi', '', NULL, '箏 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d011903c-7ae4-45fd-9527-88afd7ee11cb', '鐘', '鐘', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["既接南鄰磬，還隨北里笙。","平陵通曙響，長樂警宵聲。","秋至含霜動，春歸應律鳴。","欲知常待扣，金簴有餘清。"]', '["既接南鄰磬，還隨北里笙。","平陵通曙响，长乐警宵声。","秋至含霜动，春归應律鳴。","欲知常待扣，金簴有餘清。"]', '诗', 'shi', '', NULL, '鐘 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fac4ec75-dc9e-40eb-a6ad-6a64a9ef79c6', '簫', '簫', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["虞舜調清管，王襃賦雅音。","參差橫鳳翼，搜索動人心。","□□□□□，□□□□□。","□□□□□，□□□□□。"]', '["虞舜調清管，王襃賦雅音。","參差橫鳳翼，搜索动人心。","□□□□□，□□□□□。","□□□□□，□□□□□。"]', '诗', 'shi', '', NULL, '簫 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8daf87ab-507b-4749-9990-6b32efeaa7cc', '笛', '笛', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["羗笛寫龍聲，長吟入夜清。","關山孤月下，來向隴頭鳴。","逐吹梅花落，含春柳色驚。","行觀向子賦，坐憶舊鄰情。"]', '["羗笛寫龙声，长吟入夜清。","关山孤月下，来向隴头鳴。","逐吹梅花落，含春柳色驚。","行观向子賦，坐憶旧鄰情。"]', '诗', 'shi', '', NULL, '笛 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9d34d79-392b-497b-839b-ace1e4f80dd5', '笙', '笙', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["懸匏曲沃上，孤篠汶陽隈。","形寫歌鸞翼，聲隨舞鳳哀。","歡娛分北里，純孝即南陔。","今日虞音奏，蹌蹌鳥獸來。"]', '["懸匏曲沃上，孤篠汶陽隈。","形寫歌鸾翼，声隨舞鳳哀。","歡娛分北里，純孝即南陔。","今日虞音奏，蹌蹌鸟獸来。"]', '诗', 'shi', '', NULL, '笙 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29c300b2-0ccf-400a-8a13-ae8d693030ae', '歌', '歌', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["漢帝臨汾水，周仙去洛濱。","郢中吟白雪，梁上繞飛塵。","響發行雲駐，聲隨子夜新。","願君聽扣角，當自識賢臣。"]', '["漢帝臨汾水，周仙去洛濱。","郢中吟白雪，梁上繞飞塵。","响發行云駐，声隨子夜新。","願君听扣角，當自識賢臣。"]', '诗', 'shi', '', NULL, '歌 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc3ac7dd-d3b8-4dff-af44-efb2a529cd25', '舞', '舞', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["妙伎遊金谷，佳人滿石城。","霞衣席上轉，花岫雪前明。","儀鳳諧清曲，回鸞應雅聲。","非君一顧重，誰賞素腰輕。"]', '["妙伎游金谷，佳人满石城。","霞衣席上轉，花岫雪前明。","儀鳳諧清曲，回鸾應雅声。","非君一顧重，誰賞素腰轻。"]', '诗', 'shi', '', NULL, '舞 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f060ba9d-27f7-46c4-b566-010e181c2664', '珠', '珠', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["燦爛金輿側，玲瓏玉殿隈。","昆池明月滿，合浦夜光回。","彩逐靈蛇轉，行隨舞鳳來。","甘泉宮起罷，花媚望風臺。"]', '["燦爛金輿側，玲瓏玉殿隈。","昆池明月满，合浦夜光回。","彩逐靈蛇轉，行隨舞鳳来。","甘泉宮起罷，花媚望风台。"]', '诗', 'shi', '', NULL, '珠 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39e171f2-dbc2-432e-9505-d5b6d47a3a0a', '玉', '玉', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["映石先過魏，連城欲向秦。","洛陽陪勝友，燕趙類佳人。","方水晴虹媚，常山瑞馬新。","徒爲卞和識，不遇楚王珍。"]', '["映石先過魏，連城欲向秦。","洛陽陪勝友，燕趙類佳人。","方水晴虹媚，常山瑞马新。","徒爲卞和識，不遇楚王珍。"]', '诗', 'shi', '', NULL, '玉 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4174d1a-5436-41d3-b619-7a1abb48b943', '金', '金', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["南楚標前貢，西秦識舊城。","祭天封漢嶺，擲地警孫聲。","向日披沙淨，含風振鐸鳴。","方同楊伯起，獨有四知名。"]', '["南楚標前貢，西秦識旧城。","祭天封漢嶺，擲地警孫声。","向日披沙淨，含风振鐸鳴。","方同楊伯起，独有四知名。"]', '诗', 'shi', '', NULL, '金 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d41b10f4-00e6-4a37-b860-f720c3ff5a3e', '銀', '銀', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["思婦屏輝掩，遊人燭影長。","玉壺初下箭，桐井共安牀。","色帶長河色，光浮滿月光。","靈山有珍甕，仙闕薦君王。"]', '["思婦屏輝掩，游人燭影长。","玉壺初下箭，桐井共安牀。","色带长河色，光浮满月光。","靈山有珍甕，仙闕薦君王。"]', '诗', 'shi', '', NULL, '銀 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23cb2e95-cafb-44a2-ab19-2d4f2e828c81', '錢', '錢', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["漢日五銖建，姬年九府流。","天龍帶泉寶，地馬列金溝。","趙壹囊初乏，何曾箸欲收。","金門應入論，玉井冀來求。"]', '["漢日五銖建，姬年九府流。","天龙带泉寶，地马列金溝。","趙壹囊初乏，何曾箸欲收。","金门應入論，玉井冀来求。"]', '诗', 'shi', '', NULL, '錢 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecc0070b-7766-4797-bb06-5998eacb08d2', '錦', '錦', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["漢使巾車遠，河陽步障陳。","雲浮仙石日，霞滿蜀江春。","機迥回文巧，紳兼束髪新。","若逢楚王貴，不作夜行人。"]', '["漢使巾车远，河陽步障陳。","云浮仙石日，霞满蜀江春。","機迥回文巧，紳兼束髪新。","若逢楚王貴，不作夜行人。"]', '诗', 'shi', '', NULL, '錦 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77a14021-e3ed-46b1-96fe-d70e97fa7e17', '羅', '羅', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["妙舞隨裙動，行歌入扇清。","蓮花依帳發，秋月鑒帷明。","雲薄衣初捲，蟬飛翼轉輕。","若珍三代服，同擅綺紈名。"]', '["妙舞隨裙动，行歌入扇清。","蓮花依帳發，秋月鑒帷明。","云薄衣初捲，蟬飞翼轉轻。","若珍三代服，同擅綺紈名。"]', '诗', 'shi', '', NULL, '羅 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb03871c-ff9b-4c9c-8205-9fae833ee55f', '綾', '綾', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["金縷通秦國，爲裘指魏君。","落花遙寫霧，飛鶴近圖雲。","馬眼冰凌影，竹根雪霰文。","何當畫秦女，煙際坐氤氳。"]', '["金縷通秦国，爲裘指魏君。","落花遙寫霧，飞鹤近圖云。","马眼冰凌影，竹根雪霰文。","何當畫秦女，煙際坐氤氳。"]', '诗', 'shi', '', NULL, '綾 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4da76ae6-03d6-4c12-a834-f05376f803b0', '素', '素', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["□□□□女，纖腰洛浦妃。","□□遠方望，雁足上林飛。","妙奪鮫綃色，光騰月扇輝。","非君下路去，誰賞故人機。"]', '["□□□□女，纖腰洛浦妃。","□□远方望，雁足上林飞。","妙奪鮫綃色，光腾月扇輝。","非君下路去，誰賞故人機。"]', '诗', 'shi', '', NULL, '素 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5c4f85a-fe05-4762-aea9-b47ec2b00f45', '布', '布', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["御績創羲黃，緇冠表素王。","瀑飛臨碧海，火浣擅炎方。","孫被登三相，劉衣闡四方。","佇因舂斗粟，來曉棣華芳。"]', '["御績創羲黄，緇冠表素王。","瀑飞臨碧海，火浣擅炎方。","孫被登三相，劉衣闡四方。","佇因舂斗粟，来晓棣华芳。"]', '诗', 'shi', '', NULL, '布 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fa0eee9-157b-4ff3-a1e6-ac0f509dfe95', '舟', '舟', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["征櫂三江暮，連檣萬里回。","相烏風際轉，畫鷁浪前開。","羽客乘霞至，仙人弄月來。","何當同傅說，特展巨川材。"]', '["征櫂三江暮，連檣万里回。","相烏风際轉，畫鷁浪前开。","羽客乘霞至，仙人弄月来。","何當同傅说，特展巨川材。"]', '诗', 'shi', '', NULL, '舟 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e41d18ad-3b3a-4185-a609-a916908bb01f', '車', '车', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["天子馭金根，蒲輪闢四門。","五神趨雪至，雙轂似雷奔。","丹鳳棲金轄，非熊載寶軒。","無階忝虛左，珠乘奉王言。"]', '["天子馭金根，蒲輪闢四门。","五神趨雪至，雙轂似雷奔。","丹鳳棲金轄，非熊載寶軒。","無階忝虛左，珠乘奉王言。"]', '诗', 'shi', '', NULL, '車 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87734cde-e40f-42ce-937d-59cd2b198cc9', '牀', '牀', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["傳聞有象牀，疇昔獻君王。","玳瑁千金起，珊瑚七寶妝。","桂筵含柏馥，蘭席拂沈香。","願奉羅帷夜，長乘秋月光。"]', '["傳闻有象牀，疇昔獻君王。","玳瑁千金起，珊瑚七寶妝。","桂筵含柏馥，蘭席拂沈香。","願奉羅帷夜，长乘秋月光。"]', '诗', 'shi', '', NULL, '牀 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6678e73-d4ee-4b39-8dd9-81a4bb5d5c2d', '席', '席', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["避席承宣父，重筵揖戴公。","桂香浮半月，蘭氣襲回風。","舞拂丹霞上，歌清白雪中。","佇將文綺色，舒卷帝王宮。"]', '["避席承宣父，重筵揖戴公。","桂香浮半月，蘭氣襲回风。","舞拂丹霞上，歌清白雪中。","佇將文綺色，舒卷帝王宮。"]', '诗', 'shi', '', NULL, '席 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3becd0ae-ea65-4936-997f-0030d305dde4', '帷', '帷', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["久閉先生戶，高褰太守車。","羅將翡翠合，錦逐鳳皇舒。","明月彈琴夜，清風入幌初。","方知決勝策，黃石受兵書。"]', '["久閉先生戶，高褰太守车。","羅將翡翠合，錦逐鳳皇舒。","明月彈琴夜，清风入幌初。","方知決勝策，黄石受兵书。"]', '诗', 'shi', '', NULL, '帷 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f34ae469-7eb2-420f-9d65-41540ea931ee', '簾', '簾', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["清風時入燕，紫殿幾含秋。","曖曖籠鈴閣，纖纖上玉鉤。","窗中翡翠動，戶外水精浮。","巧作盤龍勢，長迎飛燕遊。"]', '["清风时入燕，紫殿幾含秋。","曖曖籠鈴閣，纖纖上玉鉤。","窗中翡翠动，戶外水精浮。","巧作盤龙勢，长迎飞燕游。"]', '诗', 'shi', '', NULL, '簾 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a559f0f-e54a-4208-84d2-36bc6392ffc0', '屏', '屏', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["洞徹琉璃蔽，威紆屈膝回。","錦中雲母列，霞上織成開。","山上含春動，神仙倒景來。","脩身兼竭節，誰識作銘才。"]', '["洞徹琉璃蔽，威紆屈膝回。","錦中云母列，霞上织成开。","山上含春动，神仙倒景来。","脩身兼竭節，誰識作銘才。"]', '诗', 'shi', '', NULL, '屏 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb562a18-61b6-4bff-9199-7c6e11e2855e', '被', '被', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["桂友尋東閣，蘭交聚北堂。","象筵分錦繡，羅薦合鴛鴦。","光逸偷眠穩，王章泣恨長。","孔懷欣共寢，棣萼幾含芳。"]', '["桂友尋东閣，蘭交聚北堂。","象筵分錦繡，羅薦合鴛鴦。","光逸偷眠穩，王章泣恨长。","孔懷欣共寢，棣萼幾含芳。"]', '诗', 'shi', '', NULL, '被 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be15183e-ac11-4df8-becd-802fd6d376ee', '鑑', '鑑', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["明鑑掩塵埃，含情照魏臺。","日中烏鵲至，花裏鳳皇來。","玉彩疑冰徹，金輝似月開。","方知樂彥輔，自有鑒人才。"]', '["明鑑掩塵埃，含情照魏台。","日中烏鵲至，花裏鳳皇来。","玉彩疑冰徹，金輝似月开。","方知乐彥輔，自有鑒人才。"]', '诗', 'shi', '', NULL, '鑑 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78066d78-48e6-480c-8d07-f789f103b614', '扇', '扇', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["翟羽舊傳名，蒲葵價不輕。","花芳不滿面，羅薄詎障聲。","禦熱含風細，臨秋帶月明。","同心如可贈，持表合歡情。"]', '["翟羽旧傳名，蒲葵價不轻。","花芳不满面，羅薄詎障声。","禦熱含风細，臨秋带月明。","同心如可贈，持表合歡情。"]', '诗', 'shi', '', NULL, '扇 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f1cacdf-ff25-4110-9273-d12f486d410a', '燭', '燭', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["兔月清光隱，龍盤畫燭新。","三星花入夜，四序玉調晨。","浮炷依羅幌，吹香匝綺茵。","若逢燕國相，持用舉賢人。"]', '["兔月清光隐，龙盤畫燭新。","三星花入夜，四序玉調晨。","浮炷依羅幌，吹香匝綺茵。","若逢燕国相，持用舉賢人。"]', '诗', 'shi', '', NULL, '燭 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65104886-e39a-4fcb-af82-343115df6d5b', '酒', '酒', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["孔坐洽良儔，陳筵幾獻酬。","臨風竹葉滿，湛月桂香浮。","每接高陽宴，長陪河朔遊。","會從玄石飲，雲雨出圓丘。"]', '["孔坐洽良儔，陳筵幾獻酬。","臨风竹葉满，湛月桂香浮。","每接高陽宴，长陪河朔游。","會從玄石饮，云雨出圓丘。"]', '诗', 'shi', '', NULL, '酒 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebab8cfc-f58d-46f3-9e58-88f5f65fc390', '蘭', '蘭', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["虛室重招尋，忘言契斷金。","英浮漢家酒，雪儷楚王琴。","廣殿輕香發，高臺遠吹吟。","河汾應擢秀，誰肯訪山陰。"]', '["虛室重招尋，忘言契斷金。","英浮漢家酒，雪儷楚王琴。","廣殿轻香發，高台远吹吟。","河汾應擢秀，誰肯訪山陰。"]', '诗', 'shi', '', NULL, '蘭 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fee5db3-d6de-4569-8bf8-58982e99902e', '菊', '菊', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["玉律三秋暮，金精九日開。","榮舒洛媛浦，香泛野人杯。","靃靡寒潭側，丰茸曉岸隈。","黃花今日晚，無復白衣來。"]', '["玉律三秋暮，金精九日开。","榮舒洛媛浦，香泛野人杯。","靃靡寒潭側，丰茸晓岸隈。","黄花今日晚，無复白衣来。"]', '诗', 'shi', '', NULL, '菊 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edc80b2b-224d-4759-9d03-5f02c6515c32', '竹', '竹', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["高簳楚江濆，嬋娟含曙氛。","白花搖鳳影，青節動龍文。","葉埽東南日，枝捎西北雲。","誰知湘水上，流淚獨思君。"]', '["高簳楚江濆，嬋娟含曙氛。","白花搖鳳影，青節动龙文。","葉埽东南日，枝捎西北云。","誰知湘水上，流泪独思君。"]', '诗', 'shi', '', NULL, '竹 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d56b4fae-8941-4f08-a0ee-9ba662d03646', '藤', '藤', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["吐葉依松磴，舒苗長石臺。","神農嘗藥罷，質子寄書來。","色映蒲萄架，花分竹葉杯。","金堤不見識，玉潤幾重開。"]', '["吐葉依松磴，舒苗长石台。","神農嘗藥罷，質子寄书来。","色映蒲萄架，花分竹葉杯。","金堤不见識，玉潤幾重开。"]', '诗', 'shi', '', NULL, '藤 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c994d39-eea3-4384-8f4e-1996f6004a03', '萱', '萱', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["屣步尋芳草，忘憂自結叢。","黃英開養性，綠葉正依籠。","色湛仙人露，香傳少女風。","還依北堂下，曹植動文雄。"]', '["屣步尋芳草，忘憂自結叢。","黄英开養性，綠葉正依籠。","色湛仙人露，香傳少女风。","還依北堂下，曹植动文雄。"]', '诗', 'shi', '', NULL, '萱 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08dc1b87-9585-46e0-a144-c98b53906814', '茅', '茅', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["楚甸供王日，衡陽入貢年。","麏包青野外，鴟嘯綺楹前。","堯帝成茨罷，殷湯祭雨旋。","方期大君錫，不懼小巫捐。"]', '["楚甸供王日，衡陽入貢年。","麏包青野外，鴟嘯綺楹前。","堯帝成茨罷，殷湯祭雨旋。","方期大君錫，不懼小巫捐。"]', '诗', 'shi', '', NULL, '茅 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ee8d5cc-bb25-499f-8d1c-4df1581916fa', '荷', '荷', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["新溜滿澄陂，圓荷影若規。","風來香氣遠，日落蓋陰移。","魚戲排緗葉，龜浮見綠池。","魏朝難接採，楚服但同披。"]', '["新溜满澄陂，圓荷影若規。","风来香氣远，日落蓋陰移。","鱼戲排緗葉，龟浮见綠池。","魏朝难接採，楚服但同披。"]', '诗', 'shi', '', NULL, '荷 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce521476-6455-4ee5-a06d-c270defa7eed', '萍', '萍', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["二月虹初見，三春蟻正浮。","青蘋含吹轉，紫蒂帶波流。","屢逐明神薦，常隨旅客遊。","既能甜似蜜，還遶楚王舟。"]', '["二月虹初见，三春蟻正浮。","青蘋含吹轉，紫蒂带波流。","屢逐明神薦，常隨旅客游。","既能甜似蜜，還遶楚王舟。"]', '诗', 'shi', '', NULL, '萍 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b20cce1-79a1-4e0a-97a9-ce6a59c2d484', '菱', '菱', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["鉅野韶光暮，東平春溜通。","影搖江浦月，香引櫂歌風。","日色翻池上，潭花發鏡中。","五湖多賞樂，千里望難窮。"]', '["鉅野韶光暮，东平春溜通。","影搖江浦月，香引櫂歌风。","日色翻池上，潭花發镜中。","五湖多賞乐，千里望难窮。"]', '诗', 'shi', '', NULL, '菱 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('441e1725-3470-45c5-a565-74249fade679', '瓜', '瓜', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["欲識東陵味，青門五色瓜。","龍蹄遠珠履，女臂動金花。","六子方呈瑞，三仙實可嘉。","終朝奉絺綌，謁帝佇非賒。"]', '["欲識东陵味，青门五色瓜。","龙蹄远珠履，女臂动金花。","六子方呈瑞，三仙實可嘉。","終朝奉絺綌，謁帝佇非賒。"]', '诗', 'shi', '', NULL, '瓜 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6275cdf-0b32-4e37-9ff7-539ee40fac1d', '松', '松', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["鬱鬱高巖表，森森幽澗陲。","鶴棲君子樹，風拂大夫枝。","百尺條陰合，千年蓋影披。","歲寒終不改，勁節幸君知。"]', '["鬱鬱高巖表，森森幽澗陲。","鹤棲君子樹，风拂大夫枝。","百尺條陰合，千年蓋影披。","歲寒終不改，勁節幸君知。"]', '诗', 'shi', '', NULL, '松 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86f3f477-affc-41a9-923b-5d586bac2c21', '桂', '桂', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["未[殖]銀宮裏，寧移玉殿幽。","枝生無限月，花滿自然秋。","俠客條爲馬，仙人葉作舟。","願君期道術，攀折可淹留。"]', '["未[殖]銀宮裏，寧移玉殿幽。","枝生無限月，花满自然秋。","俠客條爲马，仙人葉作舟。","願君期道術，攀折可淹留。"]', '诗', 'shi', '', NULL, '桂 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a59add5-9f03-4a78-9200-057b51d2aef9', '槐', '槐', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["暮律移寒火，春宮長舊栽。","葉生馳道側，花落鳳庭隈。","烈士懷忠觸，鴻儒訪業來。","何當赤墀下，疎幹擬三台。"]', '["暮律移寒火，春宮长旧栽。","葉生驰道側，花落鳳庭隈。","烈士懷忠觸，鴻儒訪業来。","何當赤墀下，疎幹擬三台。"]', '诗', 'shi', '', NULL, '槐 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02132c8c-6c18-4c19-902c-d5588136be76', '柳', '柳', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["楊柳鬱氤氳，金堤總翠氛。","庭前花類雪，樓際葉如雲。","列宿分龍影，芳池寫鳳文。","短簫何以奏，攀折爲思君。"]', '["楊柳鬱氤氳，金堤總翠氛。","庭前花類雪，楼際葉如云。","列宿分龙影，芳池寫鳳文。","短簫何以奏，攀折爲思君。"]', '诗', 'shi', '', NULL, '柳 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da21af11-9ae8-488e-a5ab-f475f0ee7409', '桐', '桐', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["孤秀嶧陽岑，亭亭出衆林。","春光雜鳳影，秋月弄圭陰。","高映龍門迥，雙依玉井深。","不因將入爨，誰謂作鳴琴。"]', '["孤秀嶧陽岑，亭亭出衆林。","春光杂鳳影，秋月弄圭陰。","高映龙门迥，雙依玉井深。","不因將入爨，誰謂作鳴琴。"]', '诗', 'shi', '', NULL, '桐 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5766e2a-5744-4365-ab71-bc646fd389ac', '桃', '桃', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["獨有成蹊處，穠華發井傍。","山風凝笑臉，朝露泫啼妝。","隱士顏應改，仙人路漸長。","還欣上林苑，千歲奉君王。"]', '["独有成蹊处，穠华發井傍。","山风凝笑臉，朝露泫啼妝。","隐士顏應改，仙人路漸长。","還欣上林苑，千歲奉君王。"]', '诗', 'shi', '', NULL, '桃 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('435848e9-8b7e-4e9c-8e6d-e3bedba8225e', '李', '李', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["潘岳閑居日，王戎戲陌辰。","蝶游芳徑馥，鸎囀弱枝新。","葉暗青房晚，花明玉井春。","方知有靈幹，特用表真人。"]', '["潘岳闲居日，王戎戲陌辰。","蝶游芳徑馥，鸎囀弱枝新。","葉暗青房晚，花明玉井春。","方知有靈幹，特用表真人。"]', '诗', 'shi', '', NULL, '李 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d26fcebf-9555-46f1-be3f-d0a554a7f9e0', '梨', '梨', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["擅美玄光側，傳芳瀚海中。","鳳文疎象郡，花影麗新豐。","色對瑤池紫，甘依大谷紅。","若令逢漢主，還冀識張公。"]', '["擅美玄光側，傳芳瀚海中。","鳳文疎象郡，花影丽新豐。","色对瑤池紫，甘依大谷紅。","若令逢漢主，還冀識張公。"]', '诗', 'shi', '', NULL, '梨 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89cafa47-5cbd-4228-b465-7d54876c605a', '梅', '梅', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["大庾歛寒光，南枝獨早芳。","雪含朝暝色，風引去來香。","妝面回青鏡，歌塵起畫梁。","若能遙止渴，何暇泛瓊漿。"]', '["大庾歛寒光，南枝独早芳。","雪含朝暝色，风引去来香。","妝面回青镜，歌塵起畫梁。","若能遙止渴，何暇泛瓊漿。"]', '诗', 'shi', '', NULL, '梅 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5739588d-93b0-41f0-b389-e466fb63fed1', '橘', '橘', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["萬里盤根植，千秋布葉繁。","既榮潘子賦，方重陸生言。","玉蘤含霜動，金衣逐吹翻。","願辭湘水曲，長茂上林園。"]', '["万里盤根植，千秋布葉繁。","既榮潘子賦，方重陸生言。","玉蘤含霜动，金衣逐吹翻。","願辞湘水曲，长茂上林园。"]', '诗', 'shi', '', NULL, '橘 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfd05dae-8933-46c8-82e0-b9bbc0ab47b8', '鳳', '鳳', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["有鳥居丹穴，其名曰鳳皇。","九苞應靈瑞，五色成文章。","屢向秦樓側，頻過洛水陽。","鳴岐今日見，阿閣佇來翔。"]', '["有鸟居丹穴，其名曰鳳皇。","九苞應靈瑞，五色成文章。","屢向秦楼側，頻過洛水陽。","鳴岐今日见，阿閣佇来翔。"]', '诗', 'shi', '', NULL, '鳳 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab80b3b0-27ca-487d-9ef1-a18c9001d24e', '鶴', '鹤', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["黃鶴遠聯翩，從鸞下紫煙。","翱翔一萬里，來去幾千年。","已憩青田側，時遊丹禁前。","莫言空警露，猶冀一聞天。"]', '["黄鹤远聯翩，從鸾下紫煙。","翱翔一万里，来去幾千年。","已憩青田側，时游丹禁前。","莫言空警露，猶冀一闻天。"]', '诗', 'shi', '', NULL, '鶴 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52ae7d46-b657-463c-bd24-249e1b1458bd', '烏', '烏', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["日路朝飛急，霜臺夕影寒。","聯翩依月樹，迢遞繞風竿。","白首何年改，青琴此夜彈。","靈臺如可託，千里向長安。"]', '["日路朝飞急，霜台夕影寒。","聯翩依月樹，迢遞繞风竿。","白首何年改，青琴此夜彈。","靈台如可託，千里向长安。"]', '诗', 'shi', '', NULL, '烏 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1668d938-139f-41f4-8b2b-1a5a6fe3150b', '鵲', '鵲', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["不分荆山抵，甘從石印飛。","危巢畏風急，繞樹覺星稀。","喜逐行人至，愁隨織女歸。","倘遊明鏡裏，朝夕動光輝。"]', '["不分荆山抵，甘從石印飞。","危巢畏风急，繞樹覺星稀。","喜逐行人至，愁隨织女归。","倘游明镜裏，朝夕动光輝。"]', '诗', 'shi', '', NULL, '鵲 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9aa1d77e-5533-4fe3-8209-09d251564ac3', '雁', '雁', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["春暉滿朔方，歸雁發衡陽。","望月驚弦影，排雲結陣行。","往還倦南北，朝夕苦風霜。","寄語能鳴侶，相隨入帝鄉。"]', '["春暉满朔方，归雁發衡陽。","望月驚弦影，排云結陣行。","往還倦南北，朝夕苦风霜。","寄語能鳴侶，相隨入帝乡。"]', '诗', 'shi', '', NULL, '雁 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b141d9da-4b9d-4d1a-95a9-fe00ab6fe4ce', '鳧', '鳧', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["颯沓睢陽涘，浮游漢水隈。","錢飛出井見，鶴引入琴哀。","李陵賦詩罷，王喬曳舄來。","何當歸太液，翱集動成雷。"]', '["颯沓睢陽涘，浮游漢水隈。","錢飞出井见，鹤引入琴哀。","李陵賦诗罷，王喬曳舄来。","何當归太液，翱集动成雷。"]', '诗', 'shi', '', NULL, '鳧 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('749d5af7-f822-4ebd-98c5-0f1282be7fa7', '鸎', '鸎', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["芳樹雜花紅，羣鸎亂曉空。","聲分折楊吹，嬌韻落梅風。","寫囀清弦裏，遷喬暗木中。","友生若可冀，幽谷響還通。"]', '["芳樹杂花紅，羣鸎亂晓空。","声分折楊吹，嬌韻落梅风。","寫囀清弦裏，遷喬暗木中。","友生若可冀，幽谷响還通。"]', '诗', 'shi', '', NULL, '鸎 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5ead39e-f60d-4477-9db1-3249b2608452', '雉', '雉', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["白雉振朝聲，飛來表太平。","楚郊疑鳳出，陳寶若雞鳴。","童子懷仁至，中郎作賦成。","冀君看飲啄，耿介獨含情。"]', '["白雉振朝声，飞来表太平。","楚郊疑鳳出，陳寶若雞鳴。","童子懷仁至，中郎作賦成。","冀君看饮啄，耿介独含情。"]', '诗', 'shi', '', NULL, '雉 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a220382-a0cf-49c7-a7ff-7e95f0cf934d', '燕', '燕', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["天女伺辰至，玄衣澹碧空。","差池沐時雨，頡頏舞春風。","相賀雕闌側，雙飛翠幕中。","勿驚留爪去，猶冀識吳宮。"]', '["天女伺辰至，玄衣澹碧空。","差池沐时雨，頡頏舞春风。","相賀雕闌側，雙飞翠幕中。","勿驚留爪去，猶冀識吳宮。"]', '诗', 'shi', '', NULL, '燕 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e5bad91-e3d8-430a-8513-a9904840a36f', '雀', '雀', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["大廈初成日，嘉賓集杏梁。","銜書表周瑞，入幕應王祥。","暮宿江城裏，朝遊漣水傍。","願齊鴻鵠至，希逐鳳皇翔。"]', '["大廈初成日，嘉賓集杏梁。","銜书表周瑞，入幕應王祥。","暮宿江城裏，朝游漣水傍。","願齊鴻鵠至，希逐鳳皇翔。"]', '诗', 'shi', '', NULL, '雀 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('752e69e6-c395-4c7c-b1ea-2f0215b851a4', '龍', '龙', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["銜燭耀幽都，含章擬鳳雛。","西秦飲渭水，東洛薦河圖。","帶火移星陸，升雲出鼎湖。","希逢聖人步，庭闕正晨趨。"]', '["銜燭耀幽都，含章擬鳳雛。","西秦饮渭水，东洛薦河圖。","带火移星陸，升云出鼎湖。","希逢聖人步，庭闕正晨趨。"]', '诗', 'shi', '', NULL, '龍 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23a7ec55-a6f5-4163-9e3b-2d6d7a26f39e', '麟', '麟', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["漢祀應祥開，魯郊西狩回。","奇音中鍾呂，成角喻英才。","畫像臨仙閣，藏書入帝臺。","若驚能吐哺，爲待鳳皇來。"]', '["漢祀應祥开，魯郊西狩回。","奇音中鍾呂，成角喻英才。","畫像臨仙閣，藏书入帝台。","若驚能吐哺，爲待鳳皇来。"]', '诗', 'shi', '', NULL, '麟 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7267a417-b11d-403c-8434-aeb692fe02b7', '象', '象', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["鬱林開郡畢，維揚作貢初。","萬推方演夢，惠子正焚書。","執燧奔吳戰，量舟入魏墟。","六牙行致遠，千葉奉高居。"]', '["鬱林开郡畢，維揚作貢初。","万推方演梦，惠子正焚书。","執燧奔吳戰，量舟入魏墟。","六牙行致远，千葉奉高居。"]', '诗', 'shi', '', NULL, '象 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab867042-2c37-42e8-9537-5e51d728a2c1', '馬', '马', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["天馬本來東，嘶驚御史驄。","蒼龍遙逐日，紫燕迥追風。","明月來鞍上，浮雲落蓋中。","得隨穆天子，何假唐成公。"]', '["天马本来东，嘶驚御史驄。","蒼龙遙逐日，紫燕迥追风。","明月来鞍上，浮云落蓋中。","得隨穆天子，何假唐成公。"]', '诗', 'shi', '', NULL, '馬 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47e0b243-e233-461d-a7a4-dc00b0ed7bab', '牛', '牛', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["齊歌初入相，燕陣早橫功。","欲向桃林下，先過梓樹中。","在吳頻喘月，奔夢屢驚風。","不用五丁士，如何九折通。"]', '["齊歌初入相，燕陣早橫功。","欲向桃林下，先過梓樹中。","在吳頻喘月，奔梦屢驚风。","不用五丁士，如何九折通。"]', '诗', 'shi', '', NULL, '牛 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3acda38d-1e14-4bbe-9604-1ea488d12630', '豹', '豹', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["車法肇宗周，鼷文闡大猷。","還將君子變，來蘊太公籌。","委質超羊鞟，飛名列虎侯。","若令逢雨露，長隱南山幽。"]', '["车法肇宗周，鼷文闡大猷。","還將君子变，来蘊太公籌。","委質超羊鞟，飞名列虎侯。","若令逢雨露，长隐南山幽。"]', '诗', 'shi', '', NULL, '豹 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08ee29a4-672f-42d9-84d2-0b65502752d0', '熊', '熊', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["導洛宜陽右，乘春別館前。","昭儀忠漢日，太傅翊周年。","列射三侯滿，興師七步旋。","莫言舒紫褥，猶異飲清泉。"]', '["導洛宜陽右，乘春別館前。","昭儀忠漢日，太傅翊周年。","列射三侯满，兴師七步旋。","莫言舒紫褥，猶異饮清泉。"]', '诗', 'shi', '', NULL, '熊 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4227428-5c74-4a04-8ad2-240bc6c47cf2', '鹿', '鹿', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["涿鹿聞中冀，秦原闢帝畿。","柰花開舊苑，萍葉藹前詩。","道士乘仙日，先生折角時。","方懷丈夫志，抗首別心期。"]', '["涿鹿闻中冀，秦原闢帝畿。","柰花开旧苑，萍葉藹前诗。","道士乘仙日，先生折角时。","方懷丈夫志，抗首別心期。"]', '诗', 'shi', '', NULL, '鹿 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('287695d6-23fd-4432-b763-07a7c2ccb862', '羊', '羊', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["絕飲懲澆俗，行驅夢逸材。","仙人擁石去，童子馭車來。","夜玉含星動，晨氈映雪開。","莫言鴻漸力，長牧上林隈。"]', '["絕饮懲澆俗，行驱梦逸材。","仙人擁石去，童子馭车来。","夜玉含星动，晨氈映雪开。","莫言鴻漸力，长牧上林隈。"]', '诗', 'shi', '', NULL, '羊 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('462d29a1-3633-4959-a5e8-eb348c87c77c', '兔', '兔', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["上蔡應初擊，平岡遠不稀。","目隨槐葉長，形逐桂條飛。","漢月澄秋色，梁園映雪輝。","唯當感純孝，郛郭引兵威。"]', '["上蔡應初擊，平岡远不稀。","目隨槐葉长，形逐桂條飞。","漢月澄秋色，梁园映雪輝。","唯當感純孝，郛郭引兵威。"]', '诗', 'shi', '', NULL, '兔 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88653ecc-c560-41e1-8d9e-15c871ce7e71', '人日侍宴大明宮恩賜綵縷人勝應制', '人日侍宴大明宮恩賜綵縷人勝應制', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["鳳城景色已含韶，人日風光倍覺饒。","桂吐半輪迎此夜，蓂開七葉應今朝。","魚猜水凍行猶澁，鸎喜春熙弄欲嬌。","媿奉登高搖彩翰，欣逢御氣上丹霄。"]', '["鳳城景色已含韶，人日风光倍覺饒。","桂吐半輪迎此夜，蓂开七葉應今朝。","鱼猜水凍行猶澁，鸎喜春熙弄欲嬌。","媿奉登高搖彩翰，欣逢御氣上丹霄。"]', '诗', 'shi', '', NULL, '人日侍宴大明宮恩賜綵縷人勝應制 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0f7ae8c-a20b-4893-b2de-5ef8cdc13a7d', '奉和初春幸太平公主南莊應制', '奉和初春幸太平公主南莊應制', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["主家山第接雲開，天子春遊動地來。","羽騎參差花外轉，霓旌搖曳日邊回。","還將石溜調琴曲，更取峰霞入酒杯。","鸞輅已辭烏鵲渚，簫聲猶繞鳳皇臺。"]', '["主家山第接云开，天子春游动地来。","羽騎參差花外轉，霓旌搖曳日邊回。","還將石溜調琴曲，更取峰霞入酒杯。","鸾輅已辞烏鵲渚，簫声猶繞鳳皇台。"]', '诗', 'shi', '', NULL, '奉和初春幸太平公主南莊應制 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('647a3e19-b506-4d7c-9c7b-43dd5397f0e4', '太平公主山亭侍宴應制', '太平公主山亭侍宴應制', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["黃金瑞牓絳河隈，白玉仙輿紫禁來。","碧樹青岑雲外聳，朱樓畫閣水中開。","龍舟下瞰鮫人室，羽節高臨鳳女臺。","遽惜歡娛歌吹晚，揮戈更却曜靈回。"]', '["黄金瑞牓絳河隈，白玉仙輿紫禁来。","碧樹青岑云外聳，朱楼畫閣水中开。","龙舟下瞰鮫人室，羽節高臨鳳女台。","遽惜歡娛歌吹晚，揮戈更却曜靈回。"]', '诗', 'shi', '', NULL, '太平公主山亭侍宴應制 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1c62a56-548f-4786-b7ec-6c1933a93e68', '奉和拜洛應制', '奉和拜洛應制', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["七萃鑾輿動，千年瑞檢開。","文如龜負出，圖似鳳銜來。","殷薦三神享，明禋萬國陪。","周旗黃鳥集，漢幄紫雲回。","日暮鈎陳轉，清歌上帝臺。"]', '["七萃鑾輿动，千年瑞檢开。","文如龟負出，圖似鳳銜来。","殷薦三神享，明禋万国陪。","周旗黄鸟集，漢幄紫云回。","日暮鈎陳轉，清歌上帝台。"]', '诗', 'shi', '', NULL, '奉和拜洛應制 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc12d353-11e2-4dbf-a2fb-c423a416d745', '奉和幸大薦福寺應制', '奉和幸大薦福寺應制', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["雁沼開香域，鸚林降綵旃。","還窺圖鳳宇，更坐躍龍川。","桂轝朝羣辟，蘭宮列四禪。","半空銀閣斷，分砌寶繩連。","甘雨蘇燋澤，慈雲動沛篇。","獨慙賢作礪，空喜福成田。"]', '["雁沼开香域，鸚林降綵旃。","還窺圖鳳宇，更坐躍龙川。","桂轝朝羣辟，蘭宮列四禪。","半空銀閣斷，分砌寶繩連。","甘雨蘇燋澤，慈云动沛篇。","独慙賢作礪，空喜福成田。"]', '诗', 'shi', '', NULL, '奉和幸大薦福寺應制 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df35ee88-c1b9-43d8-8f99-6d3f0b681f38', '奉和幸長安故城未央宮應制', '奉和幸长安故城未央宮應制', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["舊宮賢相築，新苑聖君來。","運改城隍變，年深棟宇摧。","後池無復水，前殿久成灰。","莫辨祈風觀，空傳承露杯。","宸心千載合，睿律九韶開。","今日聯章處，猶疑上柏臺。"]', '["旧宮賢相築，新苑聖君来。","運改城隍变，年深棟宇摧。","後池無复水，前殿久成灰。","莫辨祈风观，空傳承露杯。","宸心千載合，睿律九韶开。","今日聯章处，猶疑上柏台。"]', '诗', 'shi', '', NULL, '奉和幸長安故城未央宮應制 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91fc34f7-50dd-4e48-8b7e-67488164b451', '奉和幸望春宮送朔方總管張仁亶', '奉和幸望春宮送朔方總管張仁亶', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["玉塞征驕子，金符命老臣。","三軍張武斾，萬乘餞行輪。","猛氣凌玄朔，崇恩降紫宸。","投醪還結士，辭第本忘身。","露下鷹初擊，風高雁欲賓。","方銷塞北祲，還靖漠南塵。"]', '["玉塞征驕子，金符命老臣。","三軍張武斾，万乘餞行輪。","猛氣凌玄朔，崇恩降紫宸。","投醪還結士，辞第本忘身。","露下鷹初擊，风高雁欲賓。","方銷塞北祲，還靖漠南塵。"]', '诗', 'shi', '', NULL, '奉和幸望春宮送朔方總管張仁亶 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2f519d1-9a44-476f-ac7d-9d750ce1e5fe', '奉和幸三會寺應制', '奉和幸三會寺應制', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["故臺蒼頡里，新邑紫泉居。","歲在開金寺，時來降玉輿。","龍形雖近剎，鳥跡尚留書。","竹是蒸青外，池仍點墨餘。","天文光聖草，寶思合真如。","謬奉千齡日，欣陪十地初。"]', '["故台蒼頡里，新邑紫泉居。","歲在开金寺，时来降玉輿。","龙形雖近剎，鸟跡尚留书。","竹是蒸青外，池仍点墨餘。","天文光聖草，寶思合真如。","謬奉千齡日，欣陪十地初。"]', '诗', 'shi', '', NULL, '奉和幸三會寺應制 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a35abcc-b3e1-481d-b16c-df3b4e9e997d', '奉和天樞成宴夷夏羣僚應制', '奉和天樞成宴夷夏羣僚應制', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["轍迹光西崦，勳庸紀北燕。","何如萬方會，頌德九門前。","灼灼臨黃道，迢迢入紫煙。","仙盤正下露，高柱欲承天。","山類叢雲起，珠疑大火懸。","聲流塵作刼，業固海成田。","帝澤傾堯酒，宸歌掩舜弦。","欣逢下生日，還覩上皇年。"]', '["轍迹光西崦，勳庸紀北燕。","何如万方會，頌德九门前。","灼灼臨黄道，迢迢入紫煙。","仙盤正下露，高柱欲承天。","山類叢云起，珠疑大火懸。","声流塵作刼，業固海成田。","帝澤傾堯酒，宸歌掩舜弦。","欣逢下生日，還覩上皇年。"]', '诗', 'shi', '', NULL, '奉和天樞成宴夷夏羣僚應制 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81abb6ad-3788-4606-9b2f-32675e2e87b0', '皇帝上禮撫事述懷', '皇帝上禮撫事述懷', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["配極輝光遠，承天顧託隆。","負圖濟多難，脫履歸成功。","聖道昭永錫，邕言讓在躬。","還推萬方重，咸仰四門聰。","恭己忘自逸，因人體至公。","垂旒滄海晏，解網法星空。","雲散天五色，春還日再中。","稱觴合纓弁，率舞應絲桐。","凱樂深居鎬，傳歌盛飲豐。","小臣濫簪筆，無以頌唐風。"]', '["配極輝光远，承天顧託隆。","負圖濟多难，脫履归成功。","聖道昭永錫，邕言讓在躬。","還推万方重，咸仰四门聰。","恭己忘自逸，因人體至公。","垂旒滄海晏，解網法星空。","云散天五色，春還日再中。","稱觴合纓弁，率舞應絲桐。","凱乐深居鎬，傳歌盛饮豐。","小臣濫簪笔，無以頌唐风。"]', '诗', 'shi', '', NULL, '皇帝上禮撫事述懷 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1854cf4-5d46-4e9f-b6c2-5d29f71a57cd', '奉和幸韋嗣立山莊侍宴應制', '奉和幸韋嗣立山莊侍宴應制', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["南洛師臣契，東巖王佐居。","幽情遺紱冕，宸眷屬樵漁。","制下峒山蹕，恩回灞水輿。","松門駐旌蓋，薜幄引簪裾。","石磴平黃陸，煙樓半紫虛。","雲霞仙路近，琴酒俗塵疎。","喬木千齡外，懸泉百丈餘。","崖深經鍊藥，穴古舊藏書。","樹宿摶風鳥，池潛縱壑魚。","寧知天子貴，尚憶武侯廬。"]', '["南洛師臣契，东巖王佐居。","幽情遺紱冕，宸眷屬樵漁。","制下峒山蹕，恩回灞水輿。","松门駐旌蓋，薜幄引簪裾。","石磴平黄陸，煙楼半紫虛。","云霞仙路近，琴酒俗塵疎。","喬木千齡外，懸泉百丈餘。","崖深經鍊藥，穴古旧藏书。","樹宿摶风鸟，池潛縱壑鱼。","寧知天子貴，尚憶武侯廬。"]', '诗', 'shi', '', NULL, '奉和幸韋嗣立山莊侍宴應制 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51aff429-eb12-4478-b4ae-c4b9849c94c3', '倡婦行', '倡婦行', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["十年倡家婦，三秋邊地人。","紅妝樓上歇，白髮隴頭新。","夜夜風霜苦，年年征戍頻。","山西長落日，塞北久無春。","團扇辭恩寵，回文贈苦辛。","胡兵屢攻戰，漢使絕和親。","消息如瓶井，沈浮似路塵。","空餘千里月，照妾兩眉嚬。"]', '["十年倡家婦，三秋邊地人。","紅妝楼上歇，白髮隴头新。","夜夜风霜苦，年年征戍頻。","山西长落日，塞北久無春。","團扇辞恩寵，回文贈苦辛。","胡兵屢攻戰，漢使絕和親。","消息如瓶井，沈浮似路塵。","空餘千里月，照妾兩眉嚬。"]', '诗', 'shi', '', NULL, '倡婦行 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('438ea8a5-c4c5-494b-9b20-39f7569e5414', '餞薛大夫護邊', '餞薛大夫護邊', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["荒隅時未通，副相下臨戎。","授律星芒動，分兵月暈空。","犀皮擁青橐，象齒飾雕弓。","決勝三河勇，長驅六郡雄。","登山窺代北，屈指計遼東。","佇見燕然上，抽毫頌武功。"]', '["荒隅时未通，副相下臨戎。","授律星芒动，分兵月暈空。","犀皮擁青橐，象齒飾雕弓。","決勝三河勇，长驱六郡雄。","登山窺代北，屈指計遼东。","佇见燕然上，抽毫頌武功。"]', '诗', 'shi', '', NULL, '餞薛大夫護邊 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2957a2b4-7e13-42a2-b35b-7c8d27cc95f5', '和杜學士旅次淮口阻風', '和杜学士旅次淮口阻风', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["夕吹生寒浦，清淮上暝潮。","迎風欲舉櫂，觸浪反停橈。","淼漫煙波闊，參差林岸遙。","日沈丹氣斂，天敞白雲銷。","水雁銜蘆葉，沙鷗隱荻苗。","客行殊未已，川路幾迢迢。"]', '["夕吹生寒浦，清淮上暝潮。","迎风欲舉櫂，觸浪反停橈。","淼漫煙波闊，參差林岸遙。","日沈丹氣斂，天敞白云銷。","水雁銜蘆葉，沙鷗隐荻苗。","客行殊未已，川路幾迢迢。"]', '诗', 'shi', '', NULL, '和杜學士旅次淮口阻風 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b110291-f82a-4875-a6b3-29251c151896', '送光祿劉主簿之洛', '送光祿劉主簿之洛', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["函谷雙崤右，伊川二陝東。","仙舟窅將隔，芳斝暫云同。","朋席餘歡盡，文房舊侶空。","他鄉千里月，岐路九秋風。","背櫪嘶班馬，分洲呌斷鴻。","別後青山外，相望白雲中。"]', '["函谷雙崤右，伊川二陝东。","仙舟窅將隔，芳斝暫云同。","朋席餘歡尽，文房旧侶空。","他乡千里月，岐路九秋风。","背櫪嘶班马，分洲呌斷鴻。","別後青山外，相望白云中。"]', '诗', 'shi', '', NULL, '送光祿劉主簿之洛 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ab78b9a-4242-497c-9628-e75c14c2fd86', '送駱奉禮從軍', '送駱奉禮從軍', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["玉塞邊烽舉，金壇廟略申。","羽書資銳筆，戎幕引英賓。","劍動三軍氣，衣飄萬里塵。","琴尊留別賞，風景惜離晨。","笛梅含晚吹，營柳帶餘春。","希君勒石返，歌舞入城闉。"]', '["玉塞邊烽舉，金壇廟略申。","羽书資銳笔，戎幕引英賓。","劍动三軍氣，衣飄万里塵。","琴尊留別賞，风景惜離晨。","笛梅含晚吹，營柳带餘春。","希君勒石返，歌舞入城闉。"]', '诗', 'shi', '', NULL, '送駱奉禮從軍 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b928a862-6be7-4ded-b121-75ddad706b10', '王屋山第之側雜構小亭暇日與羣公同遊', '王屋山第之側杂構小亭暇日與羣公同游', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["桂亭依絕巘，蘭榭俯回溪。","綺棟魚鱗出，雕甍鳳羽棲。","引泉聊漲沼，鑿磴且通蹊。","席上山花落，簾前野樹低。","弋林開曙景，釣渚發晴霓。","狎水驚梁雁，臨風聽楚雞。","復看題柳葉，彌喜蔭桐圭。"]', '["桂亭依絕巘，蘭榭俯回溪。","綺棟鱼鱗出，雕甍鳳羽棲。","引泉聊漲沼，鑿磴且通蹊。","席上山花落，簾前野樹低。","弋林开曙景，釣渚發晴霓。","狎水驚梁雁，臨风听楚雞。","复看題柳葉，彌喜蔭桐圭。"]', '诗', 'shi', '', NULL, '王屋山第之側雜構小亭暇日與羣公同遊 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f83c615-ac3c-49fd-b1d9-cf91451a8663', '奉和杜員外扈從教閱', '奉和杜員外扈從教閱', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["杪冬嚴殺氣，窮紀送頹光。","薄狩三農隙，大閱五戎塲。","菜田初起燒，蘭野正開防。","夾岸虹旗轉，分朋獸罟張。","燕弧帶曉月，吳劒動秋霜。","原啓前禽路，山縈後騎行。","雲區墜日羽，星苑斃天狼。","禮振軍容肅，威宣武節揚。","神心體殷祝，靈兆叶姬祥。","幸陪仙駕末，欣採翰林芳。"]', '["杪冬嚴殺氣，窮紀送頹光。","薄狩三農隙，大閱五戎塲。","菜田初起燒，蘭野正开防。","夾岸虹旗轉，分朋獸罟張。","燕弧带晓月，吳劒动秋霜。","原啓前禽路，山縈後騎行。","云區墜日羽，星苑斃天狼。","禮振軍容肅，威宣武節揚。","神心體殷祝，靈兆叶姬祥。","幸陪仙駕末，欣採翰林芳。"]', '诗', 'shi', '', NULL, '奉和杜員外扈從教閱 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76d2c1f7-62a7-4686-8023-a49bdbff5326', '軍師凱旋自邕州順流舟中', '軍師凱旋自邕州順流舟中', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["鳴鞞入嶂口，汎舸歷川湄。","尚想江陵陣，猶疑下瀨師。","岸回帆影疾，風逆鼓聲遲。","萍葉沾蘭槳，林花拂桂旗。","弓鳴蒼隼落，劒動白猿悲。","芳樹吟羗管，幽篁入楚詞。","全軍多勝策，無戰在明時。","寄謝山東妙，長纓徒自欺。"]', '["鳴鞞入嶂口，汎舸歷川湄。","尚想江陵陣，猶疑下瀨師。","岸回帆影疾，风逆鼓声遲。","萍葉沾蘭槳，林花拂桂旗。","弓鳴蒼隼落，劒动白猿悲。","芳樹吟羗管，幽篁入楚词。","全軍多勝策，無戰在明时。","寄謝山东妙，长纓徒自欺。"]', '诗', 'shi', '', NULL, '軍師凱旋自邕州順流舟中 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d0451d4-5a61-4cce-af90-5b8cff356cb1', '夏晚九成宮呈同僚', '夏晚九成宮呈同僚', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["碣館分襄野，平臺架射峰。","英藩信煒燁，勝地本從容。","林引梧庭鳳，泉歸竹沼龍。","小軒恆共處，長坂屬相從。","野席蘭琴奏，山臺桂酒醲。","一枰移晝景，六著盡宵鐘。","枚藻清詞律，鄒談耀辯鋒。","結歡良有裕，聯寀愧無庸。","暫悅丘中賞，還希物外蹤。","風煙遠近至，魚鳥去來逢。","月澗橫千丈，雲崖列萬重。","樹紅山果熟，崖綠水苔濃。","願以西園柳，長間北巖松。"]', '["碣館分襄野，平台架射峰。","英藩信煒燁，勝地本從容。","林引梧庭鳳，泉归竹沼龙。","小軒恆共处，长坂屬相從。","野席蘭琴奏，山台桂酒醲。","一枰移晝景，六著尽宵鐘。","枚藻清词律，鄒談耀辯鋒。","結歡良有裕，聯寀愧無庸。","暫悅丘中賞，還希物外蹤。","风煙远近至，鱼鸟去来逢。","月澗橫千丈，云崖列万重。","樹紅山果熟，崖綠水苔濃。","願以西园柳，长间北巖松。"]', '诗', 'shi', '', NULL, '夏晚九成宮呈同僚 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6144f01e-6bb9-4ed8-8b1e-7a1ca0dd4dfa', '田假限疾不獲還莊載想田園兼思親友率成短韻用寫長懷贈杜幽素', '田假限疾不獲還莊載想田园兼思親友率成短韻用寫长懷贈杜幽素', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["游宦勞牽網，風塵久化衣。","迹馳東苑路，望阻北巖扉。","及此承休告，聊將狎遯肥。","十旬俄委疾，三徑且殊歸。","茂陵窅難即，靈臺暫可依。","疲痾旅城寺，延想屬郊畿。","夕夢園林是，晨瞻邑里非。","綠疇良已穢，清濠曠不追。","野花何處落？山月幾秋輝。","彼美符商政，優游絕漢機。","高情物累遣，逸氣煙霞飛。","樂道方無悶，懷賢獨有違。","尊虛舊園酒，琴靜故人徽。","夏沼蓮初發，秋田麥稍稀。","何當攜手去，歲暮采芳菲。"]', '["游宦勞牽網，风塵久化衣。","迹驰东苑路，望阻北巖扉。","及此承休告，聊將狎遯肥。","十旬俄委疾，三徑且殊归。","茂陵窅难即，靈台暫可依。","疲痾旅城寺，延想屬郊畿。","夕梦园林是，晨瞻邑里非。","綠疇良已穢，清濠曠不追。","野花何处落？山月幾秋輝。","彼美符商政，優游絕漢機。","高情物累遣，逸氣煙霞飞。","乐道方無悶，懷賢独有違。","尊虛旧园酒，琴静故人徽。","夏沼蓮初發，秋田麦稍稀。","何當携手去，歲暮采芳菲。"]', '诗', 'shi', '', NULL, '田假限疾不獲還莊載想田園兼思親友率成短韻用寫長懷贈杜幽素 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2aeab157-f981-4aba-81f2-d4c5ef7bf666', '劉侍讀見和山邸十篇重申此贈', '劉侍读见和山邸十篇重申此贈', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["神嶽瑤池圃，仙宮玉樹林。","乘時警天御，清暑滌宸襟。","梁駕陪玄賞，淄庭掩翠岑。","對巖龍岫出，分壑雁池深。","簷迥松蘿映，窗高石鏡臨。","落泉奔澗響，驚吹助猿吟。","野氣迷涼燠，山花雜古今。","英藩盛賓侶，勝景想招尋。","踐徑披蘭葉，攀崖引桂陰。","穆生時泛醴，鄒子或調琴。","雉翳分塲合，魚鉤向浦沈。","朝遊極斜景，夕宴待橫參。","顧己慙鉛鍔，叨名齒玳簪。","暫依朱邸館，還暢白雲心。","丘壑信多美，煙霞得所欽。","寓言攄宿志，竊吹簡知音。","獎價踰珍石，酬文重振金。","方從仁智所，攜手濯清潯。"]', '["神嶽瑤池圃，仙宮玉樹林。","乘时警天御，清暑滌宸襟。","梁駕陪玄賞，淄庭掩翠岑。","对巖龙岫出，分壑雁池深。","簷迥松蘿映，窗高石镜臨。","落泉奔澗响，驚吹助猿吟。","野氣迷涼燠，山花杂古今。","英藩盛賓侶，勝景想招尋。","踐徑披蘭葉，攀崖引桂陰。","穆生时泛醴，鄒子或調琴。","雉翳分塲合，鱼鉤向浦沈。","朝游極斜景，夕宴待橫參。","顧己慙鉛鍔，叨名齒玳簪。","暫依朱邸館，還暢白云心。","丘壑信多美，煙霞得所欽。","寓言攄宿志，竊吹簡知音。","獎價踰珍石，酬文重振金。","方從仁智所，携手濯清潯。"]', '诗', 'shi', '', NULL, '劉侍讀見和山邸十篇重申此贈 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c45d0f8-9bf0-4aae-9c46-e6e3bc12012b', '晚秋喜雨', '晚秋喜雨', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["積陽躔首夏，隆旱屆徂秋。","炎威振皇服，歊景暴神州。","氣滌朝川朗，光澄夕照浮。","草木委林甸，禾黍悴原疇。","國懼流金眚，人深懸磬憂。","紫宸兢履薄，丹扆念推溝。","望肅壇場祀，冤申囹圄囚。","御車遷玉殿，薦菲撤瓊羞。","濟窘邦儲發，蠲窮井賦優。","服閑雲驥屏，冗術土龍修。","睿感通三極，天誠貫六幽。","夏祈良未擬，商禱詎爲儔。","穴蟻禎符應，山蛇毒影收。","騰雲八際滿，飛雨四溟周。","聚靄籠仙闕，連霏繞畫樓。","旱陂仍積水，涸沼更通流。","晚穗萎還結，寒苗瘁復抽。","九農歡歲阜，萬宇慶時休。","野洽如坻詠，途喧擊壤謳。","幸聞東李道，欣奉北場遊。"]', '["積陽躔首夏，隆旱屆徂秋。","炎威振皇服，歊景暴神州。","氣滌朝川朗，光澄夕照浮。","草木委林甸，禾黍悴原疇。","国懼流金眚，人深懸磬憂。","紫宸兢履薄，丹扆念推溝。","望肅壇場祀，冤申囹圄囚。","御车遷玉殿，薦菲撤瓊羞。","濟窘邦儲發，蠲窮井賦優。","服闲云驥屏，冗術土龙修。","睿感通三極，天誠貫六幽。","夏祈良未擬，商禱詎爲儔。","穴蟻禎符應，山蛇毒影收。","腾云八際满，飞雨四溟周。","聚靄籠仙闕，連霏繞畫楼。","旱陂仍積水，涸沼更通流。","晚穗萎還結，寒苗瘁复抽。","九農歡歲阜，万宇慶时休。","野洽如坻詠，途喧擊壤謳。","幸闻东李道，欣奉北場游。"]', '诗', 'shi', '', NULL, '晚秋喜雨 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a443d0c2-46b8-481f-a0f6-15aa3948abfe', '中秋月二首 一', '中秋月二首 一', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["盈缺青冥外，東風萬古吹。","何人種丹桂，不長出輪枝。"]', '["盈缺青冥外，东风万古吹。","何人種丹桂，不长出輪枝。"]', '诗', 'shi', '', NULL, '中秋月二首 一 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('707c3c73-4e8b-426e-b8a5-97ed10d8ca15', '中秋月二首 二', '中秋月二首 二', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["圓魄上寒空，皆言四海同。","安知千里外，不有雨兼風。"]', '["圓魄上寒空，皆言四海同。","安知千里外，不有雨兼风。"]', '诗', 'shi', '', NULL, '中秋月二首 二 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cf8203f-4163-4ad6-b5e0-e6ff9bc9bbe7', '侍宴桃花園詠花應制', '侍宴桃花园詠花應制', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["歲去無言忽顦顇，時來含笑吐氛氳。","不能擁路迷仙客，故欲開蹊待聖君。"]', '["歲去無言忽顦顇，时来含笑吐氛氳。","不能擁路迷仙客，故欲开蹊待聖君。"]', '诗', 'shi', '', NULL, '侍宴桃花園詠花應制 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18703f50-4ab1-4cfc-9037-987402b42383', '奉和聖製幸韋嗣立山莊應制', '奉和聖製幸韋嗣立山莊應制', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["萬騎千官擁帝車，八龍三馬訪仙家。","鳳皇原上開青壁，鸚鵡杯中弄紫霞。"]', '["万騎千官擁帝车，八龙三马訪仙家。","鳳皇原上开青壁，鸚鵡杯中弄紫霞。"]', '诗', 'shi', '', NULL, '奉和聖製幸韋嗣立山莊應制 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c5db886-fc4e-4c78-9a85-e013c1609595', '遊苑遇雪應制', '游苑遇雪應制', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["散漫祥雲逐聖回，飄颻瑞雪繞天來。","不能落後爭飛絮，故欲迎前賽早梅。"]', '["散漫祥云逐聖回，飄颻瑞雪繞天来。","不能落後爭飞絮，故欲迎前賽早梅。"]', '诗', 'shi', '', NULL, '遊苑遇雪應制 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de0e2fd0-1828-40af-b495-60b4a7f97bce', '送司馬先生', '送司马先生', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["蓬閣桃源兩處分，人間海上不相聞。","一朝琴裏悲黃鶴，何日山頭望白雲。"]', '["蓬閣桃源兩处分，人间海上不相闻。","一朝琴裏悲黄鹤，何日山头望白云。"]', '诗', 'shi', '', NULL, '送司馬先生 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cac9d77-a4b7-47c2-8bbf-eac58805e5e4', '風', '风', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["解落三秋葉，能開二月花。","過江千尺浪，入竹萬竿斜。"]', '["解落三秋葉，能开二月花。","過江千尺浪，入竹万竿斜。"]', '诗', 'shi', '', NULL, '風 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24406ef9-6653-4c93-982a-1afa1bb83f9d', '上清暉閤遇雪', '上清暉閤遇雪', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["千鍾聖酒御筵披，六出祥英亂繞枝。","即此神仙對瓊圃，何須轍跡向瑤池。"]', '["千鍾聖酒御筵披，六出祥英亂繞枝。","即此神仙对瓊圃，何須轍跡向瑤池。"]', '诗', 'shi', '', NULL, '上清暉閤遇雪 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a12454e0-add9-4d8e-b0e0-42b656640ef0', '石淙', '石淙', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["羽蓋龍旗下絕冥，蘭除薜幄坐雲扃。","鳥和百籟疑調管，花發千巖似畫屏。","金竈浮煙朝漠漠，石牀寒水夜泠泠。","自然碧洞窺仙境，何必丹丘是福庭。"]', '["羽蓋龙旗下絕冥，蘭除薜幄坐云扃。","鸟和百籟疑調管，花發千巖似畫屏。","金竈浮煙朝漠漠，石牀寒水夜泠泠。","自然碧洞窺仙境，何必丹丘是福庭。"]', '诗', 'shi', '', NULL, '石淙 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8c48f21-10ec-4d93-b5ac-0c27e1183c34', '南海亂石山作', '南海亂石山作', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["漲海積稽天，羣山高嶪地。","相傳稱亂石，圖典失其事。","懸危悉可驚，大小都不類。","乍將雲島極，還與星河次。","上聳忽如飛，下臨仍欲墜。","朝暾赩丹紫，夜魄炯青翠。","穹崇霧雨蓄，幽隱靈仙閟。","萬尋挂鶴巢，千丈垂猿臂。","昔去景風涉，今來姑洗至。","觀此得詠歌，長時想精異。"]', '["漲海積稽天，羣山高嶪地。","相傳稱亂石，圖典失其事。","懸危悉可驚，大小都不類。","乍將云島極，還與星河次。","上聳忽如飞，下臨仍欲墜。","朝暾赩丹紫，夜魄炯青翠。","穹崇霧雨蓄，幽隐靈仙閟。","万尋挂鹤巢，千丈垂猿臂。","昔去景风涉，今来姑洗至。","观此得詠歌，长时想精異。"]', '诗', 'shi', '', NULL, '南海亂石山作 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b89b383-f06e-41e2-8d9b-edc10c39b2b0', '送和西蕃使', '送和西蕃使', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["使出鳳皇池，京師陽春晚。","聖朝尚邊策，詔諭兵戈偃。","拜手明光殿，搖心上林苑。","種落踰青羌，關山度赤坂。","疆場及無事，雅歌而餐飯。","寧獨錫和戎，更當封定遠。"]', '["使出鳳皇池，京師陽春晚。","聖朝尚邊策，詔諭兵戈偃。","拜手明光殿，搖心上林苑。","種落踰青羌，关山度赤坂。","疆場及無事，雅歌而餐飯。","寧独錫和戎，更當封定远。"]', '诗', 'shi', '', NULL, '送和西蕃使 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfa5b7e8-1eef-47be-aa88-898797cb41cd', '蓬萊三殿侍宴奉敕詠終南山應制', '蓬萊三殿侍宴奉敕詠終南山應制', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["北斗挂城邊，南山倚殿前。","雲標金闕迥，樹杪玉堂懸。","半嶺通佳氣，中峰繞瑞煙。","小臣持獻壽，長此戴堯天。"]', '["北斗挂城邊，南山倚殿前。","云標金闕迥，樹杪玉堂懸。","半嶺通佳氣，中峰繞瑞煙。","小臣持獻壽，长此戴堯天。"]', '诗', 'shi', '', NULL, '蓬萊三殿侍宴奉敕詠終南山應制 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0dace816-ab80-4f3c-a87c-1ac6a49d7795', '望春亭侍遊應詔', '望春亭侍游應詔', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["帝出明光殿，天臨太液池。","堯樽隨步輦，舜樂繞行麾。","萬壽禎祥獻，三春景物滋。","小臣同酌海，歌頌荅無爲。"]', '["帝出明光殿，天臨太液池。","堯樽隨步輦，舜乐繞行麾。","万壽禎祥獻，三春景物滋。","小臣同酌海，歌頌荅無爲。"]', '诗', 'shi', '', NULL, '望春亭侍遊應詔 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63ecd5ea-2e61-4060-a925-27c350750650', '宿羽亭侍宴應制', '宿羽亭侍宴應制', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["步輦千門出，離宮二月開。","風光新柳報，宴賞落花催。","碧水搖空閣，青山繞吹臺。","聖情留晚興，歌管送餘杯。"]', '["步輦千门出，離宮二月开。","风光新柳報，宴賞落花催。","碧水搖空閣，青山繞吹台。","聖情留晚兴，歌管送餘杯。"]', '诗', 'shi', '', NULL, '宿羽亭侍宴應制 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d466ddc1-2819-4adf-8585-10f81915aff7', '歲夜安樂公主滿月侍宴應制', '歲夜安乐公主满月侍宴應制', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["戚里生昌胤，天杯宴重臣。","畫樓初滿月，香殿早迎春。","睿作堯君寶，孫謀梁國珍。","明朝元會日，萬壽樂章陳。"]', '["戚里生昌胤，天杯宴重臣。","畫楼初满月，香殿早迎春。","睿作堯君寶，孫謀梁国珍。","明朝元會日，万壽乐章陳。"]', '诗', 'shi', '', NULL, '歲夜安樂公主滿月侍宴應制 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b37eae8-ad47-4b31-9353-976ba804c48d', '奉和七夕侍宴兩儀殿應制', '奉和七夕侍宴兩儀殿應制', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["一年銜別怨，七夕始言歸。","斂淚開星靨，微步動雲衣。","天迴兔欲落，河曠鵲停飛。","那堪盡此夜，復往弄殘機。"]', '["一年銜別怨，七夕始言归。","斂泪开星靨，微步动云衣。","天迴兔欲落，河曠鵲停飞。","那堪尽此夜，复往弄殘機。"]', '诗', 'shi', '', NULL, '奉和七夕侍宴兩儀殿應制 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6548b26-739c-42c1-b6af-47ebddf23625', '大酺', '大酺', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["聖后乘乾日，皇明御曆辰。","紫宮初啓坐，蒼璧正臨春。","雷雨垂膏澤，金錢贈下人。","詔酺歡賞徧，交泰覩惟新。"]', '["聖后乘乾日，皇明御曆辰。","紫宮初啓坐，蒼璧正臨春。","雷雨垂膏澤，金錢贈下人。","詔酺歡賞徧，交泰覩惟新。"]', '诗', 'shi', '', NULL, '大酺 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46364a14-cc64-4f3f-8601-b9035a1c9866', '賦得妾薄命', '賦得妾薄命', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["草綠長門掩，苔青永巷幽。","寵移新愛奪，淚落故情留。","啼鳥驚殘夢，飛花攪獨愁。","自憐春色罷，團扇復迎秋。"]', '["草綠长门掩，苔青永巷幽。","寵移新愛奪，泪落故情留。","啼鸟驚殘梦，飞花攪独愁。","自怜春色罷，團扇复迎秋。"]', '诗', 'shi', '', NULL, '賦得妾薄命 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1a3ce19-0b48-456c-b6ce-1657eb6de21c', '和韋承慶過義陽公主山池五首 一', '和韋承慶過義陽公主山池五首 一', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["野興城中發，朝英物外求。","情懸朱紱望，契動赤泉遊。","海燕巢書閣，山雞舞畫樓。","雨餘清晚夏，共坐北巖幽。"]', '["野兴城中發，朝英物外求。","情懸朱紱望，契动赤泉游。","海燕巢书閣，山雞舞畫楼。","雨餘清晚夏，共坐北巖幽。"]', '诗', 'shi', '', NULL, '和韋承慶過義陽公主山池五首 一 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2eedc678-3efb-4b1c-bba0-8f096c3dcba8', '和韋承慶過義陽公主山池五首 二', '和韋承慶過義陽公主山池五首 二', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["逕轉危峰逼，橋回缺岸妨。","玉泉移酒味，石髓換粳香。","綰霧青絲弱，牽風紫蔓長。","猶言宴樂少，別向後池塘。"]', '["逕轉危峰逼，橋回缺岸妨。","玉泉移酒味，石髓換粳香。","綰霧青絲弱，牽风紫蔓长。","猶言宴乐少，別向後池塘。"]', '诗', 'shi', '', NULL, '和韋承慶過義陽公主山池五首 二 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52b04458-2e97-4c40-86fd-6f4a17219b54', '和韋承慶過義陽公主山池五首 三', '和韋承慶過義陽公主山池五首 三', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["攜琴遶碧沙，搖筆弄青霞。","杜若幽庭草，芙蓉曲沼花。","宴遊成野客，形勝得仙家。","往往留仙步，登攀日易斜。"]', '["携琴遶碧沙，搖笔弄青霞。","杜若幽庭草，芙蓉曲沼花。","宴游成野客，形勝得仙家。","往往留仙步，登攀日易斜。"]', '诗', 'shi', '', NULL, '和韋承慶過義陽公主山池五首 三 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfb6764d-41ce-4929-946c-2bce0573be04', '和韋承慶過義陽公主山池五首 四', '和韋承慶過義陽公主山池五首 四', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["攢石當軒倚，懸泉度牖飛。","鹿麛衝妓席，鶴子曳童衣。","園果嘗難遍，池蓮摘未稀。","卷簾唯待月，應在醉中歸。"]', '["攢石當軒倚，懸泉度牖飞。","鹿麛衝妓席，鹤子曳童衣。","园果嘗难遍，池蓮摘未稀。","卷簾唯待月，應在醉中归。"]', '诗', 'shi', '', NULL, '和韋承慶過義陽公主山池五首 四 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c22e201-31c0-4927-9685-893955b78356', '和韋承慶過義陽公主山池五首 五', '和韋承慶過義陽公主山池五首 五', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["賞翫期他日，高深愛此時。","池分八水背，峰作九山疑。","地靜魚偏逸，人閑鳥欲欺。","青溪留別興，更與白雲期。"]', '["賞翫期他日，高深愛此时。","池分八水背，峰作九山疑。","地静鱼偏逸，人闲鸟欲欺。","青溪留別兴，更與白云期。"]', '诗', 'shi', '', NULL, '和韋承慶過義陽公主山池五首 五 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b881b056-6d92-45e8-9620-4710a375776f', '和晉陵陸丞早春遊望', '和晉陵陸丞早春游望', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["獨有宦遊人，偏驚物候新。","雲霞出海曙，梅柳渡江春。","淑氣催黃鳥，晴光轉綠蘋。","忽聞歌古調，歸思欲霑巾。"]', '["独有宦游人，偏驚物候新。","云霞出海曙，梅柳渡江春。","淑氣催黄鸟，晴光轉綠蘋。","忽闻歌古調，归思欲霑巾。"]', '诗', 'shi', '', NULL, '和晉陵陸丞早春遊望 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c115189b-63c5-41cb-b9f9-5e716e1003c7', '秋夜宴臨津鄭明府宅', '秋夜宴臨津鄭明府宅', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["行止皆無地，招尋獨有君。","酒中堪累月，身外即浮雲。","露白宵鐘徹，風清曉漏聞。","坐攜餘興往，還似未離羣。"]', '["行止皆無地，招尋独有君。","酒中堪累月，身外即浮云。","露白宵鐘徹，风清晓漏闻。","坐携餘兴往，還似未離羣。"]', '诗', 'shi', '', NULL, '秋夜宴臨津鄭明府宅 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62e870d6-3a23-440d-a5f9-f7df841f7f4a', '和康五庭芝望月有懷', '和康五庭芝望月有懷', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["明月高秋迥，愁人獨夜看。","暫將弓並曲，飜與扇俱團。","霧濯清輝苦，風飄素影寒。","羅衣一此鑒，頓使別離難。"]', '["明月高秋迥，愁人独夜看。","暫將弓並曲，飜與扇俱團。","霧濯清輝苦，风飄素影寒。","羅衣一此鑒，頓使別離难。"]', '诗', 'shi', '', NULL, '和康五庭芝望月有懷 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb73222f-8a80-4905-8441-08ce08c91e0e', '登襄陽城', '登襄陽城', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["旅客三秋至，層城四望開。","楚山橫地出，漢水接天回。","冠蓋非新里，章華即舊臺。","習池風景異，歸路滿塵埃。"]', '["旅客三秋至，層城四望开。","楚山橫地出，漢水接天回。","冠蓋非新里，章华即旧台。","習池风景異，归路满塵埃。"]', '诗', 'shi', '', NULL, '登襄陽城 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69e6a763-2664-4a5f-bad7-4cd097c51844', '旅寓安南', '旅寓安南', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["交趾殊風候，寒遲暖復催。","仲冬山果熟，正月野花開。","積雨生昏霧，輕霜下震雷。","故鄉踰萬里，客思倍從來。"]', '["交趾殊风候，寒遲暖复催。","仲冬山果熟，正月野花开。","積雨生昏霧，轻霜下震雷。","故乡踰万里，客思倍從来。"]', '诗', 'shi', '', NULL, '旅寓安南 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('189d4bfd-d1fa-401e-9c69-f2a5bf2839b9', '春日懷歸', '春日懷归', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["心是傷歸望，春歸異往年。","河山鑒魏闕，桑梓憶秦川。","花雜芳園鳥，風和綠野煙。","更懷歡賞地，車馬洛橋邊。"]', '["心是傷归望，春归異往年。","河山鑒魏闕，桑梓憶秦川。","花杂芳园鸟，风和綠野煙。","更懷歡賞地，车马洛橋邊。"]', '诗', 'shi', '', NULL, '春日懷歸 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('796333f6-7fe6-47f0-aa58-9d6b89a14718', '代張侍御傷美人', '代張侍御傷美人', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["二八泉扉掩，帷屏寵愛空。","淚痕消夜燭，愁緒亂春風。","巧笑人疑在，新妝曲未終。","應憐脂粉氣，留著舞衣中。"]', '["二八泉扉掩，帷屏寵愛空。","泪痕消夜燭，愁緒亂春风。","巧笑人疑在，新妝曲未終。","應怜脂粉氣，留著舞衣中。"]', '诗', 'shi', '', NULL, '代張侍御傷美人 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e63a20b-7a26-41b9-9e72-4c5bcf0f0efa', '送高郎中北使', '送高郎中北使', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["北狄願和親，東京發使臣。","馬銜邊地雪，衣染異方塵。","歲月催行旅，恩榮變苦辛。","歌鐘期重錫，拜手落花春。"]', '["北狄願和親，东京發使臣。","马銜邊地雪，衣染異方塵。","歲月催行旅，恩榮变苦辛。","歌鐘期重錫，拜手落花春。"]', '诗', 'shi', '', NULL, '送高郎中北使 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e398bdb7-e2fa-4bba-b19f-45bdc9074fc1', '都尉山亭', '都尉山亭', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["紫藤縈葛藟，綠刺罥薔薇。","下釣看魚躍，探巢畏鳥飛。","葉疎荷已晚，枝亞果新肥。","勝迹都無限，只應伴月歸。"]', '["紫藤縈葛藟，綠刺罥薔薇。","下釣看鱼躍，探巢畏鸟飞。","葉疎荷已晚，枝亞果新肥。","勝迹都無限，只應伴月归。"]', '诗', 'shi', '', NULL, '都尉山亭 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1658fad0-6e6c-4d3f-aa5a-7b21450ff96a', '夏日過鄭七山齋', '夏日過鄭七山斋', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["共有樽中好，言尋谷口來。","薜蘿山逕入，荷芰水亭開。","日氣含殘雨，雲陰送晚雷。","洛陽鐘鼓至，車馬繫遲回。"]', '["共有樽中好，言尋谷口来。","薜蘿山逕入，荷芰水亭开。","日氣含殘雨，云陰送晚雷。","洛陽鐘鼓至，车马繫遲回。"]', '诗', 'shi', '', NULL, '夏日過鄭七山齋 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25e70bc0-e40f-499e-92ff-d2c546f529a7', '送崔融', '送崔融', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["君王行出將，書記遠從征。","祖帳連河闕，軍麾動洛城。","旌旃朝朔氣，笳吹夜邊聲。","坐覺煙塵掃，秋風古北平。"]', '["君王行出將，书記远從征。","祖帳連河闕，軍麾动洛城。","旌旃朝朔氣，笳吹夜邊声。","坐覺煙塵掃，秋风古北平。"]', '诗', 'shi', '', NULL, '送崔融 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('926afdf1-dd5b-44a9-be3a-62dda48c07e8', '經行嵐州', '經行嵐州', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["北地春光晚，邊城氣候寒。","往來花不發，新舊雪仍殘。","水作琴中聽，山疑畫裏看。","自驚牽遠役，艱險促征鞍。"]', '["北地春光晚，邊城氣候寒。","往来花不發，新旧雪仍殘。","水作琴中听，山疑畫裏看。","自驚牽远役，艱險促征鞍。"]', '诗', 'shi', '', NULL, '經行嵐州 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7efe3c86-7478-46c1-9fef-aa02594af9fb', '重九日宴江陰', '重九日宴江陰', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["蟋蟀期歸晚，茱萸節候新。","降霜青女月，送酒白衣人。","高興要長壽，卑棲隔近臣。","龍沙即此地，舊俗坐爲鄰。"]', '["蟋蟀期归晚，茱萸節候新。","降霜青女月，送酒白衣人。","高兴要长壽，卑棲隔近臣。","龙沙即此地，旧俗坐爲鄰。"]', '诗', 'shi', '', NULL, '重九日宴江陰 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea021f19-e544-4b26-abaa-211a23a2e499', '除夜有懷', '除夜有懷', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["故節當歌守，新年把燭迎。","冬氛戀虬箭，春色候雞鳴。","興盡聞壺覆，宵闌見斗橫。","還將萬億壽，更謁九重城。"]', '["故節當歌守，新年把燭迎。","冬氛戀虬箭，春色候雞鳴。","兴尽闻壺覆，宵闌见斗橫。","還將万億壽，更謁九重城。"]', '诗', 'shi', '', NULL, '除夜有懷 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d4d8531-ec39-4bde-8f77-718cafe5432a', '晦日宴遊', '晦日宴游', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["日晦隨蓂莢，春情著杏花。","解紳宜就水，張幕會連沙。","歌管風輕度，池臺日半斜。","更看金谷騎，爭向石崇家。"]', '["日晦隨蓂莢，春情著杏花。","解紳宜就水，張幕會連沙。","歌管风轻度，池台日半斜。","更看金谷騎，爭向石崇家。"]', '诗', 'shi', '', NULL, '晦日宴遊 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4378da93-d144-4fbf-beba-45173f7d1f86', '七夕', '七夕', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["白露含明月，青霞斷絳河。","天街七襄轉，閣道二神過。","袨服鏘環珮，香筵拂綺羅。","年年今夜盡，機杼別情多。"]', '["白露含明月，青霞斷絳河。","天街七襄轉，閣道二神過。","袨服鏘环珮，香筵拂綺羅。","年年今夜尽，機杼別情多。"]', '诗', 'shi', '', NULL, '七夕 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bfce051-60ed-46bf-9bc3-aa8b7b4f4aac', '守歲侍宴應制', '守歲侍宴應制', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["季冬除夜接新年，帝子王孫捧御筵。","宮闕星河低拂樹，殿廷燈燭上薰天。","彈弦奏節梅風入，對局探鉤柏酒傳。","欲向正元歌萬壽，暫留歡賞寄春前。"]', '["季冬除夜接新年，帝子王孫捧御筵。","宮闕星河低拂樹，殿廷灯燭上薰天。","彈弦奏節梅风入，对局探鉤柏酒傳。","欲向正元歌万壽，暫留歡賞寄春前。"]', '诗', 'shi', '', NULL, '守歲侍宴應制 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3b5b535-b51f-4c68-8bf5-070617049ca4', '大酺', '大酺', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["毘陵震澤九州通，士女歡娛萬國同。","伐鼓撞鐘驚海上，新妝袨服照江東。","梅花落處疑殘雪，柳葉開時任好風。","火德雲官逢道泰，天長地久屬年豐。"]', '["毘陵震澤九州通，士女歡娛万国同。","伐鼓撞鐘驚海上，新妝袨服照江东。","梅花落处疑殘雪，柳葉开时任好风。","火德云官逢道泰，天长地久屬年豐。"]', '诗', 'shi', '', NULL, '大酺 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9be6ee69-ac5d-4f11-ba9f-b11b277d93b1', '春日京中有懷', '春日京中有懷', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["今年遊寓獨遊秦，愁思看春不當春。","上林苑裏花徒發，細柳營前葉漫新。","公子南橋應盡興，將軍西第幾留賓。","寄語洛城風日道，明年春色倍還人。"]', '["今年游寓独游秦，愁思看春不當春。","上林苑裏花徒發，細柳營前葉漫新。","公子南橋應尽兴，將軍西第幾留賓。","寄語洛城风日道，明年春色倍還人。"]', '诗', 'shi', '', NULL, '春日京中有懷 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f79247a6-7cf2-4d27-a6d9-bc2b6727eda9', '扈從出長安應制', '扈從出长安應制', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["分野都畿列，時乘六御均。","京師舊西幸，洛道此東巡。","文物驅三統，聲名走百神。","龍旗縈漏夕，鳳輦拂鈎陳。","撫迹地靈古，游情皇鑒新。","山追散馬日，水憶釣魚人。","禹食傳中使，堯樽遍下臣。","省方稱國阜，問道識風淳。","歲晚天行吉，年豐景從親。","歡娛包歷代，宇宙忽疑春。"]', '["分野都畿列，时乘六御均。","京師旧西幸，洛道此东巡。","文物驱三統，声名走百神。","龙旗縈漏夕，鳳輦拂鈎陳。","撫迹地靈古，游情皇鑒新。","山追散马日，水憶釣鱼人。","禹食傳中使，堯樽遍下臣。","省方稱国阜，问道識风淳。","歲晚天行吉，年豐景從親。","歡娛包歷代，宇宙忽疑春。"]', '诗', 'shi', '', NULL, '扈從出長安應制 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed0ebb3a-b2b4-4529-8070-caf23fb9633c', '春日江津遊望', '春日江津游望', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["旅客搖邊思，春江弄晚晴。","煙銷垂柳弱，霧捲落花輕。","飛棹乘空下，回流向日平。","鳥啼移幾處，蝶舞亂相迎。","忽歎人皆濁，堤防水至清。","谷王常不讓，深可戒中盈。"]', '["旅客搖邊思，春江弄晚晴。","煙銷垂柳弱，霧捲落花轻。","飞棹乘空下，回流向日平。","鸟啼移幾处，蝶舞亂相迎。","忽歎人皆濁，堤防水至清。","谷王常不讓，深可戒中盈。"]', '诗', 'shi', '', NULL, '春日江津遊望 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19ebf97a-e873-429e-b074-750258f377fa', '泛舟送鄭卿入京', '泛舟送鄭卿入京', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["帝坐蓬萊殿，恩追社稷臣。","長安遙向日，宗伯正乘春。","相宅開基地，傾都送別人。","行舟縈淥水，列戟滿紅塵。","酒助歡娛洽，風催景氣新。","此時光乃命，誰爲惜無津。"]', '["帝坐蓬萊殿，恩追社稷臣。","长安遙向日，宗伯正乘春。","相宅开基地，傾都送別人。","行舟縈淥水，列戟满紅塵。","酒助歡娛洽，风催景氣新。","此时光乃命，誰爲惜無津。"]', '诗', 'shi', '', NULL, '泛舟送鄭卿入京 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75a1bf2b-7eb6-44fe-af37-f7220ae97faa', '度石門山', '度石门山', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["石門千仞斷，迸水落遙空。","道束懸崖半，橋欹絕澗中。","仰攀人屢息，直下騎纔通。","泥擁奔虵徑，雲埋伏獸叢。","星躔牛斗北，地脈象牙東。","開塞隨行變，高深觸望同。","江聲連驟雨，日氣抱殘虹。","未改朱明律，先含白露風。","堅貞深不憚，險澁諒難窮。","有異登臨賞，徒爲造化功。"]', '["石门千仞斷，迸水落遙空。","道束懸崖半，橋欹絕澗中。","仰攀人屢息，直下騎纔通。","泥擁奔虵徑，云埋伏獸叢。","星躔牛斗北，地脈象牙东。","开塞隨行变，高深觸望同。","江声連驟雨，日氣抱殘虹。","未改朱明律，先含白露风。","堅貞深不憚，險澁諒难窮。","有異登臨賞，徒爲造化功。"]', '诗', 'shi', '', NULL, '度石門山 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14d0288b-6a5a-454d-b12e-e802574f9d1a', '贈崔融二十韻', '贈崔融二十韻', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["十年俱薄宦，萬里各他方。","雲天斷書札，風土異炎涼。","太息幽蘭紫，勞歌奇樹黃。","日疑懷叔度，夜似憶真長。","北使從江表，東歸在洛陽。","相逢慰疇昔，相對敘存亡。","草深窮巷毀，竹盡故園荒。","雅節君彌固，衰顏余自傷。","人事盈虛改，交遊寵辱妨。","雀羅爭去翟，鶴氅競尋王。","思極歡娛至，朋情詎可忘。","琴樽橫宴席，巖谷臥詞場。","連騎追佳賞，城中及路傍。","三川宿雨霽，四月晚花芳。","復此開懸榻，寧唯入後堂。","興酣鴝鵒舞，言洽鳳皇翔。","高選俄遷職，嚴程已飭裝。","撫躬銜道義，攜手戀輝光。","玉振先推美，金銘舊所防。","勿嗟離別易，行役共時康。"]', '["十年俱薄宦，万里各他方。","云天斷书札，风土異炎涼。","太息幽蘭紫，勞歌奇樹黄。","日疑懷叔度，夜似憶真长。","北使從江表，东归在洛陽。","相逢慰疇昔，相对敘存亡。","草深窮巷毀，竹尽故园荒。","雅節君彌固，衰顏余自傷。","人事盈虛改，交游寵辱妨。","雀羅爭去翟，鹤氅競尋王。","思極歡娛至，朋情詎可忘。","琴樽橫宴席，巖谷臥词場。","連騎追佳賞，城中及路傍。","三川宿雨霽，四月晚花芳。","复此开懸榻，寧唯入後堂。","兴酣鴝鵒舞，言洽鳳皇翔。","高選俄遷職，嚴程已飭裝。","撫躬銜道義，携手戀輝光。","玉振先推美，金銘旧所防。","勿嗟離別易，行役共时康。"]', '诗', 'shi', '', NULL, '贈崔融二十韻 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2aea77b5-e023-4478-bcf9-ee6ddf01a434', '贈蘇味道', '贈蘇味道', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["北地寒應苦，南庭戍未歸。","邊聲亂羗笛，朔氣卷戎衣。","雨雪關山暗，風霜草木稀。","胡兵戰欲盡，虜騎獵猶肥。","雁塞何時入，龍城幾度圍。","據鞍雄劒動，插筆羽書飛。","輿駕還京邑，朋遊滿帝畿。","方期來獻凱，歌舞共春輝。"]', '["北地寒應苦，南庭戍未归。","邊声亂羗笛，朔氣卷戎衣。","雨雪关山暗，风霜草木稀。","胡兵戰欲尽，虜騎獵猶肥。","雁塞何时入，龙城幾度圍。","據鞍雄劒动，插笔羽书飞。","輿駕還京邑，朋游满帝畿。","方期来獻凱，歌舞共春輝。"]', '诗', 'shi', '', NULL, '贈蘇味道 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58447b81-6032-4ef6-ade1-2fd3fefe0a89', '和李大夫嗣真奉使存撫河東', '和李大夫嗣真奉使存撫河东', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["六位乾坤動，三微曆數遷。","謳歌移火德，圖讖在金天。","子月開階統，房星受命年。","禎符龍馬出，寶籙鳳凰傳。","地即交風雨，都仍卜澗瀍。","明堂唯御極，清廟乃尊先。","不宰神功運，無爲大象懸。","八荒平物土，四海接人煙。","已屬羣生泰，猶言至道偏。","璽書傍問俗，旌節近推賢。","秩比司空位，官臨御史員。","雄詞執刀筆，直諫罷樓船。","國有大臣器，朝加小會筵。","將行備禮樂，送別仰神仙。","城闕周京轉，關河陝服連。","稍觀汾水曲，俄指絳臺前。","姑射聊長望，平陽遂宛然。","舜耕餘草木，禹鑿舊山川。","昔出諸侯上，無何霸業全。","中軍歸戰敵，外府絕兵權。","隱隱帝鄉遠，瞻瞻肅命虔。","西河偃風俗，東壁挂星躔。","井邑枌榆社，陵園松柏田。","榮光晴掩代，佳氣曉侵燕。","雨霈鴻私滌，風行睿旨宣。","煢嫠訪疾苦，屠釣采貞堅。","人樂逢刑措，時康洽賞延。","賜踰秦氏級，恩倍漢家錢。","擁傳咸翹首，稱觴競比肩。","拜迎彌道路，舞詠溢郊鄽。","殺氣西衡白，窮陰北暝玄。","飛霜遙渡海，殘月迥臨邊。","緬邈朝廷問，周流朔塞旋。","興來探馬策，俊發抱龍泉。","學總八千卷，文傾三百篇。","澄清得使者，作頌有人焉。","莫以崇班閡，而云勝託捐。","偉材何磊落，陋質幾翩翾。","江海寧爲讓，巴渝轉自牽。","一聞歌聖道，助曲荷陶甄。"]', '["六位乾坤动，三微曆數遷。","謳歌移火德，圖讖在金天。","子月开階統，房星受命年。","禎符龙马出，寶籙鳳凰傳。","地即交风雨，都仍卜澗瀍。","明堂唯御極，清廟乃尊先。","不宰神功運，無爲大象懸。","八荒平物土，四海接人煙。","已屬羣生泰，猶言至道偏。","璽书傍问俗，旌節近推賢。","秩比司空位，官臨御史員。","雄词執刀笔，直諫罷楼船。","国有大臣器，朝加小會筵。","將行備禮乐，送別仰神仙。","城闕周京轉，关河陝服連。","稍观汾水曲，俄指絳台前。","姑射聊长望，平陽遂宛然。","舜耕餘草木，禹鑿旧山川。","昔出諸侯上，無何霸業全。","中軍归戰敵，外府絕兵權。","隐隐帝乡远，瞻瞻肅命虔。","西河偃风俗，东壁挂星躔。","井邑枌榆社，陵园松柏田。","榮光晴掩代，佳氣晓侵燕。","雨霈鴻私滌，风行睿旨宣。","煢嫠訪疾苦，屠釣采貞堅。","人乐逢刑措，时康洽賞延。","賜踰秦氏級，恩倍漢家錢。","擁傳咸翹首，稱觴競比肩。","拜迎彌道路，舞詠溢郊鄽。","殺氣西衡白，窮陰北暝玄。","飞霜遙渡海，殘月迥臨邊。","緬邈朝廷问，周流朔塞旋。","兴来探马策，俊發抱龙泉。","学總八千卷，文傾三百篇。","澄清得使者，作頌有人焉。","莫以崇班閡，而云勝託捐。","偉材何磊落，陋質幾翩翾。","江海寧爲讓，巴渝轉自牽。","一闻歌聖道，助曲荷陶甄。"]', '诗', 'shi', '', NULL, '和李大夫嗣真奉使存撫河東 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcda09e6-2d91-449a-8ef2-2a996746a9ce', '贈蘇綰書記', '贈蘇綰书記', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["知君書記本翩翩，爲許從戎赴朔邊。","紅粉樓中應計日，燕支山下莫經年。"]', '["知君书記本翩翩，爲許從戎赴朔邊。","紅粉楼中應計日，燕支山下莫經年。"]', '诗', 'shi', '', NULL, '贈蘇綰書記 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2adf2ec4-c087-4b64-8eb0-ce60b10ce54c', '渡湘江', '渡湘江', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["遲日園林悲昔遊，今春花鳥作邊愁。","獨憐京國人南竄，不似湘江水北流。"]', '["遲日园林悲昔游，今春花鸟作邊愁。","独怜京国人南竄，不似湘江水北流。"]', '诗', 'shi', '', NULL, '渡湘江 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ba1c9a5-409c-461e-b8a2-1408a4590e4c', '戲贈趙使君美人', '戲贈趙使君美人', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["紅粉青娥暎楚雲，桃花馬上石榴帬。","羅敷獨向東方去，謾學他家作使君。"]', '["紅粉青娥暎楚云，桃花马上石榴帬。","羅敷独向东方去，謾学他家作使君。"]', '诗', 'shi', '', NULL, '戲贈趙使君美人 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('772fe6c9-b1e8-4b96-952b-abe4b4f9b4a7', '三婦豔', '三婦豔', 'ccecc1bb-eb6f-4fb5-be66-3bade24af40f', '唐', '["大婦裁紈素，中婦弄明璫。","小婦多姿態，登樓紅粉妝。","丈人且安坐，初日漸流光。"]', '["大婦裁紈素，中婦弄明璫。","小婦多姿態，登楼紅粉妝。","丈人且安坐，初日漸流光。"]', '诗', 'shi', '', NULL, '三婦豔 董思恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4304996f-9598-4419-9fb5-4eeeaf762d64', '感懷', '感懷', 'ccecc1bb-eb6f-4fb5-be66-3bade24af40f', '唐', '["野郊愴新別，河橋非舊餞。","慘日映峰沈，愁雲隨蓋轉。","哀笳時斷續，悲旌乍舒卷。","望望情何極，浪浪淚空泫。","無復昔時人，芳春共誰遣。"]', '["野郊愴新別，河橋非旧餞。","慘日映峰沈，愁云隨蓋轉。","哀笳时斷續，悲旌乍舒卷。","望望情何極，浪浪泪空泫。","無复昔时人，芳春共誰遣。"]', '诗', 'shi', '', NULL, '感懷 董思恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c19cf735-ff9e-4a31-a731-bf2db25bf91c', '守歲二首 一', '守歲二首 一', 'ccecc1bb-eb6f-4fb5-be66-3bade24af40f', '唐', '["暮景斜芳殿，年華麗綺宮。","寒辭去冬雪，暖帶入春風。","階馥舒梅素，盤花卷燭紅。","共歡新故歲，迎送一宵中。"]', '["暮景斜芳殿，年华丽綺宮。","寒辞去冬雪，暖带入春风。","階馥舒梅素，盤花卷燭紅。","共歡新故歲，迎送一宵中。"]', '诗', 'shi', '', NULL, '守歲二首 一 董思恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b37135d-0c99-4f1e-872b-5a88d9c74b5a', '守歲二首 二', '守歲二首 二', 'ccecc1bb-eb6f-4fb5-be66-3bade24af40f', '唐', '["歲陰窮暮紀，獻節啓新芳。","冬盡今宵促，年開明日長。","冰銷出鏡水，梅散入風香。","對此歡終宴，傾壺待曙光。"]', '["歲陰窮暮紀，獻節啓新芳。","冬尽今宵促，年开明日长。","冰銷出镜水，梅散入风香。","对此歡終宴，傾壺待曙光。"]', '诗', 'shi', '', NULL, '守歲二首 二 董思恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da230f09-1dbc-4999-b819-26c94ca9daa5', '昭君怨二首 一', '昭君怨二首 一', 'ccecc1bb-eb6f-4fb5-be66-3bade24af40f', '唐', '["新年猶尚小，那堪遠聘秦。","裾衫霑馬汗，眉黛染胡塵。","舉眼無相識，路逢皆異人。","唯有梅將李，猶帶故鄉春。"]', '["新年猶尚小，那堪远聘秦。","裾衫霑马汗，眉黛染胡塵。","舉眼無相識，路逢皆異人。","唯有梅將李，猶带故乡春。"]', '诗', 'shi', '', NULL, '昭君怨二首 一 董思恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d982b4a-8584-4c3a-8e4d-b860d5c37949', '昭君怨二首 二', '昭君怨二首 二', 'ccecc1bb-eb6f-4fb5-be66-3bade24af40f', '唐', '["琵琶馬上彈，行路曲中難。","漢月正南遠，燕山直北寒。","髻鬟風拂亂，眉黛雪霑殘。","斟酌紅顏改，徒勞握鏡看。"]', '["琵琶马上彈，行路曲中难。","漢月正南远，燕山直北寒。","髻鬟风拂亂，眉黛雪霑殘。","斟酌紅顏改，徒勞握镜看。"]', '诗', 'shi', '', NULL, '昭君怨二首 二 董思恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1813c627-8c26-4f33-ae10-05c1e1f2d7fe', '詠日', '詠日', 'ccecc1bb-eb6f-4fb5-be66-3bade24af40f', '唐', '["滄海十枝暉，懸圃重輪慶。","蕣華發晨楹，菱彩飜朝鏡。","忽遇驚風飄，自有浮雲映。","更也人皆仰，無待揮戈正。"]', '["滄海十枝暉，懸圃重輪慶。","蕣华發晨楹，菱彩飜朝镜。","忽遇驚风飄，自有浮云映。","更也人皆仰，無待揮戈正。"]', '诗', 'shi', '', NULL, '詠日 董思恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de56b03d-02f9-4d82-b2da-166771890344', '詠月', '詠月', 'ccecc1bb-eb6f-4fb5-be66-3bade24af40f', '唐', '["北堂未安寢，西園聊騁望。","玉戶照羅幃，珠軒明綺障。","別客長安道，思婦高樓上。","所願君莫違，清風時可訪。"]', '["北堂未安寢，西园聊騁望。","玉戶照羅幃，珠軒明綺障。","別客长安道，思婦高楼上。","所願君莫違，清风时可訪。"]', '诗', 'shi', '', NULL, '詠月 董思恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a914fb3-5571-4822-b95a-e64a0d2853e9', '詠星', '詠星', 'ccecc1bb-eb6f-4fb5-be66-3bade24af40f', '唐', '["歷歷東井舍，昭昭右掖垣。","雲際龍文出，池中鳥色飜。","流輝下月路，墜影入河源。","方知潁川集，別有太丘門。"]', '["歷歷东井舍，昭昭右掖垣。","云際龙文出，池中鸟色飜。","流輝下月路，墜影入河源。","方知潁川集，別有太丘门。"]', '诗', 'shi', '', NULL, '詠星 董思恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f433cb66-864d-48c9-b8f9-55ebc3525f29', '詠風', '詠风', 'ccecc1bb-eb6f-4fb5-be66-3bade24af40f', '唐', '["蕭蕭度閶闔，習習下庭闈。","花蝶自飄舞，蘭蕙生光輝。","相烏正舉翼，退鷁已驚飛。","方從列子御，更逐浮雲歸。"]', '["蕭蕭度閶闔，習習下庭闈。","花蝶自飄舞，蘭蕙生光輝。","相烏正舉翼，退鷁已驚飞。","方從列子御，更逐浮云归。"]', '诗', 'shi', '', NULL, '詠風 董思恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0376bb0-4c4c-44c1-8519-2cae57fce8ae', '詠雲', '詠云', 'ccecc1bb-eb6f-4fb5-be66-3bade24af40f', '唐', '["帝鄉白雲起，飛蓋上天衢。","帶月綺羅映，從風枝葉敷。","參差過層閣，倏忽下蒼梧。","因風望既遠，安得久踟躕。"]', '["帝乡白云起，飞蓋上天衢。","带月綺羅映，從风枝葉敷。","參差過層閣，倏忽下蒼梧。","因风望既远，安得久踟躕。"]', '诗', 'shi', '', NULL, '詠雲 董思恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0143fea2-a4f4-4d32-a476-dec38620e82b', '詠雪', '詠雪', 'ccecc1bb-eb6f-4fb5-be66-3bade24af40f', '唐', '["天山飛雪度，言是落花朝。","惜哉不我與，蕭索從風飄。","鮮潔凌紈素，紛糅下枝條。","良時竟何在，坐見容華銷。"]', '["天山飞雪度，言是落花朝。","惜哉不我與，蕭索從风飄。","鲜潔凌紈素，紛糅下枝條。","良时竟何在，坐见容华銷。"]', '诗', 'shi', '', NULL, '詠雪 董思恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec12a9f1-97aa-4a5f-83dc-f19622ec37a4', '詠露', '詠露', 'ccecc1bb-eb6f-4fb5-be66-3bade24af40f', '唐', '["夜色凝仙掌，晨甘下帝庭。","不覺九秋至，遠向三危零。","蘆渚花初白，葵園葉尚青。","晞陽一灑惠，方願益滄溟。"]', '["夜色凝仙掌，晨甘下帝庭。","不覺九秋至，远向三危零。","蘆渚花初白，葵园葉尚青。","晞陽一灑惠，方願益滄溟。"]', '诗', 'shi', '', NULL, '詠露 董思恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a171b0d9-ffc7-4bdc-89ce-e6075754394b', '詠霧', '詠霧', 'ccecc1bb-eb6f-4fb5-be66-3bade24af40f', '唐', '["蒼山寂已暮，翠觀黯將沈。","終南晨豹隱，巫峽夜猿吟。","天寒氣不歇，景晦色方深。","待訪公超市，將予赴華陰。"]', '["蒼山寂已暮，翠观黯將沈。","終南晨豹隐，巫峽夜猿吟。","天寒氣不歇，景晦色方深。","待訪公超市，將予赴华陰。"]', '诗', 'shi', '', NULL, '詠霧 董思恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77ae50af-e0a1-44f5-9d40-b319a0549ea5', '詠虹', '詠虹', 'ccecc1bb-eb6f-4fb5-be66-3bade24af40f', '唐', '["春暮萍生早，日落雨飛餘。","橫彩分長漢，倒色媚清渠。","梁前朝影出，橋上晚光舒。","願逐旌旗轉，飄飄侍直廬。"]', '["春暮萍生早，日落雨飞餘。","橫彩分长漢，倒色媚清渠。","梁前朝影出，橋上晚光舒。","願逐旌旗轉，飄飄侍直廬。"]', '诗', 'shi', '', NULL, '詠虹 董思恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03d41a55-1682-4cb4-8635-dba61d512367', '詠桃', '詠桃', 'ccecc1bb-eb6f-4fb5-be66-3bade24af40f', '唐', '["禁苑春光麗，花蹊幾樹裝。","綴條深淺色，點露參差光。","向日分千笑，迎風共一香。","如何仙嶺側，獨秀隱遙芳。"]', '["禁苑春光丽，花蹊幾樹裝。","綴條深淺色，点露參差光。","向日分千笑，迎风共一香。","如何仙嶺側，独秀隐遙芳。"]', '诗', 'shi', '', NULL, '詠桃 董思恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b77f6dda-ffc5-496a-b66c-ed7bff6ae4a6', '詠李', '詠李', 'ccecc1bb-eb6f-4fb5-be66-3bade24af40f', '唐', '["盤根植瀛渚，交幹橫倚天。","舒華光四海，卷葉蔭山川。"]', '["盤根植瀛渚，交幹橫倚天。","舒华光四海，卷葉蔭山川。"]', '诗', 'shi', '', NULL, '詠李 董思恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90b3dcc4-2242-40a0-95d9-a426f7892037', '詠弓', '詠弓', 'ccecc1bb-eb6f-4fb5-be66-3bade24af40f', '唐', '["上弦明月半，激箭流星遠。","落雁帶書驚，啼猿映枝轉。"]', '["上弦明月半，激箭流星远。","落雁带书驚，啼猿映枝轉。"]', '诗', 'shi', '', NULL, '詠弓 董思恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b2d68dd-6800-4f46-8ab5-50c1e380082d', '詠琵琶', '詠琵琶', 'ccecc1bb-eb6f-4fb5-be66-3bade24af40f', '唐', '["半月無雙影，金花有四時。","摧藏千里態，掩抑幾重悲。","促節縈紅袖，清音滿翠帷。","駛彈風響急，緩曲釧聲遲。","空餘關隴恨，因此代相思。"]', '["半月無雙影，金花有四时。","摧藏千里態，掩抑幾重悲。","促節縈紅袖，清音满翠帷。","駛彈风响急，緩曲釧声遲。","空餘关隴恨，因此代相思。"]', '诗', 'shi', '', NULL, '詠琵琶 董思恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80a62573-63b4-45f1-a215-83d09ba61a3b', '經廬岳回望江州想洛川有作', '經廬岳回望江州想洛川有作', 'b7d79684-ad55-4892-a7b4-e62f9007b14e', '唐', '["龜山帝始營，龍門禹初鑿。","出入經變化，俯仰憑寥廓。","未若茲山功，連延竝巫霍。","東北疏艮象，西南距坤絡。","宏阜自鬱盤，高標復迴薄。","勢入柴桑渚，陰開彭蠡壑。","九江杳無際，七澤紛相錯。","雲雨散吳會，風波騰鄬鄀。","跡隨造化久，利與乾坤博。","肸蠁精氣通，紛綸潛怪作。","石渠忽見踐，金房安可託。","地入天子都，巖有仙人藥。","二門幾迢遰，三宮何儵爚。","咫尺窮杳冥，跬步皆恬漠。","仙才驚羽翰，幽居靜龍蠖。","明牧振雄詞，棣華殊灼灼。","盛業匡西夏，深謀贊禹亳。","黃雲覆鼎飛，絳氣橫川躍。","佐曆符賢運，人期茂天爵。","禮樂富垂髫，詩書成舞勺。","清輝靖嵒電，利器騰霜鍔。","遊聖挹衢尊，鄰畿恭木鐸。","巖仞包武侯，波瀾控文若。","旋聞刈薪楚，遽覩升葵藿。","稷契序揆圖，良平公輔略。","重地資出守，英藩諒求瘼。","豫章觀偉材，江州訪靈崿。","陽岫曉氛氳，陰崖暮蕭索。","潛伏屢黥奔，雄飛更鷙搏。","驚𤢹透煙霞，騰猿亂枝格。","故園有歸夢，他山飛賞樂。","帝鄉徒可遊，湟澗終旅泊。","景物觀淮海，雲霄望河洛。","城闕紫微星，圖書玄扈閣。","神功多粉繢，元氣猶斟酌。","丞相下南宮，將軍趨北落。","橫簪竝附蟬，列鼎俱調鶴。","四郊時迷路，五月先投龠。","池榭宣瓊管，風花亂珠箔。","舊遊勞夢寐，新知無悅樂。","天寒欲贈言，歲暮期交約。","夜琴清玉柱，秋灰變緹幕。","風雲動翰林，宮徵調文籥。","言泉激爲浪，思緒飛成繳。","千里輝珠璣，五采含丹雘。","鐘鼓旋驚鷃，瑾瑜俄抵鵲。","竊價慙庸怠，叨聲逾寂莫。","長望限南溟，居然翳東郭。"]', '["龟山帝始營，龙门禹初鑿。","出入經变化，俯仰憑寥廓。","未若茲山功，連延竝巫霍。","东北疏艮象，西南距坤絡。","宏阜自鬱盤，高標复迴薄。","勢入柴桑渚，陰开彭蠡壑。","九江杳無際，七澤紛相錯。","云雨散吳會，风波腾鄬鄀。","跡隨造化久，利與乾坤博。","肸蠁精氣通，紛綸潛怪作。","石渠忽见踐，金房安可託。","地入天子都，巖有仙人藥。","二门幾迢遰，三宮何儵爚。","咫尺窮杳冥，跬步皆恬漠。","仙才驚羽翰，幽居静龙蠖。","明牧振雄词，棣华殊灼灼。","盛業匡西夏，深謀贊禹亳。","黄云覆鼎飞，絳氣橫川躍。","佐曆符賢運，人期茂天爵。","禮乐富垂髫，诗书成舞勺。","清輝靖嵒電，利器腾霜鍔。","游聖挹衢尊，鄰畿恭木鐸。","巖仞包武侯，波瀾控文若。","旋闻刈薪楚，遽覩升葵藿。","稷契序揆圖，良平公輔略。","重地資出守，英藩諒求瘼。","豫章观偉材，江州訪靈崿。","陽岫晓氛氳，陰崖暮蕭索。","潛伏屢黥奔，雄飞更鷙搏。","驚𤢹透煙霞，腾猿亂枝格。","故园有归梦，他山飞賞乐。","帝乡徒可游，湟澗終旅泊。","景物观淮海，云霄望河洛。","城闕紫微星，圖书玄扈閣。","神功多粉繢，元氣猶斟酌。","丞相下南宮，將軍趨北落。","橫簪竝附蟬，列鼎俱調鹤。","四郊时迷路，五月先投龠。","池榭宣瓊管，风花亂珠箔。","旧游勞梦寐，新知無悅乐。","天寒欲贈言，歲暮期交約。","夜琴清玉柱，秋灰变緹幕。","风云动翰林，宮徵調文籥。","言泉激爲浪，思緒飞成繳。","千里輝珠璣，五采含丹雘。","鐘鼓旋驚鷃，瑾瑜俄抵鵲。","竊價慙庸怠，叨声逾寂莫。","长望限南溟，居然翳东郭。"]', '诗', 'shi', '', NULL, '經廬岳回望江州想洛川有作 劉允濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1e47e2b-1e63-44fe-a5e3-6ca0e1f4aa27', '詠琴', '詠琴', 'b7d79684-ad55-4892-a7b4-e62f9007b14e', '唐', '["昔在龍門側，誰想鳳鳴時。","雕琢今爲器，宮商不自持。","巴人緩疎節，楚客弄繁絲。","欲作高張引，飜成下調悲。"]', '["昔在龙门側，誰想鳳鳴时。","雕琢今爲器，宮商不自持。","巴人緩疎節，楚客弄繁絲。","欲作高張引，飜成下調悲。"]', '诗', 'shi', '', NULL, '詠琴 劉允濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d76fc64-ca0d-4a79-b14e-005502fcd939', '怨情', '怨情', 'b7d79684-ad55-4892-a7b4-e62f9007b14e', '唐', '["玉關芳信斷，蘭閨錦字新。","愁來好自抑，念切已含嚬。","虛牖風驚夢，空牀月厭人。","歸期倘可促，勿度柳園春。"]', '["玉关芳信斷，蘭閨錦字新。","愁来好自抑，念切已含嚬。","虛牖风驚梦，空牀月厭人。","归期倘可促，勿度柳园春。"]', '诗', 'shi', '', NULL, '怨情 劉允濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('966b0c06-1f75-4417-8f02-ae68a6f1d618', '見道邊死人', '见道邊死人', 'b7d79684-ad55-4892-a7b4-e62f9007b14e', '唐', '["淒涼徒見日，冥寞詎知年。","魂兮不可問，應爲直如弦。"]', '["淒涼徒见日，冥寞詎知年。","魂兮不可问，應爲直如弦。"]', '诗', 'shi', '', NULL, '見道邊死人 劉允濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83397093-44b2-41c1-a254-9a3490f47b6e', '九日登玄武山旅眺', '九日登玄武山旅眺', 'e00b90ee-d143-4f81-a7f3-6882f1bba887', '唐', '["九月九日望遙空，秋水秋天生夕風。","寒雁一向南去遠，遊人幾度菊花叢。"]', '["九月九日望遙空，秋水秋天生夕风。","寒雁一向南去远，游人幾度菊花叢。"]', '诗', 'shi', '', NULL, '九日登玄武山旅眺 邵大震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('455875de-13ca-4546-bc21-f048af541d2d', '軍中行路難', '軍中行路难', 'b86edfd1-925a-4ca7-9847-16b73e828afe', '唐', '["君不見封狐雄虺自成羣，憑深負固結妖氛。","玉璽分兵徵惡少，金壇授律動將軍。","將軍擁麾宣廟略，戰士橫戈靜夷落。","長驅一息背銅梁，直指三危登劒閣。","閣道岧嶢起戍樓，劒門遙裔俯靈丘。","邛關九折無平路，江水雙源有急流。","征役無期返，他鄉歲華晚。","杳杳丘陵出，蒼蒼林薄遠。","途危紫蓋峰，路澀青泥坂。","去去指哀牢，行行入不毛。","絕壁千里險，連山四望高。","中外分區宇，夷夏殊風土。","交阯枕南荒，昆彌臨北戶。","川原饒毒霧，谿谷多霪雨。","行潦四時流，崩查千歲古。","漂梗飛蓬不暫安，捫蘿引葛陟危巒。","昔時聞道從軍樂，今日方知行路難。","滄江綠水東流駛，炎州丹徼南中地。","南中南斗映星河，秦關秦塞阻煙波。","三春邊地風光少，五月瀘川瘴癘多。","朝驅疲斥候，夕息倦樵歌。","向月彎繁弱，連星轉太阿。","重義輕生懷一顧，東伐西征凡幾度。","夜夜朝朝斑鬢新，年年歲歲戎衣故。","灞城隅，滇池水。","天涯望轉積，地際行無已。","徒覺炎涼節物非，不知關山千萬里。","棄置勿重陳，重陳多苦辛。","且悅清笳梅柳曲，詎憶芳園桃李人。","絳節紅旗分日羽，丹心白刃酬明主。","但令一被君王知，誰憚三邊征戰苦。","行路難，岐路幾千端。","無復歸雲憑短翰，空餘望日想長安。"]', '["君不见封狐雄虺自成羣，憑深負固結妖氛。","玉璽分兵徵惡少，金壇授律动將軍。","將軍擁麾宣廟略，戰士橫戈静夷落。","长驱一息背銅梁，直指三危登劒閣。","閣道岧嶢起戍楼，劒门遙裔俯靈丘。","邛关九折無平路，江水雙源有急流。","征役無期返，他乡歲华晚。","杳杳丘陵出，蒼蒼林薄远。","途危紫蓋峰，路澀青泥坂。","去去指哀牢，行行入不毛。","絕壁千里險，連山四望高。","中外分區宇，夷夏殊风土。","交阯枕南荒，昆彌臨北戶。","川原饒毒霧，谿谷多霪雨。","行潦四时流，崩查千歲古。","漂梗飞蓬不暫安，捫蘿引葛陟危巒。","昔时闻道從軍乐，今日方知行路难。","滄江綠水东流駛，炎州丹徼南中地。","南中南斗映星河，秦关秦塞阻煙波。","三春邊地风光少，五月瀘川瘴癘多。","朝驱疲斥候，夕息倦樵歌。","向月彎繁弱，連星轉太阿。","重義轻生懷一顧，东伐西征凡幾度。","夜夜朝朝斑鬢新，年年歲歲戎衣故。","灞城隅，滇池水。","天涯望轉積，地際行無已。","徒覺炎涼節物非，不知关山千万里。","棄置勿重陳，重陳多苦辛。","且悅清笳梅柳曲，詎憶芳园桃李人。","絳節紅旗分日羽，丹心白刃酬明主。","但令一被君王知，誰憚三邊征戰苦。","行路难，岐路幾千端。","無复归云憑短翰，空餘望日想长安。"]', '诗', 'shi', '', NULL, '軍中行路難 辛常伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('457c68c1-8ab5-436e-a7fd-901e044ff05c', '奉和聖製夏日遊石淙山', '奉和聖製夏日游石淙山', '824609f5-419a-4fe3-ac98-159c5bc9931d', '唐', '["二室三塗光地險，均霜揆日處天中。","石泉石鏡恆留月，山鳥山花競逐風。","周王久謝瑤池賞，漢主懸慙玉樹宮。","別有祥煙伴佳氣，能隨輕輦共蔥蔥。"]', '["二室三塗光地險，均霜揆日处天中。","石泉石镜恆留月，山鸟山花競逐风。","周王久謝瑤池賞，漢主懸慙玉樹宮。","別有祥煙伴佳氣，能隨轻輦共蔥蔥。"]', '诗', 'shi', '', NULL, '奉和聖製夏日遊石淙山 姚崇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68c6f2e7-abc0-471c-9351-6d711e64f3c3', '故洛陽城侍宴應制', '故洛陽城侍宴應制', '824609f5-419a-4fe3-ac98-159c5bc9931d', '唐', '["遊豫停仙蹕，登臨對晚晴。","川鳧連倒影，巖鳥應虛聲。","野奏風成曲，山居雲作纓。","今朝丘壑上，高興小蓬瀛。"]', '["游豫停仙蹕，登臨对晚晴。","川鳧連倒影，巖鸟應虛声。","野奏风成曲，山居云作纓。","今朝丘壑上，高兴小蓬瀛。"]', '诗', 'shi', '', NULL, '故洛陽城侍宴應制 姚崇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('878d2299-db2f-4e38-bcab-f370f637bd6e', '春日洛陽城侍宴', '春日洛陽城侍宴', '824609f5-419a-4fe3-ac98-159c5bc9931d', '唐', '["南山開寶曆，北渚對芳蹊。","的歷風梅度，參差露草低。","堯樽臨上席，舜樂下前溪。","任重由來醉，乘酣志轉迷。"]', '["南山开寶曆，北渚对芳蹊。","的歷风梅度，參差露草低。","堯樽臨上席，舜乐下前溪。","任重由来醉，乘酣志轉迷。"]', '诗', 'shi', '', NULL, '春日洛陽城侍宴 姚崇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('713514a9-9744-4c9d-be03-8197ce2e2c6c', '秋夜望月', '秋夜望月', '824609f5-419a-4fe3-ac98-159c5bc9931d', '唐', '["明月有餘鑒，羈人殊未安。","桂含秋樹晚，波入夜池寒。","灼灼雲枝淨，光光草露團。","所思迷所在，長望獨長歎。"]', '["明月有餘鑒，羈人殊未安。","桂含秋樹晚，波入夜池寒。","灼灼云枝淨，光光草露團。","所思迷所在，长望独长歎。"]', '诗', 'shi', '', NULL, '秋夜望月 姚崇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7973312c-4db5-481e-9b03-41457658f413', '夜渡江', '夜渡江', '824609f5-419a-4fe3-ac98-159c5bc9931d', '唐', '["夜渚帶浮煙，蒼茫晦遠天。","舟輕不覺動，纜急始知牽。","聽草遙尋岸，聞香暗識蓮。","唯看孤帆影，常似客心懸。"]', '["夜渚带浮煙，蒼茫晦远天。","舟轻不覺动，纜急始知牽。","听草遙尋岸，闻香暗識蓮。","唯看孤帆影，常似客心懸。"]', '诗', 'shi', '', NULL, '夜渡江 姚崇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19697728-2d26-4021-bd5d-9a509addd964', '奉和聖製龍池篇', '奉和聖製龙池篇', '824609f5-419a-4fe3-ac98-159c5bc9931d', '唐', '["恭聞帝里生靈沼，應報明君鼎業新。","既協翠泉光寶命，還符白水出真人。","此時舜海潛龍躍，此地堯河帶馬巡。","獨有前池一小雁，叨承舊惠入天津。"]', '["恭闻帝里生靈沼，應報明君鼎業新。","既協翠泉光寶命，還符白水出真人。","此时舜海潛龙躍，此地堯河带马巡。","独有前池一小雁，叨承旧惠入天津。"]', '诗', 'shi', '', NULL, '奉和聖製龍池篇 姚崇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0beb441d-401f-41db-a962-37d96107e401', '句', '句', '824609f5-419a-4fe3-ac98-159c5bc9931d', '唐', '["扇掩將雛曲，釵承墮馬鬟。"]', '["扇掩將雛曲，釵承墮马鬟。"]', '诗', 'shi', '', NULL, '句 姚崇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd5e3176-7951-4a02-8f9b-67a32b879f47', '奉和御製璟與張說源乾曜同日上官命宴都堂賜詩應制', '奉和御製璟與張说源乾曜同日上官命宴都堂賜诗應制', 'efda7d12-7d8d-45d6-8156-49733f421d4a', '唐', '["丞相邦之重，非賢諒不居。","老臣慵且憊，何德以當諸。","厚秩先爲忝，崇班復此除。","太常陳禮樂，中掖降簪裾。","聖酒山河潤，仙文象緯舒。","冒恩懷寵錫，陳力省空虛。","郭隗慙無駿，馮諼媿有魚。","不知周勃者，榮幸定何如。"]', '["丞相邦之重，非賢諒不居。","老臣慵且憊，何德以當諸。","厚秩先爲忝，崇班复此除。","太常陳禮乐，中掖降簪裾。","聖酒山河潤，仙文象緯舒。","冒恩懷寵錫，陳力省空虛。","郭隗慙無駿，馮諼媿有鱼。","不知周勃者，榮幸定何如。"]', '诗', 'shi', '', NULL, '奉和御製璟與張說源乾曜同日上官命宴都堂賜詩應制 宋璟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2738f200-69ab-4c8d-a601-3db0dc2a5b83', '奉和聖製同二相已下羣官樂遊園宴', '奉和聖製同二相已下羣官乐游园宴', 'efda7d12-7d8d-45d6-8156-49733f421d4a', '唐', '["侍飲終酺會，承恩續勝遊。","戴天惟慶幸，選地即殊尤。","北向祗雙闕，南臨賞一丘。","曲江新溜暖，上苑雜花稠。","亹亹韶弦屢，戔戔賁帛周。","醉歸填畛陌，榮耀接軒裘。"]', '["侍饮終酺會，承恩續勝游。","戴天惟慶幸，選地即殊尤。","北向祗雙闕，南臨賞一丘。","曲江新溜暖，上苑杂花稠。","亹亹韶弦屢，戔戔賁帛周。","醉归填畛陌，榮耀接軒裘。"]', '诗', 'shi', '', NULL, '奉和聖製同二相已下羣官樂遊園宴 宋璟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24456bc4-6c68-403d-add5-c457d96d939e', '奉和聖製送張說巡邊', '奉和聖製送張说巡邊', 'efda7d12-7d8d-45d6-8156-49733f421d4a', '唐', '["帝道薄存兵，王師尚有征。","是關司馬法，爰命總戎行。","畫閫崇威信，分麾盛寵榮。","聚觀方結轍，出祖遂傾城。","聖酒江河潤，天詞象緯明。","德風邊草偃，勝氣朔雲平。","宰國推良器，爲軍挹壯聲。","至和常得體，不戰即亡精。","以智泉寧竭，其徐海自清。","遲還廟堂坐，贈別故人情。"]', '["帝道薄存兵，王師尚有征。","是关司马法，爰命總戎行。","畫閫崇威信，分麾盛寵榮。","聚观方結轍，出祖遂傾城。","聖酒江河潤，天词象緯明。","德风邊草偃，勝氣朔云平。","宰国推良器，爲軍挹壯声。","至和常得體，不戰即亡精。","以智泉寧竭，其徐海自清。","遲還廟堂坐，贈別故人情。"]', '诗', 'shi', '', NULL, '奉和聖製送張說巡邊 宋璟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53d0c581-0e12-44e7-9ccf-7dc0cd15ef43', '奉和聖製荅張說扈從南出雀鼠谷', '奉和聖製荅張说扈從南出雀鼠谷', 'efda7d12-7d8d-45d6-8156-49733f421d4a', '唐', '["秦地雄西夏，幷州近北胡。","禹行山啓路，舜在邑爲都。","忽視寒暄隔，深思險易殊。","四時宗伯敘，六義宰臣鋪。","徵作宮常應，星環日每紆。","盛哉逢道合，良以致亨衢。"]', '["秦地雄西夏，幷州近北胡。","禹行山啓路，舜在邑爲都。","忽視寒暄隔，深思險易殊。","四时宗伯敘，六義宰臣鋪。","徵作宮常應，星环日每紆。","盛哉逢道合，良以致亨衢。"]', '诗', 'shi', '', NULL, '奉和聖製荅張說扈從南出雀鼠谷 宋璟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff89bf17-7bc1-4cfa-9ae1-780480585dc3', '蒲津迎駕', '蒲津迎駕', 'efda7d12-7d8d-45d6-8156-49733f421d4a', '唐', '["回鑾下蒲坂，飛斾指秦京。","雒上黃雲送，關中紫氣迎。","霞朝看馬色，月曉聽雞鳴。","防拒連山險，長橋壓水平。","省方知化洽，察俗覺時清。","天下長無事，空餘襟帶名。"]', '["回鑾下蒲坂，飞斾指秦京。","雒上黄云送，关中紫氣迎。","霞朝看马色，月晓听雞鳴。","防拒連山險，长橋壓水平。","省方知化洽，察俗覺时清。","天下长無事，空餘襟带名。"]', '诗', 'shi', '', NULL, '蒲津迎駕 宋璟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8df3232-510b-4e12-9bdf-ffbb10e3842d', '送蘇尚書赴益州', '送蘇尚书赴益州', 'efda7d12-7d8d-45d6-8156-49733f421d4a', '唐', '["我望風煙接，君行霰雪飛。","園亭若有送，楊柳最依依。"]', '["我望风煙接，君行霰雪飞。","园亭若有送，楊柳最依依。"]', '诗', 'shi', '', NULL, '送蘇尚書赴益州 宋璟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('906a6a83-5bcd-4def-bb92-4de4ba2f17a4', '初春行宮侍宴應制', '初春行宮侍宴應制', '1984e783-841c-49b3-9f15-812adafd5242', '唐', '["溫液吐涓涓，跳波急應弦。","簪裾承睿賞，花柳發韶年。","聖酒千鍾洽，宸章七曜懸。","微臣從此醉，還似夢鈞天。"]', '["溫液吐涓涓，跳波急應弦。","簪裾承睿賞，花柳發韶年。","聖酒千鍾洽，宸章七曜懸。","微臣從此醉，還似梦鈞天。"]', '诗', 'shi', '', NULL, '初春行宮侍宴應制 蘇味道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba41f5b3-0724-4b6b-92ce-053736997079', '單于川對雨二首 一', '單于川对雨二首 一', '1984e783-841c-49b3-9f15-812adafd5242', '唐', '["崇朝遘行雨，薄晚屯密雲。","緣階起素沫，竟水聚圓文。","河柳低未舉，山花落已芬。","清尊久不薦，淹留遂待君。"]', '["崇朝遘行雨，薄晚屯密云。","緣階起素沫，竟水聚圓文。","河柳低未舉，山花落已芬。","清尊久不薦，淹留遂待君。"]', '诗', 'shi', '', NULL, '單于川對雨二首 一 蘇味道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ddedd95-afc8-4aea-9391-a26facab3ba1', '單于川對雨二首 二', '單于川对雨二首 二', '1984e783-841c-49b3-9f15-812adafd5242', '唐', '["飛雨欲迎旬，浮雲已送春。","還從濯枝後，來應洗兵辰。","氣合龍祠外，聲過鯨海濱。","伐邢知有屬，已見靜邊塵。"]', '["飞雨欲迎旬，浮云已送春。","還從濯枝後，来應洗兵辰。","氣合龙祠外，声過鯨海濱。","伐邢知有屬，已见静邊塵。"]', '诗', 'shi', '', NULL, '單于川對雨二首 二 蘇味道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89f42555-6e9c-4dc6-83fb-43ab4d4078d8', '正月十五夜', '正月十五夜', '1984e783-841c-49b3-9f15-812adafd5242', '唐', '["火樹銀花合，星橋鐵鎖開。","暗塵隨馬去，明月逐人來。","遊伎皆穠李，行歌盡落梅。","金吾不禁夜，玉漏莫相催。"]', '["火樹銀花合，星橋鐵鎖开。","暗塵隨马去，明月逐人来。","游伎皆穠李，行歌尽落梅。","金吾不禁夜，玉漏莫相催。"]', '诗', 'shi', '', NULL, '正月十五夜 蘇味道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88077fb4-9f1a-4297-acee-43a8384aec75', '詠霧', '詠霧', '1984e783-841c-49b3-9f15-812adafd5242', '唐', '["氤氳起洞壑，遙裔匝平疇。","乍似含龍劒，還疑映蜃樓。","拂林隨雨密，度徑帶煙浮。","方謝公超步，終從彥輔遊。"]', '["氤氳起洞壑，遙裔匝平疇。","乍似含龙劒，還疑映蜃楼。","拂林隨雨密，度徑带煙浮。","方謝公超步，終從彥輔游。"]', '诗', 'shi', '', NULL, '詠霧 蘇味道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('805134d3-3d71-496b-a4ae-08e6871461ec', '詠虹', '詠虹', '1984e783-841c-49b3-9f15-812adafd5242', '唐', '["紆餘帶星渚，窈窕架天潯。","空因壯士見，還共美人沈。","逸照含良玉，神花藻瑞金。","獨留長劒彩，終負昔賢心。"]', '["紆餘带星渚，窈窕架天潯。","空因壯士见，還共美人沈。","逸照含良玉，神花藻瑞金。","独留长劒彩，終負昔賢心。"]', '诗', 'shi', '', NULL, '詠虹 蘇味道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a73ae7a-1c7a-4cf9-9672-21f862e10993', '詠霜', '詠霜', '1984e783-841c-49b3-9f15-812adafd5242', '唐', '["金祇暮律盡，玉女暝氛歸。","孕冷隨鐘徹，飄華逐劒飛。","帶日浮寒影，乘風進晚威。","自有貞筠質，寧將庶草腓。"]', '["金祇暮律尽，玉女暝氛归。","孕冷隨鐘徹，飄华逐劒飞。","带日浮寒影，乘风進晚威。","自有貞筠質，寧將庶草腓。"]', '诗', 'shi', '', NULL, '詠霜 蘇味道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c684ee9b-bc8e-4200-95ea-99111a47a544', '詠井', '詠井', '1984e783-841c-49b3-9f15-812adafd5242', '唐', '["玲瓏映玉檻，澄澈瀉銀牀。","流聲集孔雀，帶影出羵羊。","桐落秋蛙散，桃舒春錦芳。","帝力終何有，機心庶此忘。"]', '["玲瓏映玉檻，澄澈瀉銀牀。","流声集孔雀，带影出羵羊。","桐落秋蛙散，桃舒春錦芳。","帝力終何有，機心庶此忘。"]', '诗', 'shi', '', NULL, '詠井 蘇味道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2880bfc-d719-4112-996d-1966277498af', '詠石', '詠石', '1984e783-841c-49b3-9f15-812adafd5242', '唐', '["濟北甄神貺，河西濯錦文。","聲應天池雨，影觸岱宗雲。","燕歸猶可候，羊起自成羣。","何當握靈髓，高枕絕囂氛。"]', '["濟北甄神貺，河西濯錦文。","声應天池雨，影觸岱宗云。","燕归猶可候，羊起自成羣。","何當握靈髓，高枕絕囂氛。"]', '诗', 'shi', '', NULL, '詠石 蘇味道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0588e68-3c28-4e1c-8556-9bddc9ba72e2', '奉和受圖溫洛應制', '奉和受圖溫洛應制', '1984e783-841c-49b3-9f15-812adafd5242', '唐', '["綠綺膺河檢，清壇俯洛濱。","天旋俄制蹕，孝享屬嚴禋。","陟配光三祖，懷柔洎百神。","霧開中道日，雪歛屬車塵。","預奉咸英奏，長歌億萬春。"]', '["綠綺膺河檢，清壇俯洛濱。","天旋俄制蹕，孝享屬嚴禋。","陟配光三祖，懷柔洎百神。","霧开中道日，雪歛屬车塵。","預奉咸英奏，长歌億万春。"]', '诗', 'shi', '', NULL, '奉和受圖溫洛應制 蘇味道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27f060ee-5220-495a-b43d-6f89453947f7', '使嶺南聞崔馬二御史竝拜臺郎', '使嶺南闻崔马二御史竝拜台郎', '1984e783-841c-49b3-9f15-812adafd5242', '唐', '["振鷺齊飛日，遷鶯遠聽聞。","明光共待漏，清鑒各披雲。","喜得廊廟舉，嗟爲臺閣分。","故林懷柏悅，新幄阻蘭薰。","冠去神羊影，車迎瑞雉羣。","遠從南斗外，遙仰列星文。"]', '["振鷺齊飞日，遷鶯远听闻。","明光共待漏，清鑒各披云。","喜得廊廟舉，嗟爲台閣分。","故林懷柏悅，新幄阻蘭薰。","冠去神羊影，车迎瑞雉羣。","远從南斗外，遙仰列星文。"]', '诗', 'shi', '', NULL, '使嶺南聞崔馬二御史竝拜臺郎 蘇味道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb93bbef-9711-4f55-bf3d-f382d85d88f8', '贈封御史入臺', '贈封御史入台', '1984e783-841c-49b3-9f15-812adafd5242', '唐', '["故事推三獨，茲辰對兩闈。","夕鴉共鳴舞，屈草接芳菲。","盛府持清橐，殊章動繡衣。","風連臺閣起，霜就簡書飛。","凜凜當朝色，行行滿路威。","惟當擊隼去，復覩落鵰歸。"]', '["故事推三独，茲辰对兩闈。","夕鴉共鳴舞，屈草接芳菲。","盛府持清橐，殊章动繡衣。","风連台閣起，霜就簡书飞。","凜凜當朝色，行行满路威。","惟當擊隼去，复覩落鵰归。"]', '诗', 'shi', '', NULL, '贈封御史入臺 蘇味道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9da52e35-eb50-406d-a1eb-88f45e693fc3', '始背洛城秋郊矚目奉懷臺中諸侍御', '始背洛城秋郊矚目奉懷台中諸侍御', '1984e783-841c-49b3-9f15-812adafd5242', '唐', '["薄遊忝霜署，直指戒冰心。","荔浦方南紀，蘅臯暫北臨。","山晴關塞斷，川暮廣城陰。","場圃通圭甸，溝塍礙石林。","野童來捃拾，田叟去謳吟。","蟋蟀秋風起，蒹葭晚露深。","帝城猶鬱鬱，征傳幾駸駸。","迴憶披書地，勞歌謝所欽。"]', '["薄游忝霜署，直指戒冰心。","荔浦方南紀，蘅臯暫北臨。","山晴关塞斷，川暮廣城陰。","場圃通圭甸，溝塍礙石林。","野童来捃拾，田叟去謳吟。","蟋蟀秋风起，蒹葭晚露深。","帝城猶鬱鬱，征傳幾駸駸。","迴憶披书地，勞歌謝所欽。"]', '诗', 'shi', '', NULL, '始背洛城秋郊矚目奉懷臺中諸侍御 蘇味道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42ee2e20-8a95-4add-b947-eaf2136cc75a', '九江口南濟北接蘄春南與潯陽岸', '九江口南濟北接蘄春南與潯陽岸', '1984e783-841c-49b3-9f15-812adafd5242', '唐', '["江路一悠哉，滔滔九派來。","遠潭昏似霧，前浦沸成雷。","鱗介多潛育，漁商幾泝洄。","風搖蜀柹下，日照楚萍開。","近漱湓城曲，斜吹蠡澤隈。","錫龜猶入貢，浮獸罷爲災。","津吏揮橈疾，郵童整傳催。","歸心詎可問，爲視落潮迴。"]', '["江路一悠哉，滔滔九派来。","远潭昏似霧，前浦沸成雷。","鱗介多潛育，漁商幾泝洄。","风搖蜀柹下，日照楚萍开。","近漱湓城曲，斜吹蠡澤隈。","錫龟猶入貢，浮獸罷爲災。","津吏揮橈疾，郵童整傳催。","归心詎可问，爲視落潮迴。"]', '诗', 'shi', '', NULL, '九江口南濟北接蘄春南與潯陽岸 蘇味道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('442e9d73-2d33-4a4b-992e-0b66097aada9', '和武三思於天中寺尋復禮上人之作', '和武三思於天中寺尋复禮上人之作', '1984e783-841c-49b3-9f15-812adafd5242', '唐', '["藩戚三雍暇，禪居二室隈。","忽聞從桂苑，移步踐花臺。","敏學推多藝，高談屬辯才。","是非寧滯著，空有掠嫌猜。","五行幽機暢，三蕃妙鍵開。","味同甘露灑，香似逆風來。","砌古留方石，池清辨燒灰。","人尋鶴洲返，月逐虎谿迴。","企躅瞻飛蓋，攀遊想渡杯。","願陪爲善樂，從此去塵埃。"]', '["藩戚三雍暇，禪居二室隈。","忽闻從桂苑，移步踐花台。","敏学推多藝，高談屬辯才。","是非寧滯著，空有掠嫌猜。","五行幽機暢，三蕃妙鍵开。","味同甘露灑，香似逆风来。","砌古留方石，池清辨燒灰。","人尋鹤洲返，月逐虎谿迴。","企躅瞻飞蓋，攀游想渡杯。","願陪爲善乐，從此去塵埃。"]', '诗', 'shi', '', NULL, '和武三思於天中寺尋復禮上人之作 蘇味道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bb5db63-ce70-4f82-8e40-8aad78ae0f4b', '嵩山石淙侍宴應制', '嵩山石淙侍宴應制', '1984e783-841c-49b3-9f15-812adafd5242', '唐', '["琱輿藻衞擁千官，仙洞靈谿訪九丹。","隱曖源花迷近路，參差嶺竹掃危壇。","重崖對聳霞文駮，瀑水交飛雨氣寒。","天洛宸襟有餘興，裴回周矖駐歸鑾。"]', '["琱輿藻衞擁千官，仙洞靈谿訪九丹。","隐曖源花迷近路，參差嶺竹掃危壇。","重崖对聳霞文駮，瀑水交飞雨氣寒。","天洛宸襟有餘兴，裴回周矖駐归鑾。"]', '诗', 'shi', '', NULL, '嵩山石淙侍宴應制 蘇味道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9466b4fb-2f61-4f56-af76-5fc24469b059', '古劒篇', '古劒篇', 'ea71c336-261f-4ee6-8fce-a70815aee81b', '唐', '["君不見昆吾鐵冶飛炎煙，紅光紫氣俱赫然。","良工鍛鍊凡幾年，鑄得寶劒名龍泉。","龍泉顏色如霜雪，良工咨嗟歎奇絕。","琉璃玉匣吐蓮花，錯鏤金環映明月。","正逢天下無風塵，幸得周防君子身。","精光黯黯青蛇色，文章片片綠龜鱗。","非直結交游俠子，亦曾親近英雄人。","何言中路遭棄捐，零落漂淪古獄邊。","雖復塵埋無所用，猶能夜夜氣衝天。"]', '["君不见昆吾鐵冶飞炎煙，紅光紫氣俱赫然。","良工鍛鍊凡幾年，鑄得寶劒名龙泉。","龙泉顏色如霜雪，良工咨嗟歎奇絕。","琉璃玉匣吐蓮花，錯鏤金环映明月。","正逢天下無风塵，幸得周防君子身。","精光黯黯青蛇色，文章片片綠龟鱗。","非直結交游俠子，亦曾親近英雄人。","何言中路遭棄捐，零落漂淪古獄邊。","雖复塵埋無所用，猶能夜夜氣衝天。"]', '诗', 'shi', '', NULL, '古劒篇 郭震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa7c2c85-55c8-4d54-ab13-8f3fb6251fc5', '塞上', '塞上', 'ea71c336-261f-4ee6-8fce-a70815aee81b', '唐', '["塞外虜塵飛，頻年出武威。","死生隨玉劒，辛苦向金微。","久戍人將老，長征馬不肥。","仍聞酒泉郡，已合數重圍。"]', '["塞外虜塵飞，頻年出武威。","死生隨玉劒，辛苦向金微。","久戍人將老，长征马不肥。","仍闻酒泉郡，已合數重圍。"]', '诗', 'shi', '', NULL, '塞上 郭震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('febe0eae-d6fd-4069-a337-d8dd9538c0b1', '寄劉校書', '寄劉校书', 'ea71c336-261f-4ee6-8fce-a70815aee81b', '唐', '["俗吏三年何足論，每將榮辱在朝昏。","才微易向風塵老，身賤難酬知己恩。","御苑殘鶯啼落日，黃山細雨濕歸軒。","迴首漢家丞相府，昨來誰得掃重門。"]', '["俗吏三年何足論，每將榮辱在朝昏。","才微易向风塵老，身賤难酬知己恩。","御苑殘鶯啼落日，黄山細雨濕归軒。","迴首漢家丞相府，昨来誰得掃重门。"]', '诗', 'shi', '', NULL, '寄劉校書 郭震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62f5584b-1083-4d0b-8fcd-16a80d900658', '同徐員外除太子舍人寓直之作', '同徐員外除太子舍人寓直之作', 'ea71c336-261f-4ee6-8fce-a70815aee81b', '唐', '["太子擅元良，宮臣命偉長。","除榮辭會府，直宿總書坊。","露濕幽巖桂，風吹便坐桑。","閣連雲一色，池帶月重光。","葉死蘭無氣，荷枯水不香。","遙聞秋興作，言是晉中郎。"]', '["太子擅元良，宮臣命偉长。","除榮辞會府，直宿總书坊。","露濕幽巖桂，风吹便坐桑。","閣連云一色，池带月重光。","葉死蘭無氣，荷枯水不香。","遙闻秋兴作，言是晉中郎。"]', '诗', 'shi', '', NULL, '同徐員外除太子舍人寓直之作 郭震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0ac00b2-92fa-4328-8db2-104d83d9a050', '春江曲', '春江曲', 'ea71c336-261f-4ee6-8fce-a70815aee81b', '唐', '["江水春沈沈，上有雙竹林。","竹葉壞水色，郎亦壞人心。"]', '["江水春沈沈，上有雙竹林。","竹葉壞水色，郎亦壞人心。"]', '诗', 'shi', '', NULL, '春江曲 郭震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1216559-15db-45c2-bb26-b812e75bda8d', '王昭君三首 一', '王昭君三首 一', 'ea71c336-261f-4ee6-8fce-a70815aee81b', '唐', '["自嫁單于國，長銜漢掖悲。","容顏日憔悴，有甚畫圖時。"]', '["自嫁單于国，长銜漢掖悲。","容顏日憔悴，有甚畫圖时。"]', '诗', 'shi', '', NULL, '王昭君三首 一 郭震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef9709b2-7956-4287-b3c5-666afb861638', '王昭君三首 二', '王昭君三首 二', 'ea71c336-261f-4ee6-8fce-a70815aee81b', '唐', '["厭踐冰霜域，嗟爲邊塞人。","思從漠南獵，一見漢家塵。"]', '["厭踐冰霜域，嗟爲邊塞人。","思從漠南獵，一见漢家塵。"]', '诗', 'shi', '', NULL, '王昭君三首 二 郭震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98700c77-b793-4936-8930-3c7f92e64ff6', '王昭君三首 三', '王昭君三首 三', 'ea71c336-261f-4ee6-8fce-a70815aee81b', '唐', '["聞有南河信，傳言殺畫師。","始知君念重，更肯惜蛾眉。"]', '["闻有南河信，傳言殺畫師。","始知君念重，更肯惜蛾眉。"]', '诗', 'shi', '', NULL, '王昭君三首 三 郭震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc2b73ee-d1ee-46c3-9e18-e1b686eb73b3', '子夜四時歌六首 春歌 一', '子夜四时歌六首 春歌 一', 'ea71c336-261f-4ee6-8fce-a70815aee81b', '唐', '["陌頭楊柳枝，已被春風吹。","妾心正斷絕，君懷那得知。"]', '["陌头楊柳枝，已被春风吹。","妾心正斷絕，君懷那得知。"]', '诗', 'shi', '', NULL, '子夜四時歌六首 春歌 一 郭震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc751db7-c7cb-4162-af48-426a19260707', '子夜四時歌六首 春歌 二', '子夜四时歌六首 春歌 二', 'ea71c336-261f-4ee6-8fce-a70815aee81b', '唐', '["青樓含日光，綠池起風色。","贈子同心花，殷勤此何極。"]', '["青楼含日光，綠池起风色。","贈子同心花，殷勤此何極。"]', '诗', 'shi', '', NULL, '子夜四時歌六首 春歌 二 郭震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('895e7596-5915-4c85-b423-6ac0dfe50c7a', '子夜四時歌六首 秋歌 一', '子夜四时歌六首 秋歌 一', 'ea71c336-261f-4ee6-8fce-a70815aee81b', '唐', '["邀歡空佇立，望美頻迴顧。","何時復採菱，江中密相遇。"]', '["邀歡空佇立，望美頻迴顧。","何时复採菱，江中密相遇。"]', '诗', 'shi', '', NULL, '子夜四時歌六首 秋歌 一 郭震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b60f1d3b-accb-4a4b-ad54-822b34e508c7', '子夜四時歌六首 秋歌 二', '子夜四时歌六首 秋歌 二', 'ea71c336-261f-4ee6-8fce-a70815aee81b', '唐', '["辟惡茱萸囊，延年菊花酒。","與子結綢繆，丹心此何有。"]', '["辟惡茱萸囊，延年菊花酒。","與子結綢繆，丹心此何有。"]', '诗', 'shi', '', NULL, '子夜四時歌六首 秋歌 二 郭震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51cb95ca-86e1-4685-aa0f-29e68ca46d64', '子夜四時歌六首 冬歌 一', '子夜四时歌六首 冬歌 一', 'ea71c336-261f-4ee6-8fce-a70815aee81b', '唐', '["北極嚴氣昇，南至溫風謝。","調絲競短歌，拂枕憐長夜。"]', '["北極嚴氣昇，南至溫风謝。","調絲競短歌，拂枕怜长夜。"]', '诗', 'shi', '', NULL, '子夜四時歌六首 冬歌 一 郭震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6a14d98-8edb-461f-ad57-a894630ce352', '子夜四時歌六首 冬歌 二', '子夜四时歌六首 冬歌 二', 'ea71c336-261f-4ee6-8fce-a70815aee81b', '唐', '["帷橫雙翡翠，被卷兩鴛鴦。","婉態不自得，宛轉君王牀。"]', '["帷橫雙翡翠，被卷兩鴛鴦。","婉態不自得，宛轉君王牀。"]', '诗', 'shi', '', NULL, '子夜四時歌六首 冬歌 二 郭震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcafdc4a-26a8-4dfd-88cd-26f72992eda3', '二月樂遊詩', '二月乐游诗', 'ea71c336-261f-4ee6-8fce-a70815aee81b', '唐', '["二月芳遊始，開軒望曉池。","綠蘭日吐葉，紅蘂向盈枝。","柳色行將改，君心幸莫移。","陽春遽多意，唯願兩人知。"]', '["二月芳游始，开軒望晓池。","綠蘭日吐葉，紅蘂向盈枝。","柳色行將改，君心幸莫移。","陽春遽多意，唯願兩人知。"]', '诗', 'shi', '', NULL, '二月樂遊詩 郭震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae6e1a23-7e8f-416d-be1a-f2475e1dc9ac', '十月樂遊詩', '十月乐游诗', 'ea71c336-261f-4ee6-8fce-a70815aee81b', '唐', '["十月嚴陰盛，霜氣下玉臺。","羅衣羞自解，綺帳待君開。","銀箭更籌緩，金爐香氣來。","愁仍夜未幾，已使炭成灰。"]', '["十月嚴陰盛，霜氣下玉台。","羅衣羞自解，綺帳待君开。","銀箭更籌緩，金爐香氣来。","愁仍夜未幾，已使炭成灰。"]', '诗', 'shi', '', NULL, '十月樂遊詩 郭震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8933ff79-8c52-4a93-822f-e9527aca2c0e', '螢', '螢', 'ea71c336-261f-4ee6-8fce-a70815aee81b', '唐', '["秋風凜凜月依依，飛過高梧影裏時。","暗處若教同衆類，世間爭得有人知。"]', '["秋风凜凜月依依，飞過高梧影裏时。","暗处若教同衆類，世间爭得有人知。"]', '诗', 'shi', '', NULL, '螢 郭震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1754c635-af53-4699-945e-ef1ebf8fa9de', '蛩', '蛩', 'ea71c336-261f-4ee6-8fce-a70815aee81b', '唐', '["愁殺離家未達人，一聲聲到枕前聞。","苦吟莫向朱門裏，滿耳笙歌不聽君。"]', '["愁殺離家未達人，一声声到枕前闻。","苦吟莫向朱门裏，满耳笙歌不听君。"]', '诗', 'shi', '', NULL, '蛩 郭震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc434ecd-0adc-4706-9218-de42a7f0d2d1', '雲', '云', 'ea71c336-261f-4ee6-8fce-a70815aee81b', '唐', '["聚散虛空去復還，野人閑處倚筇看。","不知身是無根物，蔽月遮星作萬端。"]', '["聚散虛空去复還，野人闲处倚筇看。","不知身是無根物，蔽月遮星作万端。"]', '诗', 'shi', '', NULL, '雲 郭震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd313e15-7845-4a24-be5f-34cd951f110a', '野井', '野井', 'ea71c336-261f-4ee6-8fce-a70815aee81b', '唐', '["縱無汲引味清澄，冷浸寒空月一輪。","鑿處若教當要路，爲君常濟往來人。"]', '["縱無汲引味清澄，冷浸寒空月一輪。","鑿处若教當要路，爲君常濟往来人。"]', '诗', 'shi', '', NULL, '野井 郭震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da206264-d011-43ba-8b09-800ce616904b', '米囊花', '米囊花', 'ea71c336-261f-4ee6-8fce-a70815aee81b', '唐', '["開花空道勝于草，結實何曾濟得民。","却笑野田禾與黍，不聞弦管過青春。"]', '["开花空道勝于草，結實何曾濟得民。","却笑野田禾與黍，不闻弦管過青春。"]', '诗', 'shi', '', NULL, '米囊花 郭震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38b96fe2-4196-4a9d-9b80-2862e38376fd', '惜花', '惜花', 'ea71c336-261f-4ee6-8fce-a70815aee81b', '唐', '["豔拂衣襟蘂拂杯，遶枝閑共蝶徘徊。","春風滿目還惆悵，半欲離披半未開。"]', '["豔拂衣襟蘂拂杯，遶枝闲共蝶徘徊。","春风满目還惆悵，半欲離披半未开。"]', '诗', 'shi', '', NULL, '惜花 郭震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31bf5ad5-1a86-4866-9c6d-fc7a4aeee90b', '蓮花', '蓮花', 'ea71c336-261f-4ee6-8fce-a70815aee81b', '唐', '["臉膩香薰似有情，世間何物比輕盈。","湘妃雨後來池看，碧玉盤中弄水晶。"]', '["臉膩香薰似有情，世间何物比轻盈。","湘妃雨後来池看，碧玉盤中弄水晶。"]', '诗', 'shi', '', NULL, '蓮花 郭震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cda42a70-1158-4d7e-a1de-b7580ff210cb', '弘農清巖曲有磐石可坐宋十一每拂拭待余寄詩贈之', '弘農清巖曲有磐石可坐宋十一每拂拭待余寄诗贈之', 'a5bb83e6-e64c-4339-b4ff-e2e6cf833521', '唐', '["信彼稱靈石，居然狎遁棲。","裴回承翠巘，斌駁帶深谿。","夕陰起層岫，清景半虹霓。","風來應嘯阮，波動可琴嵇。","僕也潁陽客，望彼空思齊。","儻見山人至，簪嵩且杖藜。"]', '["信彼稱靈石，居然狎遁棲。","裴回承翠巘，斌駁带深谿。","夕陰起層岫，清景半虹霓。","风来應嘯阮，波动可琴嵇。","僕也潁陽客，望彼空思齊。","儻见山人至，簪嵩且杖藜。"]', '诗', 'shi', '', NULL, '弘農清巖曲有磐石可坐宋十一每拂拭待余寄詩贈之 田遊巖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1459fba3-9168-4084-a1b4-07a2f567f1d1', '和宋之問下山歌', '和宋之问下山歌', 'efabfbd9-153d-4b78-9136-a6a5d4f9d9e9', '唐', '["日云暮兮下嵩山，路連綿兮樹石間。","出谷口兮見明月，心裴回兮不能還。"]', '["日云暮兮下嵩山，路連綿兮樹石间。","出谷口兮见明月，心裴回兮不能還。"]', '诗', 'shi', '', NULL, '和宋之問下山歌 王無競 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e82528ac-67d2-4f16-b739-e93558f132b1', '北使長城', '北使长城', 'efabfbd9-153d-4b78-9136-a6a5d4f9d9e9', '唐', '["秦世築長城，長城無極已。","暴兵四十萬，興工九千里。","死人如亂麻，白骨相撐委。","殫弊未云悟，窮毒豈知止。","胡塵未北滅，楚兵遽東起。","六國復囂囂，兩龍鬬觺觺。","卯金竟握讖，反璧俄淪祀。","仁義寢邦國，狙暴行終始。","一旦咸陽宮，翻爲漢朝市。"]', '["秦世築长城，长城無極已。","暴兵四十万，兴工九千里。","死人如亂麻，白骨相撐委。","殫弊未云悟，窮毒豈知止。","胡塵未北滅，楚兵遽东起。","六国复囂囂，兩龙鬬觺觺。","卯金竟握讖，反璧俄淪祀。","仁義寢邦国，狙暴行終始。","一旦咸陽宮，翻爲漢朝市。"]', '诗', 'shi', '', NULL, '北使長城 王無競 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e4b1b0b-32ba-4b99-b3dd-8a20ae5bba4a', '鳳臺曲', '鳳台曲', 'efabfbd9-153d-4b78-9136-a6a5d4f9d9e9', '唐', '["鳳臺何逶迤，嬴女管參差。","一旦綵雲至，身去無還期。","遺曲此臺上，世人多學吹。","一吹一落淚，至今憐玉姿。"]', '["鳳台何逶迤，嬴女管參差。","一旦綵云至，身去無還期。","遺曲此台上，世人多学吹。","一吹一落泪，至今怜玉姿。"]', '诗', 'shi', '', NULL, '鳳臺曲 王無競 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dfa0900-dc39-41fb-ae4b-b63e01c508f8', '銅雀臺', '銅雀台', 'efabfbd9-153d-4b78-9136-a6a5d4f9d9e9', '唐', '["北登銅雀上，西望青松郭。","繐帳空蒼蒼，陵田紛漠漠。","平生事已變，歌吹宛猶昨。","長袖拂玉塵，遺情結羅幕。","妾怨在朝露，君恩豈中薄。","高臺奏曲終，曲終淚橫落。"]', '["北登銅雀上，西望青松郭。","繐帳空蒼蒼，陵田紛漠漠。","平生事已变，歌吹宛猶昨。","长袖拂玉塵，遺情結羅幕。","妾怨在朝露，君恩豈中薄。","高台奏曲終，曲終泪橫落。"]', '诗', 'shi', '', NULL, '銅雀臺 王無競 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df09ddaf-1bf8-4f8e-bd67-c0d38476507b', '巫山', '巫山', 'efabfbd9-153d-4b78-9136-a6a5d4f9d9e9', '唐', '["神女向高唐，巫山下夕陽。","裴回行作雨，婉孌逐荆王。","電影江前落，雷聲峽外長。","朝雲無處所，臺館曉蒼蒼。"]', '["神女向高唐，巫山下夕陽。","裴回行作雨，婉孌逐荆王。","電影江前落，雷声峽外长。","朝云無处所，台館晓蒼蒼。"]', '诗', 'shi', '', NULL, '巫山 王無競 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55c39448-211c-4209-882a-36e2cad7751b', '和宋之問下山歌', '和宋之问下山歌', 'c0242ea8-7b56-403e-8a5c-03f8da1ddade', '唐', '["良遊晼晚兮月呈光，錦路逶迤兮山路長。","王孫不留兮歲將晏，嵩巖仙草兮爲誰芳。"]', '["良游晼晚兮月呈光，錦路逶迤兮山路长。","王孫不留兮歲將晏，嵩巖仙草兮爲誰芳。"]', '诗', 'shi', '', NULL, '和宋之問下山歌 賈曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd0a6452-0a5d-49bb-9e3c-640a2a7132f5', '孝和皇帝輓歌', '孝和皇帝輓歌', 'c0242ea8-7b56-403e-8a5c-03f8da1ddade', '唐', '["新命千齡啓，鴻圖累聖餘。","天行應潛躍，帝出受圖書。","禮若傳堯舊，功疑復夏初。","夢遊長不返，何國是華胥。"]', '["新命千齡啓，鴻圖累聖餘。","天行應潛躍，帝出受圖书。","禮若傳堯旧，功疑复夏初。","梦游长不返，何国是华胥。"]', '诗', 'shi', '', NULL, '孝和皇帝輓歌 賈曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c96c6d5-d2f9-469c-8d65-2aec39d01950', '奉和春日出苑矚目應令', '奉和春日出苑矚目應令', 'c0242ea8-7b56-403e-8a5c-03f8da1ddade', '唐', '["銅龍曉闢問安迴，金輅春遊博望開。","渭北晴光搖草樹，終南佳氣入樓臺。","招賢已得商山老，託乘還徵鄴下才。","臣在東周獨留滯，忻逢睿藻日邊來。"]', '["銅龙晓闢问安迴，金輅春游博望开。","渭北晴光搖草樹，終南佳氣入楼台。","招賢已得商山老，託乘還徵鄴下才。","臣在东周独留滯，忻逢睿藻日邊来。"]', '诗', 'shi', '', NULL, '奉和春日出苑矚目應令 賈曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b77b1f0-92f2-45d4-bf1a-4816d576267f', '有所思', '有所思', 'c0242ea8-7b56-403e-8a5c-03f8da1ddade', '唐', '["洛陽城東桃李花，飛來飛去落誰家。","幽閨女兒愛顏色，坐見落花長歎息。","今歲花開君不待，明年花開復誰在。","故人不共洛陽東，今來空對落花風。","年年歲歲花相似，歲歲年年人不同。"]', '["洛陽城东桃李花，飞来飞去落誰家。","幽閨女兒愛顏色，坐见落花长歎息。","今歲花开君不待，明年花开复誰在。","故人不共洛陽东，今来空对落花风。","年年歲歲花相似，歲歲年年人不同。"]', '诗', 'shi', '', NULL, '有所思 賈曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c29f4de-276f-4e7e-8fd7-3bb81d7080d6', '祭汾陰樂章', '祭汾陰乐章', 'c0242ea8-7b56-403e-8a5c-03f8da1ddade', '唐', '["蠲我漸饎，潔我膋薌。","有豆孔碩，爲羞既臧。","至城無昧，精意惟芳。","神其醉止，欣欣樂康。"]', '["蠲我漸饎，潔我膋薌。","有豆孔碩，爲羞既臧。","至城無昧，精意惟芳。","神其醉止，欣欣乐康。"]', '诗', 'shi', '', NULL, '祭汾陰樂章 賈曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1501641f-3a17-4e35-9acd-9e5740050a4d', '使至汴州喜逢宋之問', '使至汴州喜逢宋之问', 'e2337781-818d-4a12-bb35-abed74dc8113', '唐', '["阮籍蓬池上，孤韻竹林才。","巨源從吏道，正擁使車來。","相逢且交臂，相命且銜杯。","醉後長歌畢，餘聲繞吹臺。"]', '["阮籍蓬池上，孤韻竹林才。","巨源從吏道，正擁使车来。","相逢且交臂，相命且銜杯。","醉後长歌畢，餘声繞吹台。"]', '诗', 'shi', '', NULL, '使至汴州喜逢宋之問 李夔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bddec91-2cbe-45b3-b738-7b43bf87bab3', '祭汾陰樂章', '祭汾陰乐章', '8c252403-53fe-49c3-9a7e-8648fffebe31', '唐', '["聿修嚴配，展事禋宗。","祥符寶鼎，禮備黃琮。","祝詞以信，明德惟聰。","介茲景福，永永無窮。"]', '["聿修嚴配，展事禋宗。","祥符寶鼎，禮備黄琮。","祝词以信，明德惟聰。","介茲景福，永永無窮。"]', '诗', 'shi', '', NULL, '祭汾陰樂章 崔玄童 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f3f7164-942a-470b-a3cc-70190f28690a', '祭汾陰樂章', '祭汾陰乐章', '3638eca4-3c1c-4fb9-956a-4cc6d090ba08', '唐', '["樂奏云闋，禮章載虔。","禋宗於地，昭假於天。","惟馨薦矣，既醉歆焉。","神之降福，永永萬年。"]', '["乐奏云闋，禮章載虔。","禋宗於地，昭假於天。","惟馨薦矣，既醉歆焉。","神之降福，永永万年。"]', '诗', 'shi', '', NULL, '祭汾陰樂章 何鸞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c1650df-0cab-4f13-afe9-d73e5a13d861', '祭汾陰樂章', '祭汾陰乐章', '7db52c03-4a80-45fa-b9a7-b36297fc15d9', '唐', '["維歲之吉，維辰之良。","聖君紱冕，肅事壇場。","大禮已備，大樂斯張。","神其醉止，降福無疆。"]', '["維歲之吉，維辰之良。","聖君紱冕，肅事壇場。","大禮已備，大乐斯張。","神其醉止，降福無疆。"]', '诗', 'shi', '', NULL, '祭汾陰樂章 蔣挺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f83489d-3526-48c8-a5d6-ccff7c3ba9d7', '關山月', '关山月', 'fee52be3-9dbf-49b0-811a-7fa71985b765', '唐', '["月生西海上，氣逐邊風壯。","萬里度關山，蒼茫非一狀。","漢兵開郡國，胡馬窺亭障。","夜夜聞悲笳，征人起南望。"]', '["月生西海上，氣逐邊风壯。","万里度关山，蒼茫非一狀。","漢兵开郡国，胡马窺亭障。","夜夜闻悲笳，征人起南望。"]', '诗', 'shi', '', NULL, '關山月 崔融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5af9518c-089e-4d8d-8c52-51ae24c86142', '擬古', '擬古', 'fee52be3-9dbf-49b0-811a-7fa71985b765', '唐', '["飲馬臨濁河，濁河深不測。","河水日東注，河源乃西極。","思君正如此，誰爲生羽翼。","日夕大川陰，雲霞千里色。","所思在河處，宛在機中織。","離夢當有魂，愁容定無力。","夙齡負奇志，中夜三歎息。","拔劒斬長榆，彎弓射小棘。","班張固非擬，衞霍行可即。","寄謝閨中人，努力加飱食。"]', '["饮马臨濁河，濁河深不測。","河水日东注，河源乃西極。","思君正如此，誰爲生羽翼。","日夕大川陰，云霞千里色。","所思在河处，宛在機中织。","離梦當有魂，愁容定無力。","夙齡負奇志，中夜三歎息。","拔劒斬长榆，彎弓射小棘。","班張固非擬，衞霍行可即。","寄謝閨中人，努力加飱食。"]', '诗', 'shi', '', NULL, '擬古 崔融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7feb657-3ea9-410f-acca-c4d2b008bed3', '西征軍行遇風', '西征軍行遇风', 'fee52be3-9dbf-49b0-811a-7fa71985b765', '唐', '["北風卷塵沙，左右不相識。","颯颯吹萬里，昏昏同一色。","馬煩莫敢進，人急未遑食。","曹木春更悲，天景晝相匿。","夙齡慕忠義，雅尚存孤直。","覽史懷浸驕，讀詩歎孔棘。","及茲戎旅地，忝從書記職。","兵氣騰北荒，軍聲振西極。","坐覺威靈遠，行看氛祲息。","愚臣何以報，倚馬申微力。"]', '["北风卷塵沙，左右不相識。","颯颯吹万里，昏昏同一色。","马煩莫敢進，人急未遑食。","曹木春更悲，天景晝相匿。","夙齡慕忠義，雅尚存孤直。","覽史懷浸驕，读诗歎孔棘。","及茲戎旅地，忝從书記職。","兵氣腾北荒，軍声振西極。","坐覺威靈远，行看氛祲息。","愚臣何以報，倚马申微力。"]', '诗', 'shi', '', NULL, '西征軍行遇風 崔融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eea4adec-a57e-4303-963e-6d22a86a93f6', '塞垣行', '塞垣行', 'fee52be3-9dbf-49b0-811a-7fa71985b765', '唐', '["疾風捲溟海，萬里揚沙礫。","仰望不見天，昏昏竟朝夕。","是時軍兩進，東拒復西敵。","蔽山張旗鼓，間道潛鋒鏑。","精騎突曉圍，奇兵襲暗壁。","十月邊塞寒，四山沍陰積。","雨雪鴈南飛，風塵景西迫。","昔我事討論，未嘗怠經籍。","一朝棄筆硯，十年操矛戟。","豈要黃河誓，須勒燕山石。","可嗟牧羊臣，海外久爲客。"]', '["疾风捲溟海，万里揚沙礫。","仰望不见天，昏昏竟朝夕。","是时軍兩進，东拒复西敵。","蔽山張旗鼓，间道潛鋒鏑。","精騎突晓圍，奇兵襲暗壁。","十月邊塞寒，四山沍陰積。","雨雪鴈南飞，风塵景西迫。","昔我事討論，未嘗怠經籍。","一朝棄笔硯，十年操矛戟。","豈要黄河誓，須勒燕山石。","可嗟牧羊臣，海外久爲客。"]', '诗', 'shi', '', NULL, '塞垣行 崔融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d1a1b29-8a18-4332-bfd0-34be746bbbac', '登東陽沈隱侯八詠樓', '登东陽沈隐侯八詠楼', 'fee52be3-9dbf-49b0-811a-7fa71985b765', '唐', '["旦登西北樓，樓峻石墉厚。","宛生長定□，俯壓三江口。","排階銜鳥衡，交疏過牛斗。","左右會稽鎮，出入具區藪。","越巖森其前，浙江漫其後。","此地實東陽，由來山水鄉。","隱侯有遺詠，落簡尚餘芳。","具物昔未改，斯人今已亡。","粵余忝藩左，束髪事文場。","悵不見夫子，神期遙相望。"]', '["旦登西北楼，楼峻石墉厚。","宛生长定□，俯壓三江口。","排階銜鸟衡，交疏過牛斗。","左右會稽鎮，出入具區藪。","越巖森其前，浙江漫其後。","此地實东陽，由来山水乡。","隐侯有遺詠，落簡尚餘芳。","具物昔未改，斯人今已亡。","粵余忝藩左，束髪事文場。","悵不见夫子，神期遙相望。"]', '诗', 'shi', '', NULL, '登東陽沈隱侯八詠樓 崔融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c09f0472-304b-4e70-8577-6746b47945c4', '從軍行', '從軍行', 'fee52be3-9dbf-49b0-811a-7fa71985b765', '唐', '["穹廬雜種亂金方，武將神兵下玉堂。","天子旌旗過細柳，匈奴運數盡枯楊。","關頭落月橫西嶺，塞下凝雲斷北荒。","漠漠邊塵飛衆鳥，昏昏朔氣聚羣羊。","依稀蜀杖迷新竹，髣髴胡牀識故桑。","臨海舊來聞驃騎，尋河本自有中郎。","坐看戰壁爲平土，近待軍營作破羌。"]', '["穹廬杂種亂金方，武將神兵下玉堂。","天子旌旗過細柳，匈奴運數尽枯楊。","关头落月橫西嶺，塞下凝云斷北荒。","漠漠邊塵飞衆鸟，昏昏朔氣聚羣羊。","依稀蜀杖迷新竹，髣髴胡牀識故桑。","臨海旧来闻驃騎，尋河本自有中郎。","坐看戰壁爲平土，近待軍營作破羌。"]', '诗', 'shi', '', NULL, '從軍行 崔融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62a22393-b9b9-498a-9991-91d5bb0ffee4', '和宋之問寒食題黃梅臨江驛', '和宋之问寒食題黄梅臨江驛', 'fee52be3-9dbf-49b0-811a-7fa71985b765', '唐', '["春分自淮北，寒食渡江南。","忽見潯陽水，疑是宋家潭。","明主閽難呌，孤臣逐未堪。","遙思故園陌，桃李正酣酣。"]', '["春分自淮北，寒食渡江南。","忽见潯陽水，疑是宋家潭。","明主閽难呌，孤臣逐未堪。","遙思故园陌，桃李正酣酣。"]', '诗', 'shi', '', NULL, '和宋之問寒食題黃梅臨江驛 崔融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18d34365-d89f-49e2-8aca-7e9a4e355677', '留別杜審言幷呈洛中舊遊', '留別杜審言幷呈洛中旧游', 'fee52be3-9dbf-49b0-811a-7fa71985b765', '唐', '["斑鬢今爲別，紅顏昨共遊。","年年春不待，處處酒相留。","駐馬西橋上，回車南陌頭。","故人從此隔，風月坐悠悠。"]', '["斑鬢今爲別，紅顏昨共游。","年年春不待，处处酒相留。","駐马西橋上，回车南陌头。","故人從此隔，风月坐悠悠。"]', '诗', 'shi', '', NULL, '留別杜審言幷呈洛中舊遊 崔融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7b620aa-a172-4bcf-8c03-0328c1113cbc', '詠寶劒', '詠寶劒', 'fee52be3-9dbf-49b0-811a-7fa71985b765', '唐', '["寶劒出昆吾，龜龍夾采珠。","五精初獻術，千戶競淪都。","匣氣衝牛斗，山形轉轆轤。","欲知天下貴，持此問風胡。"]', '["寶劒出昆吾，龟龙夾采珠。","五精初獻術，千戶競淪都。","匣氣衝牛斗，山形轉轆轤。","欲知天下貴，持此问风胡。"]', '诗', 'shi', '', NULL, '詠寶劒 崔融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a53d834c-14a4-4ddf-8cfb-3f6e6d8a1b60', '吳中好風景', '吳中好风景', 'fee52be3-9dbf-49b0-811a-7fa71985b765', '唐', '["洛渚問吳潮，吳門想洛橋。","夕煙楊柳岸，春水木蘭橈。","城邑高樓近，星辰北斗遙。","無因生羽翼，輕舉託還飆。"]', '["洛渚问吳潮，吳门想洛橋。","夕煙楊柳岸，春水木蘭橈。","城邑高楼近，星辰北斗遙。","無因生羽翼，轻舉託還飆。"]', '诗', 'shi', '', NULL, '吳中好風景 崔融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6439a49-592a-40ad-a73e-801dc711eadf', '則天皇后挽歌二首 一', '則天皇后挽歌二首 一', 'fee52be3-9dbf-49b0-811a-7fa71985b765', '唐', '["宵陳虛禁夜，夕臨空山陰。","日月昏尺景，天地慘何心。","紫殿金鋪澀，黃陵玉座深。","鏡匳長不啓，聖主淚霑巾。"]', '["宵陳虛禁夜，夕臨空山陰。","日月昏尺景，天地慘何心。","紫殿金鋪澀，黄陵玉座深。","镜匳长不啓，聖主泪霑巾。"]', '诗', 'shi', '', NULL, '則天皇后挽歌二首 一 崔融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b4abac6-1205-4d47-98b2-609597527b97', '則天皇后挽歌二首 二', '則天皇后挽歌二首 二', 'fee52be3-9dbf-49b0-811a-7fa71985b765', '唐', '["前殿臨朝罷，長陵合葬歸。","山川不可望，文物盡成非。","陰月霾中道，軒星落太微。","空餘天子孝，松上景雲飛。"]', '["前殿臨朝罷，长陵合葬归。","山川不可望，文物尽成非。","陰月霾中道，軒星落太微。","空餘天子孝，松上景云飞。"]', '诗', 'shi', '', NULL, '則天皇后挽歌二首 二 崔融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f39f0489-ddeb-447c-9c64-8f36596c1bea', '戶部尚書崔公挽歌', '戶部尚书崔公挽歌', 'fee52be3-9dbf-49b0-811a-7fa71985b765', '唐', '["八座圖書委，三臺章奏盈。","舉杯常有勸，曳履忽無聲。","市若荆州罷，池如薛縣平。","空餘濟南劒，天子署高名。"]', '["八座圖书委，三台章奏盈。","舉杯常有勸，曳履忽無声。","市若荆州罷，池如薛縣平。","空餘濟南劒，天子署高名。"]', '诗', 'shi', '', NULL, '戶部尚書崔公挽歌 崔融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b81758d0-66aa-4f12-ae5e-d1b5ffb6d355', '韋長史挽詞', '韋长史挽词', 'fee52be3-9dbf-49b0-811a-7fa71985b765', '唐', '["日落桑榆下，寒生松柏中。","冥冥多苦霧，切切有悲風。","京兆新阡闢，扶陽甲第空。","郭門從此去，荆棘漸蒙籠。"]', '["日落桑榆下，寒生松柏中。","冥冥多苦霧，切切有悲风。","京兆新阡闢，扶陽甲第空。","郭门從此去，荆棘漸蒙籠。"]', '诗', 'shi', '', NULL, '韋長史挽詞 崔融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08fa9396-b756-4bf1-830d-908b91be67ac', '和梁王衆傳張光祿是王子晉後身', '和梁王衆傳張光祿是王子晉後身', 'fee52be3-9dbf-49b0-811a-7fa71985b765', '唐', '["聞有沖天客，披雲下帝畿。","三年上賓去，千載忽來歸。","昔偶浮丘伯，今同丁令威。","中郎才貌是，柱史姓名非。","祗召趨龍闕，承恩拜虎闈。","丹成金鼎獻，酒至玉杯揮。","天仗分旄節，朝容間羽衣。","舊壇何處所，新廟坐光輝。","漢主存仙要，淮南愛道機。","朝朝緱氏鶴，長向洛城飛。"]', '["闻有沖天客，披云下帝畿。","三年上賓去，千載忽来归。","昔偶浮丘伯，今同丁令威。","中郎才貌是，柱史姓名非。","祗召趨龙闕，承恩拜虎闈。","丹成金鼎獻，酒至玉杯揮。","天仗分旄節，朝容间羽衣。","旧壇何处所，新廟坐光輝。","漢主存仙要，淮南愛道機。","朝朝緱氏鹤，长向洛城飞。"]', '诗', 'shi', '', NULL, '和梁王衆傳張光祿是王子晉後身 崔融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee1cd0c3-f7ad-4ac8-a80f-21a4a14e2cf7', '哭蔣詹事儼', '哭蔣詹事儼', 'fee52be3-9dbf-49b0-811a-7fa71985b765', '唐', '["江上有長離，從容盛羽儀。","一鳴百獸舞，一舉羣鳥隨。","應我聖明代，巢君阿閣垂。","鉤陳侍帷扆，環衞奉旌麾。","雅量滄海納，完才廟廊施。","養親光孝道，事主竭忠規。","貞節既已固，殊榮良不訾。","朝遊雲漢省，夕宴芙蓉池。","汲黯言當直，陳平智本奇。","功成喜身退，時往惜年馳。","鎮國山基毀，中天柱石頹。","將軍空有頌，刺史獨留碑。","蕪漫藏書壁，荒涼懸劒枝。","昔余參下位，數載忝牽羈。","置榻恩逾重，迎門禮自卑。","竹林常接興，黍谷每逢吹。","逸翰金相發，清談玉柄揮。","不輕文舉少，深歎子雲疲。","遺愛猶如在，殘編尚可窺。","即今流水曲，何處俗人知。"]', '["江上有长離，從容盛羽儀。","一鳴百獸舞，一舉羣鸟隨。","應我聖明代，巢君阿閣垂。","鉤陳侍帷扆，环衞奉旌麾。","雅量滄海納，完才廟廊施。","養親光孝道，事主竭忠規。","貞節既已固，殊榮良不訾。","朝游云漢省，夕宴芙蓉池。","汲黯言當直，陳平智本奇。","功成喜身退，时往惜年驰。","鎮国山基毀，中天柱石頹。","將軍空有頌，刺史独留碑。","蕪漫藏书壁，荒涼懸劒枝。","昔余參下位，數載忝牽羈。","置榻恩逾重，迎门禮自卑。","竹林常接兴，黍谷每逢吹。","逸翰金相發，清談玉柄揮。","不轻文舉少，深歎子云疲。","遺愛猶如在，殘編尚可窺。","即今流水曲，何处俗人知。"]', '诗', 'shi', '', NULL, '哭蔣詹事儼 崔融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34447457-a278-449e-9750-5f2a39eef734', '嵩山石淙侍宴應制', '嵩山石淙侍宴應制', 'fee52be3-9dbf-49b0-811a-7fa71985b765', '唐', '["洞口仙巖類削成，泉香石冷晝含清。","龍旗畫月中天下，鳳管披雲此地迎。","樹作帷屏陽景翳，芝如宮闕夏涼生。","今朝出豫臨懸圃，明日陪遊向赤城。"]', '["洞口仙巖類削成，泉香石冷晝含清。","龙旗畫月中天下，鳳管披云此地迎。","樹作帷屏陽景翳，芝如宮闕夏涼生。","今朝出豫臨懸圃，明日陪游向赤城。"]', '诗', 'shi', '', NULL, '嵩山石淙侍宴應制 崔融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f5818c2-5310-4d08-8f21-7c8a3abefae3', '塞上寄內', '塞上寄內', 'fee52be3-9dbf-49b0-811a-7fa71985b765', '唐', '["旅魂驚塞北，歸望斷河西。","春風若可寄，暫爲遶蘭閨。"]', '["旅魂驚塞北，归望斷河西。","春风若可寄，暫爲遶蘭閨。"]', '诗', 'shi', '', NULL, '塞上寄內 崔融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64f7fdb5-a18e-483d-abdb-1aa4be47ffc3', '侍從途中口號應制', '侍從途中口號應制', '279468d4-48db-402e-9185-d8eb7a150748', '唐', '["疵賤出山東，忠貞任土風。","因敷河朔藻，得奉洛陽宮。","一顧侍御史，再顧給事中。","常願粉肌骨，特荅造化功。"]', '["疵賤出山东，忠貞任土风。","因敷河朔藻，得奉洛陽宮。","一顧侍御史，再顧給事中。","常願粉肌骨，特荅造化功。"]', '诗', 'shi', '', NULL, '侍從途中口號應制 閻朝隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59fee0f6-4c9e-4f8a-b203-2e96f11f3ad6', '奉和聖製夏日遊石淙山', '奉和聖製夏日游石淙山', '279468d4-48db-402e-9185-d8eb7a150748', '唐', '["金臺隱隱陵黃道，玉輦亭亭下絳雰。","千種岡巒千種樹，一重巖壑一重雲。","花落風吹紅的歷，藤垂日晃綠葐蒀。","五百里內賢人聚，願陪閶闔侍天文。"]', '["金台隐隐陵黄道，玉輦亭亭下絳雰。","千種岡巒千種樹，一重巖壑一重云。","花落风吹紅的歷，藤垂日晃綠葐蒀。","五百里內賢人聚，願陪閶闔侍天文。"]', '诗', 'shi', '', NULL, '奉和聖製夏日遊石淙山 閻朝隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34751bd9-cc56-4d97-b75a-ff8665fd9b27', '鸚鵡貓兒篇', '鸚鵡貓兒篇', '279468d4-48db-402e-9185-d8eb7a150748', '唐', '["霹靂引，豐隆鳴，猛獸噫氣蛇吼聲。","鸚鵡鳥，同資造化兮殊粹精。","鷫鸘毛，翡翠翼。","鵷雛延頸，鵾雞弄色。","鸚鵡鳥，同稟陰陽兮異埏埴。","彼何爲兮，隱隱振振。","此何爲兮，綠衣翠襟。","彼何爲兮，窘窘蠢蠢。","此何爲兮，好貌好音。","彷彷兮徉徉，似妖姬躧步兮動羅裳。","趨趨兮蹌蹌，若處子迴眸兮登玉堂。","爰有獸也，安其忍，觜其脇，距其胸，與之放曠浪浪兮，從從容容。","鉤爪鋸牙也，宵行晝伏無以當，遇之兮忘味。","摶擊騰擲也，朝飛暮噪無以拒，逢之兮屏氣。","由是言之，貪殘薄則智慧作，貪殘臨之兮不復攫。","由是言之，智慧周則貪殘囚，智慧犯之兮不復憂。","菲形陋質雖賤微，皇王顧遇長光輝。","離宮別館臨朝市，妙舞繁弦雜宮徵。","嘉喜堂前景福內，合歡殿上明光裏。","雲母屏風文彩合，流蘇斗帳香煙起。","承恩宴盼接宴喜，高視七頭金駱駝。","平懷五尺銅獅子，國有君兮國有臣。","君爲主兮臣爲賓，朝有賢兮朝有德。","賢爲君兮德爲飾，千年萬歲兮心轉憶。"]', '["霹靂引，豐隆鳴，猛獸噫氣蛇吼声。","鸚鵡鸟，同資造化兮殊粹精。","鷫鸘毛，翡翠翼。","鵷雛延頸，鵾雞弄色。","鸚鵡鸟，同稟陰陽兮異埏埴。","彼何爲兮，隐隐振振。","此何爲兮，綠衣翠襟。","彼何爲兮，窘窘蠢蠢。","此何爲兮，好貌好音。","彷彷兮徉徉，似妖姬躧步兮动羅裳。","趨趨兮蹌蹌，若处子迴眸兮登玉堂。","爰有獸也，安其忍，觜其脇，距其胸，與之放曠浪浪兮，從從容容。","鉤爪鋸牙也，宵行晝伏無以當，遇之兮忘味。","摶擊腾擲也，朝飞暮噪無以拒，逢之兮屏氣。","由是言之，貪殘薄則智慧作，貪殘臨之兮不复攫。","由是言之，智慧周則貪殘囚，智慧犯之兮不复憂。","菲形陋質雖賤微，皇王顧遇长光輝。","離宮別館臨朝市，妙舞繁弦杂宮徵。","嘉喜堂前景福內，合歡殿上明光裏。","云母屏风文彩合，流蘇斗帳香煙起。","承恩宴盼接宴喜，高視七头金駱駝。","平懷五尺銅獅子，国有君兮国有臣。","君爲主兮臣爲賓，朝有賢兮朝有德。","賢爲君兮德爲飾，千年万歲兮心轉憶。"]', '诗', 'shi', '', NULL, '鸚鵡貓兒篇 閻朝隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2d1e4b8-f91b-49d4-bbac-883e06e18231', '三日曲水侍宴應制', '三日曲水侍宴應制', '279468d4-48db-402e-9185-d8eb7a150748', '唐', '["三月重三日，千春續萬春。","聖澤如東海，天文似北辰。","荷葉珠盤淨，蓮花寶蓋新。","陛下制萬國，臣作水心人。"]', '["三月重三日，千春續万春。","聖澤如东海，天文似北辰。","荷葉珠盤淨，蓮花寶蓋新。","陛下制万国，臣作水心人。"]', '诗', 'shi', '', NULL, '三日曲水侍宴應制 閻朝隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6e8562f-4559-4764-88d2-571bf6c453f9', '奉和九日幸臨渭亭登高應制得筵字', '奉和九日幸臨渭亭登高應制得筵字', '279468d4-48db-402e-9185-d8eb7a150748', '唐', '["九九侍神仙，高高坐半天。","文章二曜動，氣色五星連。","簪紱趨皇極，笙歌接御筵。","願因茱菊酒，相守百千年。"]', '["九九侍神仙，高高坐半天。","文章二曜动，氣色五星連。","簪紱趨皇極，笙歌接御筵。","願因茱菊酒，相守百千年。"]', '诗', 'shi', '', NULL, '奉和九日幸臨渭亭登高應制得筵字 閻朝隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b82ee19-dea7-49e8-abf0-e112106ca294', '奉和送金城公主適西蕃應制', '奉和送金城公主適西蕃應制', '279468d4-48db-402e-9185-d8eb7a150748', '唐', '["甥舅重親地，君臣厚義鄉。","還將貴公主，嫁與耨檀王。","鹵簿山河暗，琵琶道路長。","迴瞻父母國，日出在東方。"]', '["甥舅重親地，君臣厚義乡。","還將貴公主，嫁與耨檀王。","鹵簿山河暗，琵琶道路长。","迴瞻父母国，日出在东方。"]', '诗', 'shi', '', NULL, '奉和送金城公主適西蕃應制 閻朝隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33d16f6f-9b4c-44bf-aa91-a4bbdb69cc8d', '奉和立春遊苑迎春應制', '奉和立春游苑迎春應制', '279468d4-48db-402e-9185-d8eb7a150748', '唐', '["管籥周移寰極裏，乘輿望幸斗城闉。","草根未結青絲縷，蘿蔦猶垂綠帔巾。","鵲入巢中言改歲，燕銜書上道宜新。","願得長繩繫取日，光臨天子萬年春。"]', '["管籥周移寰極裏，乘輿望幸斗城闉。","草根未結青絲縷，蘿蔦猶垂綠帔巾。","鵲入巢中言改歲，燕銜书上道宜新。","願得长繩繫取日，光臨天子万年春。"]', '诗', 'shi', '', NULL, '奉和立春遊苑迎春應制 閻朝隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bc76614-4316-4956-9a0b-a2e7445e0c25', '奉和聖製春日幸望春宮應制', '奉和聖製春日幸望春宮應制', '279468d4-48db-402e-9185-d8eb7a150748', '唐', '["句芒人面乘兩龍，道是春神衞九重。","綵勝年年逢七日，酴醿歲歲滿千鍾。","宮梅間雪祥光遍，城柳含煙淑氣濃。","醉倒君前情未盡，願因歌舞自爲容。"]', '["句芒人面乘兩龙，道是春神衞九重。","綵勝年年逢七日，酴醿歲歲满千鍾。","宮梅间雪祥光遍，城柳含煙淑氣濃。","醉倒君前情未尽，願因歌舞自爲容。"]', '诗', 'shi', '', NULL, '奉和聖製春日幸望春宮應制 閻朝隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbcb4558-8691-4316-8578-bba8e041f621', '夜宴安樂公主新宅', '夜宴安乐公主新宅', '279468d4-48db-402e-9185-d8eb7a150748', '唐', '["鳳皇鳴舞樂昌年，蠟炬開花夜管弦。","半醉徐擊珊瑚樹，已聞鐘漏曉聲傳。"]', '["鳳皇鳴舞乐昌年，蠟炬开花夜管弦。","半醉徐擊珊瑚樹，已闻鐘漏晓声傳。"]', '诗', 'shi', '', NULL, '夜宴安樂公主新宅 閻朝隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87479a4e-45d9-46e9-8c31-3486c317f7c5', '餞唐永昌', '餞唐永昌', '279468d4-48db-402e-9185-d8eb7a150748', '唐', '["洛陽難理若棼絲，椎破連環定不疑。","鸚鵡休言秦地樂，回頭一顧一相思。"]', '["洛陽难理若棼絲，椎破連环定不疑。","鸚鵡休言秦地乐，回头一顧一相思。"]', '诗', 'shi', '', NULL, '餞唐永昌 閻朝隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6ed618a-fbeb-4f43-ae2d-833c60f477ba', '明月歌', '明月歌', '279468d4-48db-402e-9185-d8eb7a150748', '唐', '["梅花雪白柳葉黃，雲霧四起月蒼蒼，箭水泠泠刻漏長。","揮玉指，拂羅裳，爲君一奏楚明光。"]', '["梅花雪白柳葉黄，云霧四起月蒼蒼，箭水泠泠刻漏长。","揮玉指，拂羅裳，爲君一奏楚明光。"]', '诗', 'shi', '', NULL, '明月歌 閻朝隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d386c8a-aab5-4ed2-a19d-63db3efdbf91', '采蓮女', '采蓮女', '279468d4-48db-402e-9185-d8eb7a150748', '唐', '["采蓮女，采蓮舟，春日春江碧水流。","蓮衣承玉釧，蓮刺罥銀鉤。","薄暮斂容歌一曲，氛氳香氣滿汀洲。"]', '["采蓮女，采蓮舟，春日春江碧水流。","蓮衣承玉釧，蓮刺罥銀鉤。","薄暮斂容歌一曲，氛氳香氣满汀洲。"]', '诗', 'shi', '', NULL, '采蓮女 閻朝隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('668a791f-5475-447f-a473-aff1a64754c1', '奉和登驪山應制', '奉和登驪山應制', '279468d4-48db-402e-9185-d8eb7a150748', '唐', '["龍行踏絳氣，天半語相聞。","混沌疑初判，洪荒若始分。"]', '["龙行踏絳氣，天半語相闻。","混沌疑初判，洪荒若始分。"]', '诗', 'shi', '', NULL, '奉和登驪山應制 閻朝隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cbef4ae-209c-4d7a-8e59-034ae5638d29', '奉和九日幸臨渭亭登高應制得月字', '奉和九日幸臨渭亭登高應制得月字', '61028b68-b3eb-4974-9272-fad7b49945e8', '唐', '["雲物開千里，天行乘九月。","絲言丹鳳池，斾轉蒼龍闕。","灞水歡娛地，秦京游俠窟。","欣承解慍詞，聖酒黃花發。"]', '["云物开千里，天行乘九月。","絲言丹鳳池，斾轉蒼龙闕。","灞水歡娛地，秦京游俠窟。","欣承解慍词，聖酒黄花發。"]', '诗', 'shi', '', NULL, '奉和九日幸臨渭亭登高應制得月字 韋元旦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('784c6515-baff-443f-a581-6d66079a0806', '奉和送金城公主適西蕃應制', '奉和送金城公主適西蕃應制', '61028b68-b3eb-4974-9272-fad7b49945e8', '唐', '["柔遠安夷俗，和親重漢年。","軍容旌節送，國命錦車傳。","琴曲悲千里，簫聲戀九天。","唯應西海月，來就掌珠圓。"]', '["柔远安夷俗，和親重漢年。","軍容旌節送，国命錦车傳。","琴曲悲千里，簫声戀九天。","唯應西海月，来就掌珠圓。"]', '诗', 'shi', '', NULL, '奉和送金城公主適西蕃應制 韋元旦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f50656c8-2f41-4214-8faa-3509c92bf247', '餞唐州高使君赴任', '餞唐州高使君赴任', '61028b68-b3eb-4974-9272-fad7b49945e8', '唐', '["桐栢膺新命，芝蘭惜舊遊。","鳴臯夜鶴在，遷木早鶯求。","傳擁淮源路，尊空灞水流。","落花紛送遠，春色引離憂。"]', '["桐栢膺新命，芝蘭惜旧游。","鳴臯夜鹤在，遷木早鶯求。","傳擁淮源路，尊空灞水流。","落花紛送远，春色引離憂。"]', '诗', 'shi', '', NULL, '餞唐州高使君赴任 韋元旦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('891830f3-a5e9-491c-9c52-08f3a518341d', '早朝', '早朝', '61028b68-b3eb-4974-9272-fad7b49945e8', '唐', '["震維芳月季，宸極衆星尊。","珮玉朝三陛，鳴珂度九門。","挈壺分早漏，伏檻耀初暾。","北倚蒼龍闕，西臨紫鳳垣。","詞庭草欲奏，溫室樹無言。","鱗翰空爲忝，長懷聖主恩。"]', '["震維芳月季，宸極衆星尊。","珮玉朝三陛，鳴珂度九门。","挈壺分早漏，伏檻耀初暾。","北倚蒼龙闕，西臨紫鳳垣。","词庭草欲奏，溫室樹無言。","鱗翰空爲忝，长懷聖主恩。"]', '诗', 'shi', '', NULL, '早朝 韋元旦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('978693d7-b514-4066-91b5-b0cbcc7612af', '奉和立春游苑迎春應制', '奉和立春游苑迎春應制', '61028b68-b3eb-4974-9272-fad7b49945e8', '唐', '["灞涘長安恆近日，殷正臘月早迎新。","池魚戲葉仍含凍，宮女裁花已作春。","向苑雲疑承翠幄，入林風若起青蘋。","年年斗柄東無限，願挹瓊觴壽北辰。"]', '["灞涘长安恆近日，殷正臘月早迎新。","池鱼戲葉仍含凍，宮女裁花已作春。","向苑云疑承翠幄，入林风若起青蘋。","年年斗柄东無限，願挹瓊觴壽北辰。"]', '诗', 'shi', '', NULL, '奉和立春游苑迎春應制 韋元旦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d432e111-a6f1-4c17-8de9-242301dbc227', '奉和聖製春日幸望春宮應制', '奉和聖製春日幸望春宮應制', '61028b68-b3eb-4974-9272-fad7b49945e8', '唐', '["九重樓閣半山霞，四望韶陽春未賒。","侍蹕妍歌臨灞涘，留觴豔舞出京華。","危竿競捧中街日，戲馬爭銜上苑花。","景色歡娛長若此，承恩不醉不還家。"]', '["九重楼閣半山霞，四望韶陽春未賒。","侍蹕妍歌臨灞涘，留觴豔舞出京华。","危竿競捧中街日，戲马爭銜上苑花。","景色歡娛长若此，承恩不醉不還家。"]', '诗', 'shi', '', NULL, '奉和聖製春日幸望春宮應制 韋元旦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c658ad41-604f-4712-a4fb-28fc60eb82b8', '奉和人日宴大明宮恩賜綵縷人勝應制', '奉和人日宴大明宮恩賜綵縷人勝應制', '61028b68-b3eb-4974-9272-fad7b49945e8', '唐', '["鸞鳳旌旗拂曉陳，魚龍角觝大明辰。","青韶既肇人爲日，綺勝初成日作人。","聖藻凌雲裁栢賦，仙歌促宴摘梅春。","垂旒一慶宜年酒，朝野俱歡薦壽新。"]', '["鸾鳳旌旗拂晓陳，鱼龙角觝大明辰。","青韶既肇人爲日，綺勝初成日作人。","聖藻凌云裁栢賦，仙歌促宴摘梅春。","垂旒一慶宜年酒，朝野俱歡薦壽新。"]', '诗', 'shi', '', NULL, '奉和人日宴大明宮恩賜綵縷人勝應制 韋元旦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aeb87a16-962c-4c1f-9f0e-6d0d3297c8d6', '奉和幸安樂公主山莊應制', '奉和幸安乐公主山莊應制', '61028b68-b3eb-4974-9272-fad7b49945e8', '唐', '["銀河南渚帝城隅，帝輦平明出九衢。","刻鳳蟠螭凌桂邸，穿池疊石寫蓬壺。","瓊簫暫下鈞天樂，綺綴長懸明月珠。","仙牓承恩爭既醉，方知朝野更歡娛。"]', '["銀河南渚帝城隅，帝輦平明出九衢。","刻鳳蟠螭凌桂邸，穿池叠石寫蓬壺。","瓊簫暫下鈞天乐，綺綴长懸明月珠。","仙牓承恩爭既醉，方知朝野更歡娛。"]', '诗', 'shi', '', NULL, '奉和幸安樂公主山莊應制 韋元旦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5053867b-e73f-4928-a7d5-634b4b5b3fcd', '興慶池侍宴應制', '兴慶池侍宴應制', '61028b68-b3eb-4974-9272-fad7b49945e8', '唐', '["滄池漭沆帝城邊，殊勝昆明鑿漢年。","夾岸旌旗疏輦道，中流簫鼓振樓船。","雲峰四起迎宸幄，水樹千重入御筵。","宴樂已深魚藻詠，承恩更欲奏甘泉。"]', '["滄池漭沆帝城邊，殊勝昆明鑿漢年。","夾岸旌旗疏輦道，中流簫鼓振楼船。","云峰四起迎宸幄，水樹千重入御筵。","宴乐已深鱼藻詠，承恩更欲奏甘泉。"]', '诗', 'shi', '', NULL, '興慶池侍宴應制 韋元旦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('835e1487-e59d-485b-b54d-9ca42734b145', '夜宴安樂公主宅', '夜宴安乐公主宅', '61028b68-b3eb-4974-9272-fad7b49945e8', '唐', '["主第新成銀作牓，賓筵廣宴玉爲樓。","壺觴既卜仙人夜，歌舞宜停織女秋。"]', '["主第新成銀作牓，賓筵廣宴玉爲楼。","壺觴既卜仙人夜，歌舞宜停织女秋。"]', '诗', 'shi', '', NULL, '夜宴安樂公主宅 韋元旦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21d11f74-3e97-4d16-be94-e8cc6aca8e96', '奉和初春幸太平公主南莊應制', '奉和初春幸太平公主南莊應制', '1cf6bbeb-0f5e-481a-aff8-60b3770cd4c4', '唐', '["沁園佳麗奪蓬瀛，翠壁紅泉繞上京。","二聖忽從鸞殿幸，雙仙正下鳳樓迎。","花含步輦空間出，樹雜帷宮畫裏行。","無路乘槎窺漢渚，徒知訪卜就君平。"]', '["沁园佳丽奪蓬瀛，翠壁紅泉繞上京。","二聖忽從鸾殿幸，雙仙正下鳳楼迎。","花含步輦空间出，樹杂帷宮畫裏行。","無路乘槎窺漢渚，徒知訪卜就君平。"]', '诗', 'shi', '', NULL, '奉和初春幸太平公主南莊應制 邵昇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d3017ee-fdf9-4f87-a1ab-4f4fac7a974d', '奉和送金城公主適西蕃應制', '奉和送金城公主適西蕃應制', 'ad788326-2b51-4abe-a959-f0ffcffdadd7', '唐', '["皇恩睠下人，割愛遠和親。","少女風遊兌，姮娥月去秦。","龍笛迎金榜，驪歌送錦輪。","那堪桃李色，移向虜庭春。"]', '["皇恩睠下人，割愛远和親。","少女风游兌，姮娥月去秦。","龙笛迎金榜，驪歌送錦輪。","那堪桃李色，移向虜庭春。"]', '诗', 'shi', '', NULL, '奉和送金城公主適西蕃應制 唐遠悊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de546d8c-ba1d-4031-b5ab-41576897784a', '汾陰后土祠作', '汾陰后土祠作', '4127d5c0-8b35-4ecf-b88f-dfafc0073f02', '唐', '["昔予讀舊史，遍覩漢世君。","武皇實稽古，建茲百代勳。","號令垂懋典，舊經備闕文。","西巡歷九嶷，舳艫被江濱。","勒兵十八萬，旌旗何紛紛。","朅來茂陵下，英聲不復聞。","我行歲方晏，極望山河分。","神光終冥漠，鼎氣獨氛氳。","攬涕步脽上，登高見彼汾。","雄圖今安在，飛飛有白雲。"]', '["昔予读旧史，遍覩漢世君。","武皇實稽古，建茲百代勳。","號令垂懋典，旧經備闕文。","西巡歷九嶷，舳艫被江濱。","勒兵十八万，旌旗何紛紛。","朅来茂陵下，英声不复闻。","我行歲方晏，極望山河分。","神光終冥漠，鼎氣独氛氳。","攬涕步脽上，登高见彼汾。","雄圖今安在，飞飞有白云。"]', '诗', 'shi', '', NULL, '汾陰后土祠作 李適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07adc881-4b12-47dc-8691-e616f4c60032', '荅宋十一崖口五渡見贈', '荅宋十一崖口五渡见贈', '4127d5c0-8b35-4ecf-b88f-dfafc0073f02', '唐', '["聞君訪遠山，躋險造幽絕。","眇然青雲境，觀奇彌年月。","登嶺亦泝溪，孤舟事沿越。","崿嶂傳彩翠，崖磴互欹缺。","石林上攢藂，金澗下明滅。","捫壁窺丹井，梯苔瞰乳穴。","忽枉巖中贈，對翫未嘗輟。","殷勤獨往事，委曲鍊藥說。","邀余名山期，從爾泛海澨。","歲晏秉宿心，斯言非徒設。"]', '["闻君訪远山，躋險造幽絕。","眇然青云境，观奇彌年月。","登嶺亦泝溪，孤舟事沿越。","崿嶂傳彩翠，崖磴互欹缺。","石林上攢藂，金澗下明滅。","捫壁窺丹井，梯苔瞰乳穴。","忽枉巖中贈，对翫未嘗輟。","殷勤独往事，委曲鍊藥说。","邀余名山期，從爾泛海澨。","歲晏秉宿心，斯言非徒設。"]', '诗', 'shi', '', NULL, '荅宋十一崖口五渡見贈 李適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5008f289-7310-407e-bad2-2cec0283392f', '餞許州宋司馬赴任', '餞許州宋司马赴任', '4127d5c0-8b35-4ecf-b88f-dfafc0073f02', '唐', '["昔吾遊箕山，朅來涉潁水。","復有許由廟，迢迢白雲裏。","聞君佐繁昌，臨風悵懷此。","儻到平輿泉，寄謝干將里。"]', '["昔吾游箕山，朅来涉潁水。","复有許由廟，迢迢白云裏。","闻君佐繁昌，臨风悵懷此。","儻到平輿泉，寄謝干將里。"]', '诗', 'shi', '', NULL, '餞許州宋司馬赴任 李適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6d104a2-b07d-49a0-9847-6100af4512fe', '奉和聖製九日侍宴應制得高字', '奉和聖製九日侍宴應制得高字', '4127d5c0-8b35-4ecf-b88f-dfafc0073f02', '唐', '["禁苑秋光入，宸遊霽色高。","萸房頒綵笥，菊蘂薦香醪。","後騎縈堤柳，前旌拂御桃。","王枚俱得從，淺淺愧飛毫。"]', '["禁苑秋光入，宸游霽色高。","萸房頒綵笥，菊蘂薦香醪。","後騎縈堤柳，前旌拂御桃。","王枚俱得從，淺淺愧飞毫。"]', '诗', 'shi', '', NULL, '奉和聖製九日侍宴應制得高字 李適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ae06ef1-da07-432f-9b40-1ff8f6b9f566', '遊禁苑幸臨渭亭遇雪應制', '游禁苑幸臨渭亭遇雪應制', '4127d5c0-8b35-4ecf-b88f-dfafc0073f02', '唐', '["長樂喜春歸，披香瑞雪霏。","花從銀閤度，絮繞玉窗飛。","寫曜銜天藻，呈祥拂御衣。","上林紛可望，無處不光輝。"]', '["长乐喜春归，披香瑞雪霏。","花從銀閤度，絮繞玉窗飞。","寫曜銜天藻，呈祥拂御衣。","上林紛可望，無处不光輝。"]', '诗', 'shi', '', NULL, '遊禁苑幸臨渭亭遇雪應制 李適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff987161-b81b-4493-97c0-7e9ad0c9840c', '奉和九日登慈恩寺浮圖應制', '奉和九日登慈恩寺浮圖應制', '4127d5c0-8b35-4ecf-b88f-dfafc0073f02', '唐', '["鳳輦乘朝霽，鸚林對晚秋。","天文貝葉寫，聖澤菊花浮。","塔似神功造，龕疑佛影留。","幸陪清漢蹕，欣奉淨居遊。"]', '["鳳輦乘朝霽，鸚林对晚秋。","天文貝葉寫，聖澤菊花浮。","塔似神功造，龕疑佛影留。","幸陪清漢蹕，欣奉淨居游。"]', '诗', 'shi', '', NULL, '奉和九日登慈恩寺浮圖應制 李適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de1f9a15-20cd-466f-a15e-87f0396b7851', '侍宴長寧公主東莊應制', '侍宴长寧公主东莊應制', '4127d5c0-8b35-4ecf-b88f-dfafc0073f02', '唐', '["鳳樓紆睿幸，龍舸暢宸襟。","歌舞平陽第，園亭沁水林。","山花添聖酒，澗竹繞熏琴。","願奉瑤池駕，千春侍德音。"]', '["鳳楼紆睿幸，龙舸暢宸襟。","歌舞平陽第，园亭沁水林。","山花添聖酒，澗竹繞熏琴。","願奉瑤池駕，千春侍德音。"]', '诗', 'shi', '', NULL, '侍宴長寧公主東莊應制 李適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1cb3949-a366-4e57-985d-126ae6481be4', '奉和送金城公主適西蕃應制', '奉和送金城公主適西蕃應制', '4127d5c0-8b35-4ecf-b88f-dfafc0073f02', '唐', '["絳河從遠聘，青海赴和親。","月作臨邊曉，花爲度隴春。","主歌悲顧鶴，帝策重安人。","獨有瓊簫去，悠悠思錦輪。"]', '["絳河從远聘，青海赴和親。","月作臨邊晓，花爲度隴春。","主歌悲顧鹤，帝策重安人。","独有瓊簫去，悠悠思錦輪。"]', '诗', 'shi', '', NULL, '奉和送金城公主適西蕃應制 李適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b8aaaf0-3c10-4ef6-ba8b-f7d711da9b77', '安樂公主移入新宅', '安乐公主移入新宅', '4127d5c0-8b35-4ecf-b88f-dfafc0073f02', '唐', '["星橋他日創，仙榜此時開。","馬向鋪錢埒，簫聞奏玉臺。","人疑衞叔美，客似長卿才。","借問遊天使，誰能取石回。"]', '["星橋他日創，仙榜此时开。","马向鋪錢埒，簫闻奏玉台。","人疑衞叔美，客似长卿才。","借问游天使，誰能取石回。"]', '诗', 'shi', '', NULL, '安樂公主移入新宅 李適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('001434fc-eb06-43dc-8601-4953e6878524', '奉和幸望春宮送朔方軍大總管張仁亶', '奉和幸望春宮送朔方軍大總管張仁亶', '4127d5c0-8b35-4ecf-b88f-dfafc0073f02', '唐', '["地限驕南牧，天臨餞北征。","解衣延寵命，橫劒總威名。","豹略恭宸旨，雄文動睿情。","坐觀膜拜入，朝夕受降城。"]', '["地限驕南牧，天臨餞北征。","解衣延寵命，橫劒總威名。","豹略恭宸旨，雄文动睿情。","坐观膜拜入，朝夕受降城。"]', '诗', 'shi', '', NULL, '奉和幸望春宮送朔方軍大總管張仁亶 李適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1a9e168-42cd-4a42-a36f-c03de3f9908d', '人日宴大明宮恩賜綵縷人勝應制', '人日宴大明宮恩賜綵縷人勝應制', '4127d5c0-8b35-4ecf-b88f-dfafc0073f02', '唐', '["朱城待鳳韶年至，碧殿疏龍淑氣來。","寶帳金屏人已帖，圖花學鳥勝初裁。","林香近接宜春苑，山翠遙添獻壽杯。","向夕憑高風景麗，天文垂耀象昭回。"]', '["朱城待鳳韶年至，碧殿疏龙淑氣来。","寶帳金屏人已帖，圖花学鸟勝初裁。","林香近接宜春苑，山翠遙添獻壽杯。","向夕憑高风景丽，天文垂耀象昭回。"]', '诗', 'shi', '', NULL, '人日宴大明宮恩賜綵縷人勝應制 李適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39f6ac48-3ca6-4c44-93ea-a75594aacabb', '奉和春日幸望春宮應制', '奉和春日幸望春宮應制', '4127d5c0-8b35-4ecf-b88f-dfafc0073f02', '唐', '["玉輦金輿天上來，花園四望錦屏開。","輕絲半拂朱門柳，細纈全披畫閣梅。","舞蝶飛行飄御席，[歌鶯]度曲繞仙杯。","聖詞今日光輝滿，漢主秋風莫道才。"]', '["玉輦金輿天上来，花园四望錦屏开。","轻絲半拂朱门柳，細纈全披畫閣梅。","舞蝶飞行飄御席，[歌鶯]度曲繞仙杯。","聖词今日光輝满，漢主秋风莫道才。"]', '诗', 'shi', '', NULL, '奉和春日幸望春宮應制 李適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cae8ba8d-7886-4ec7-80b7-27004ef35090', '奉和立春遊苑迎春', '奉和立春游苑迎春', '4127d5c0-8b35-4ecf-b88f-dfafc0073f02', '唐', '["金輿翠輦迎嘉節，御苑仙宮待獻春。","淑氣初銜梅色淺，條風半拂柳墻新。","天杯慶壽齊南岳，聖藻光輝動北辰。","稍覺披香歌吹近，龍驂日暮下城闉。"]', '["金輿翠輦迎嘉節，御苑仙宮待獻春。","淑氣初銜梅色淺，條风半拂柳墻新。","天杯慶壽齊南岳，聖藻光輝动北辰。","稍覺披香歌吹近，龙驂日暮下城闉。"]', '诗', 'shi', '', NULL, '奉和立春遊苑迎春 李適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd4561b5-250a-4b37-953e-d03fca470562', '帝幸興慶池戲競渡應制', '帝幸兴慶池戲競渡應制', '4127d5c0-8b35-4ecf-b88f-dfafc0073f02', '唐', '["拂露金輿丹斾轉，凌晨黼帳碧池開。","南山倒影從雲落，北澗搖光寫溜迴。","急槳爭標排荇度，輕帆截浦觸荷來。","橫汾宴鎬歡無極，歌舞年年聖壽杯。"]', '["拂露金輿丹斾轉，凌晨黼帳碧池开。","南山倒影從云落，北澗搖光寫溜迴。","急槳爭標排荇度，轻帆截浦觸荷来。","橫汾宴鎬歡無極，歌舞年年聖壽杯。"]', '诗', 'shi', '', NULL, '帝幸興慶池戲競渡應制 李適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('695b62ab-eed4-4b1f-bb00-dc67a9e4f926', '侍宴安樂公主莊應制', '侍宴安乐公主莊應制', '4127d5c0-8b35-4ecf-b88f-dfafc0073f02', '唐', '["平陽金牓鳳皇樓，沁水銀河鸚鵡洲。","綵仗遙臨丹壑裏，仙輿暫幸綠亭幽。","前池錦石蓮花豔，後嶺香鑪桂蘂秋。","貴主稱觴萬年壽，還輕漢武濟汾遊。"]', '["平陽金牓鳳皇楼，沁水銀河鸚鵡洲。","綵仗遙臨丹壑裏，仙輿暫幸綠亭幽。","前池錦石蓮花豔，後嶺香鑪桂蘂秋。","貴主稱觴万年壽，還轻漢武濟汾游。"]', '诗', 'shi', '', NULL, '侍宴安樂公主莊應制 李適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae2260e3-9cd6-4217-9d3d-37580661dcce', '侍宴安樂公主新宅應制', '侍宴安乐公主新宅應制', '4127d5c0-8b35-4ecf-b88f-dfafc0073f02', '唐', '["銀河半倚鳳皇臺，玉酒相傳鸚鵡杯。","若見君平須借問，仙槎一去幾時來。"]', '["銀河半倚鳳皇台，玉酒相傳鸚鵡杯。","若见君平須借问，仙槎一去幾时来。"]', '诗', 'shi', '', NULL, '侍宴安樂公主新宅應制 李適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e38d0d4-b41c-45b7-8841-55a1a9bf93ec', '餞唐永昌赴任東都', '餞唐永昌赴任东都', '4127d5c0-8b35-4ecf-b88f-dfafc0073f02', '唐', '["聞道飛鳧向洛陽，翩翩矯翮度文昌。","因聲寄意三花樹，少室巖前幾過香。"]', '["闻道飞鳧向洛陽，翩翩矯翮度文昌。","因声寄意三花樹，少室巖前幾過香。"]', '诗', 'shi', '', NULL, '餞唐永昌赴任東都 李適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68f2c09a-2e19-49c7-907a-87c7ba5c9abe', '奉和聖製立春日侍宴內殿出剪綵花應制', '奉和聖製立春日侍宴內殿出剪綵花應制', '5b300b57-f5e8-470e-a5fb-166618c1fd98', '唐', '["上林宮館好，春光獨早知。","剪花疑始發，刻燕似新窺。","色濃輕雪點，香淺嫩風吹。","此日叨陪侍，恩榮得數枝。"]', '["上林宮館好，春光独早知。","剪花疑始發，刻燕似新窺。","色濃轻雪点，香淺嫩风吹。","此日叨陪侍，恩榮得數枝。"]', '诗', 'shi', '', NULL, '奉和聖製立春日侍宴內殿出剪綵花應制 劉憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f81757da-050e-4ff8-a9ea-18043f1e1bd0', '奉和人日清暉閣宴羣臣遇雪應制', '奉和人日清暉閣宴羣臣遇雪應制', '5b300b57-f5e8-470e-a5fb-166618c1fd98', '唐', '["輿輦乘人日，登臨上鳳京。","風尋歌曲颺，雪向舞行縈。","千官隨興合，萬福與時幷。","承恩長若此，微賤幸昇平。"]', '["輿輦乘人日，登臨上鳳京。","风尋歌曲颺，雪向舞行縈。","千官隨兴合，万福與时幷。","承恩长若此，微賤幸昇平。"]', '诗', 'shi', '', NULL, '奉和人日清暉閣宴羣臣遇雪應制 劉憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('257201c7-12c4-41e6-8008-1bc6e99a1ed2', '奉和七夕宴兩儀殿應制', '奉和七夕宴兩儀殿應制', '5b300b57-f5e8-470e-a5fb-166618c1fd98', '唐', '["秋吹過雙闕，星仙動二靈。","更深移月鏡，河淺度雲軿。","殿上呼方朔，人間失武丁。","天文茲夜裏，光映紫微庭。"]', '["秋吹過雙闕，星仙动二靈。","更深移月镜，河淺度云軿。","殿上呼方朔，人间失武丁。","天文茲夜裏，光映紫微庭。"]', '诗', 'shi', '', NULL, '奉和七夕宴兩儀殿應制 劉憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('516de5d1-b0ab-4c6d-b52e-f702d9a38b24', '奉和九月九日聖製登慈恩寺浮圖應制', '奉和九月九日聖製登慈恩寺浮圖應制', '5b300b57-f5e8-470e-a5fb-166618c1fd98', '唐', '["飛塔雲霄半，清晨羽斾遊。","登臨憑季月，寥廓見中州。","御酒新寒退，天文瑞景留。","辟邪將獻壽，茲日奉千秋。"]', '["飞塔云霄半，清晨羽斾游。","登臨憑季月，寥廓见中州。","御酒新寒退，天文瑞景留。","辟邪將獻壽，茲日奉千秋。"]', '诗', 'shi', '', NULL, '奉和九月九日聖製登慈恩寺浮圖應制 劉憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2726cb71-88f7-4749-81b3-c36693076c23', '閏九月九日幸總持寺登浮圖應制', '閏九月九日幸總持寺登浮圖應制', '5b300b57-f5e8-470e-a5fb-166618c1fd98', '唐', '["重陽登閏序，上界叶時巡。","駐輦天花落，開筵妓樂陳。","城端剎柱見，雲表露盤新。","臨睨光輝滿，飛文動睿神。"]', '["重陽登閏序，上界叶时巡。","駐輦天花落，开筵妓乐陳。","城端剎柱见，云表露盤新。","臨睨光輝满，飞文动睿神。"]', '诗', 'shi', '', NULL, '閏九月九日幸總持寺登浮圖應制 劉憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23564ed4-148c-42e0-b15d-ffc93e05f10f', '侍宴長寧公主東莊', '侍宴长寧公主东莊', '5b300b57-f5e8-470e-a5fb-166618c1fd98', '唐', '["公主林亭地，清晨降玉輿。","畫橋飛渡水，仙閣涌臨虛。","晴新看蛺蝶，夏早摘芙蕖。","文酒娛遊盛，忻叨侍從餘。"]', '["公主林亭地，清晨降玉輿。","畫橋飞渡水，仙閣涌臨虛。","晴新看蛺蝶，夏早摘芙蕖。","文酒娛游盛，忻叨侍從餘。"]', '诗', 'shi', '', NULL, '侍宴長寧公主東莊 劉憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca0d3a07-42ca-4052-a773-24014c95811b', '奉和送金城公主入西蕃應制', '奉和送金城公主入西蕃應制', '5b300b57-f5e8-470e-a5fb-166618c1fd98', '唐', '["外館踰河右，行營指路岐。","和親悲遠嫁，忍愛泣將離。","旌斾羗風引，軒車漢月隨。","那堪馬上曲，時向管中吹。"]', '["外館踰河右，行營指路岐。","和親悲远嫁，忍愛泣將離。","旌斾羗风引，軒车漢月隨。","那堪马上曲，时向管中吹。"]', '诗', 'shi', '', NULL, '奉和送金城公主入西蕃應制 劉憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0badfafd-7d3f-4003-8a4e-80c643bdc10a', '奉和聖製登驪山高頂寓目應制', '奉和聖製登驪山高頂寓目應制', '5b300b57-f5e8-470e-a5fb-166618c1fd98', '唐', '["驪阜鎮皇都，鑾遊眺八區。","原隰旌門裏，風雲扆座隅。","直城如斗柄，官樹似星榆。","從臣詞賦末，濫得上天衢。"]', '["驪阜鎮皇都，鑾游眺八區。","原隰旌门裏，风云扆座隅。","直城如斗柄，官樹似星榆。","從臣词賦末，濫得上天衢。"]', '诗', 'shi', '', NULL, '奉和聖製登驪山高頂寓目應制 劉憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5d4264b-a1e8-4331-a09a-04f54d9fdeee', '奉和幸白鹿觀應制', '奉和幸白鹿观應制', '5b300b57-f5e8-470e-a5fb-166618c1fd98', '唐', '["玄遊乘落暉，仙宇藹霏微。","石梁縈澗轉，珠斾掃壇飛。","芝童薦膏液，松鶴舞驂騑。","還似瑤池上，歌成周馭歸。"]', '["玄游乘落暉，仙宇藹霏微。","石梁縈澗轉，珠斾掃壇飞。","芝童薦膏液，松鹤舞驂騑。","還似瑤池上，歌成周馭归。"]', '诗', 'shi', '', NULL, '奉和幸白鹿觀應制 劉憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2571834c-30da-4c33-831c-ad55226c30b4', '折楊柳', '折楊柳', '5b300b57-f5e8-470e-a5fb-166618c1fd98', '唐', '["沙塞三河道，金閨二月春。","碧煙楊柳色，紅粉綺羅人。","露葉憐啼臉，風花思舞巾。","攀持君不見，爲聽曲中新。"]', '["沙塞三河道，金閨二月春。","碧煙楊柳色，紅粉綺羅人。","露葉怜啼臉，风花思舞巾。","攀持君不见，爲听曲中新。"]', '诗', 'shi', '', NULL, '折楊柳 劉憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ded5bd0-ce40-4e0c-8e47-ea8e53e6c1a7', '奉和立春日內出綵花樹應制', '奉和立春日內出綵花樹應制', '5b300b57-f5e8-470e-a5fb-166618c1fd98', '唐', '["禁苑韶年此日歸，東郊道上轉青旂。","柳色梅芳何處所，風前雪裏覓芳菲。","開冰池內魚新躍，剪綵花間燕始飛。","欲識王遊布陽氣，爲觀天藻競春暉。"]', '["禁苑韶年此日归，东郊道上轉青旂。","柳色梅芳何处所，风前雪裏覓芳菲。","开冰池內鱼新躍，剪綵花间燕始飞。","欲識王游布陽氣，爲观天藻競春暉。"]', '诗', 'shi', '', NULL, '奉和立春日內出綵花樹應制 劉憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf138811-0247-4918-9bc8-6dc812a3aa3b', '奉和春日幸望春宮應制', '奉和春日幸望春宮應制', '5b300b57-f5e8-470e-a5fb-166618c1fd98', '唐', '["暮春春色最便妍，苑裏花開列御筵。","商山積翠臨城起，滻水浮光共幕連。","鶯藏嫩葉歌相喚，蝶礙芳叢舞不前。","歡娛節物今如此，願奉宸遊億萬年。"]', '["暮春春色最便妍，苑裏花开列御筵。","商山積翠臨城起，滻水浮光共幕連。","鶯藏嫩葉歌相喚，蝶礙芳叢舞不前。","歡娛節物今如此，願奉宸游億万年。"]', '诗', 'shi', '', NULL, '奉和春日幸望春宮應制 劉憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bc0ff85-ea67-41a4-b748-af836da05e4a', '奉和幸安樂公主山莊應制', '奉和幸安乐公主山莊應制', '5b300b57-f5e8-470e-a5fb-166618c1fd98', '唐', '["主家別墅帝城隈，無勞海上覓蓬萊。","沓石懸流平地起，危樓曲閣半天開。","庭莎作薦舞行出，浦樹相將歌棹回。","此日風光與形勝，衹言作伴聖詞來。"]', '["主家別墅帝城隈，無勞海上覓蓬萊。","沓石懸流平地起，危楼曲閣半天开。","庭莎作薦舞行出，浦樹相將歌棹回。","此日风光與形勝，衹言作伴聖词来。"]', '诗', 'shi', '', NULL, '奉和幸安樂公主山莊應制 劉憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d3e71c6-cddb-4291-a9db-48873615f1a5', '興慶池侍宴應制', '兴慶池侍宴應制', '5b300b57-f5e8-470e-a5fb-166618c1fd98', '唐', '["蒼龍闕下天泉池，軒駕來遊簫管吹。","緣堤夏篠縈不散，冐水新荷卷復披。","帳殿疑從畫裏出，樓船直在鏡中移。","自然東海神仙處，何用西崑轍迹疲。"]', '["蒼龙闕下天泉池，軒駕来游簫管吹。","緣堤夏篠縈不散，冐水新荷卷复披。","帳殿疑從畫裏出，楼船直在镜中移。","自然东海神仙处，何用西崑轍迹疲。"]', '诗', 'shi', '', NULL, '興慶池侍宴應制 劉憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f65f6a94-dcc8-4429-849e-766ed1ffaa9a', '奉和幸大薦福寺應制', '奉和幸大薦福寺應制', '5b300b57-f5e8-470e-a5fb-166618c1fd98', '唐', '["地靈傳景福，天駕儼鉤陳。","佳哉藩邸舊，赫矣梵宮新。","香塔魚山下，禪堂雁水濱。","珠幡映白日，鏡殿寫青春。","甚歡延故吏，大覺拯生人。","幸承歌頌末，長奉屬車塵。"]', '["地靈傳景福，天駕儼鉤陳。","佳哉藩邸旧，赫矣梵宮新。","香塔鱼山下，禪堂雁水濱。","珠幡映白日，镜殿寫青春。","甚歡延故吏，大覺拯生人。","幸承歌頌末，长奉屬车塵。"]', '诗', 'shi', '', NULL, '奉和幸大薦福寺應制 劉憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdcf3f45-3d7a-4399-b972-4a5597ad55db', '奉和幸三會寺應制', '奉和幸三會寺應制', '5b300b57-f5e8-470e-a5fb-166618c1fd98', '唐', '["岧嶤倉史臺，敞朗紺園開。","戒旦壺人集，翻霜羽騎來。","下輦登三襲，褰旒望九垓。","林披舘陶牓，水浸昆明灰。","網戶飛花綴，幡竿度鳥迴。","豫遊仙唱動，瀟灑出塵埃。"]', '["岧嶤倉史台，敞朗紺园开。","戒旦壺人集，翻霜羽騎来。","下輦登三襲，褰旒望九垓。","林披舘陶牓，水浸昆明灰。","網戶飞花綴，幡竿度鸟迴。","豫游仙唱动，瀟灑出塵埃。"]', '诗', 'shi', '', NULL, '奉和幸三會寺應制 劉憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7b9e810-21fd-41c1-a64d-0cdb0c6dab69', '奉和幸長安故城未央宮應制', '奉和幸长安故城未央宮應制', '5b300b57-f5e8-470e-a5fb-166618c1fd98', '唐', '["漢宮千祀外，軒駕一來遊。","夷蕩長如此，威靈不復留。","憑高睿賞發，懷古聖情周。","寒向南山歛，春過北渭浮。","土功昔云盛，人英今所求。","幸聽熏風曲，方知霸道羞。"]', '["漢宮千祀外，軒駕一来游。","夷蕩长如此，威靈不复留。","憑高睿賞發，懷古聖情周。","寒向南山歛，春過北渭浮。","土功昔云盛，人英今所求。","幸听熏风曲，方知霸道羞。"]', '诗', 'shi', '', NULL, '奉和幸長安故城未央宮應制 劉憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1d7c2cc-b778-4257-acee-404582b175e3', '奉和幸禮部尚書竇希玠宅應制', '奉和幸禮部尚书竇希玠宅應制', '5b300b57-f5e8-470e-a5fb-166618c1fd98', '唐', '["北斗樞機任，西京肺腑親。","疇昔王門下，今茲御幸辰。","恩光山水被，聖作管弦新。","遶坐熏紅藥，當軒暗綠筠。","摘荷纔早夏，聽鳥尚餘春。","行漏今徒晚，風煙起觀津。"]', '["北斗樞機任，西京肺腑親。","疇昔王门下，今茲御幸辰。","恩光山水被，聖作管弦新。","遶坐熏紅藥，當軒暗綠筠。","摘荷纔早夏，听鸟尚餘春。","行漏今徒晚，风煙起观津。"]', '诗', 'shi', '', NULL, '奉和幸禮部尚書竇希玠宅應制 劉憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c154414-92e5-4805-96e3-ae798baeb2ab', '奉和聖製幸望春宮送朔方大總管張仁亶', '奉和聖製幸望春宮送朔方大總管張仁亶', '5b300b57-f5e8-470e-a5fb-166618c1fd98', '唐', '["命將擇耆年，圖功勝必全。","光輝萬乘餞，威武二庭宣。","中衢橫鼓角，曠野蔽旌旃。","推食天廚至，投醪御酒傳。","涼風過雁苑，殺氣下雞田。","分閫恩何極，臨岐動睿篇。"]', '["命將擇耆年，圖功勝必全。","光輝万乘餞，威武二庭宣。","中衢橫鼓角，曠野蔽旌旃。","推食天廚至，投醪御酒傳。","涼风過雁苑，殺氣下雞田。","分閫恩何極，臨岐动睿篇。"]', '诗', 'shi', '', NULL, '奉和聖製幸望春宮送朔方大總管張仁亶 劉憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbcbbb9b-b3be-4a39-a41b-0c01993c2b5b', '奉和幸韋嗣立山莊侍宴應制', '奉和幸韋嗣立山莊侍宴應制', '5b300b57-f5e8-470e-a5fb-166618c1fd98', '唐', '["東山有謝安，枉道降鳴鑾。","緹騎分初日，霓旌度曉寒。","雲蹕巖間下，虹橋澗底盤。","幽棲俄以届，聖矚宛餘歡。","崖懸飛溜直，岸轉綠潭寬。","桂華堯酒泛，松響舜琴彈。","明主恩斯極，賢臣節更殫。","不才叨侍從，詠德以濡翰。"]', '["东山有謝安，枉道降鳴鑾。","緹騎分初日，霓旌度晓寒。","云蹕巖间下，虹橋澗底盤。","幽棲俄以届，聖矚宛餘歡。","崖懸飞溜直，岸轉綠潭寬。","桂华堯酒泛，松响舜琴彈。","明主恩斯極，賢臣節更殫。","不才叨侍從，詠德以濡翰。"]', '诗', 'shi', '', NULL, '奉和幸韋嗣立山莊侍宴應制 劉憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('901756ab-621e-46e7-9dc5-502e11c59558', '人日翫雪應制', '人日翫雪應制', '5b300b57-f5e8-470e-a5fb-166618c1fd98', '唐', '["勝日登臨雲葉起，芳風搖蕩雪花飛。","呈暉幸得承金鏡，颺彩還將奉玉衣。"]', '["勝日登臨云葉起，芳风搖蕩雪花飞。","呈暉幸得承金镜，颺彩還將奉玉衣。"]', '诗', 'shi', '', NULL, '人日翫雪應制 劉憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8723446-6f05-4b01-b97b-b0ab44f5bc5a', '上巳日祓禊渭濱應制', '上巳日祓禊渭濱應制', '5b300b57-f5e8-470e-a5fb-166618c1fd98', '唐', '["桃花欲落柳條長，沙頭水上足風光。","此時御蹕來遊處，願奉年年祓禊觴。"]', '["桃花欲落柳條长，沙头水上足风光。","此时御蹕来游处，願奉年年祓禊觴。"]', '诗', 'shi', '', NULL, '上巳日祓禊渭濱應制 劉憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c44d50c8-eabc-4e14-84f7-fbe4d2af0e5b', '苑中遇雪應制', '苑中遇雪應制', '5b300b57-f5e8-470e-a5fb-166618c1fd98', '唐', '["龍驂曉入望春宮，正逢春雪舞東風。","花光倂灑天文上，寒氣行消御酒中。"]', '["龙驂晓入望春宮，正逢春雪舞东风。","花光倂灑天文上，寒氣行消御酒中。"]', '诗', 'shi', '', NULL, '苑中遇雪應制 劉憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('308d1e8b-69b0-482d-b5e2-8111e49e495d', '夜宴安樂公主新宅', '夜宴安乐公主新宅', '5b300b57-f5e8-470e-a5fb-166618c1fd98', '唐', '["層軒洞戶旦新披，度曲飛觴夜不疲。","綺綴玲瓏河色曉，珠簾隱映月華窺。"]', '["層軒洞戶旦新披，度曲飞觴夜不疲。","綺綴玲瓏河色晓，珠簾隐映月华窺。"]', '诗', 'shi', '', NULL, '夜宴安樂公主新宅 劉憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf6b77dd-f548-43e4-90a9-5203bb71dcd0', '奉和聖製幸韋嗣立山莊', '奉和聖製幸韋嗣立山莊', '5b300b57-f5e8-470e-a5fb-166618c1fd98', '唐', '["非吏非隱晉尚書，一丘一壑降乘輿。","天藻緣情兩曜合，山巵獻壽萬年餘。"]', '["非吏非隐晉尚书，一丘一壑降乘輿。","天藻緣情兩曜合，山巵獻壽万年餘。"]', '诗', 'shi', '', NULL, '奉和聖製幸韋嗣立山莊 劉憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b683d2e-949d-42b1-994d-25563faf420c', '餞唐永昌', '餞唐永昌', '5b300b57-f5e8-470e-a5fb-166618c1fd98', '唐', '["始見郎官拜洛陽，旋聞近侍發雕章。","緒言已勖期年政，綺字當生滿路光。"]', '["始见郎官拜洛陽，旋闻近侍發雕章。","緒言已勖期年政，綺字當生满路光。"]', '诗', 'shi', '', NULL, '餞唐永昌 劉憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e5c0091-3b8c-4843-a391-8765451cd122', '晦日置酒林亭', '晦日置酒林亭', '2b317edc-f600-4275-9d11-ce31bfc32674', '唐', '["正月符嘉節，三春翫物華。","忘懷寄尊酒，陶性狎山家。","柳翠含煙葉，梅芳帶雪花。","光陰不相借，遲遲落景斜。"]', '["正月符嘉節，三春翫物华。","忘懷寄尊酒，陶性狎山家。","柳翠含煙葉，梅芳带雪花。","光陰不相借，遲遲落景斜。"]', '诗', 'shi', '', NULL, '晦日置酒林亭 高正臣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b993be2-23fd-4469-a89f-a493bb442afd', '晦日重宴', '晦日重宴', '2b317edc-f600-4275-9d11-ce31bfc32674', '唐', '["芳辰重游衍，乘景共追隨。","班荆陪舊識，傾蓋得新知。","水葉分蓮沼，風花落柳枝。","自符河朔趣，寧羨高陽池。"]', '["芳辰重游衍，乘景共追隨。","班荆陪旧識，傾蓋得新知。","水葉分蓮沼，风花落柳枝。","自符河朔趣，寧羨高陽池。"]', '诗', 'shi', '', NULL, '晦日重宴 高正臣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('834ac43f-692a-4a67-8292-3a80e4a930c1', '晦日宴高氏林亭', '晦日宴高氏林亭', 'd067dde2-e827-493e-b8a3-6bf13496eeee', '唐', '["上月河陽地，芳辰景物華。","緜蠻變時鳥，照曜起春霞。","柳搖風處色，梅散日前花。","淹留洛城晚，歌吹石崇家。"]', '["上月河陽地，芳辰景物华。","緜蠻变时鸟，照曜起春霞。","柳搖风处色，梅散日前花。","淹留洛城晚，歌吹石崇家。"]', '诗', 'shi', '', NULL, '晦日宴高氏林亭 崔知賢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3eaa47b5-3860-41bd-8856-13cbdb2b81de', '上元夜效小庾體', '上元夜效小庾體', 'd067dde2-e827-493e-b8a3-6bf13496eeee', '唐', '["今夜啓城闉，結伴戲芳春。","鼓聲撩亂動，風光觸處新。","月下多遊騎，燈前饒看人。","歡樂無窮已，歌舞達明晨。"]', '["今夜啓城闉，結伴戲芳春。","鼓声撩亂动，风光觸处新。","月下多游騎，灯前饒看人。","歡乐無窮已，歌舞達明晨。"]', '诗', 'shi', '', NULL, '上元夜效小庾體 崔知賢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1478971-4188-4f24-b05f-ffd69291177f', '三月三日宴王明府山亭', '三月三日宴王明府山亭', 'd067dde2-e827-493e-b8a3-6bf13496eeee', '唐', '["京洛皇居，芳禊春餘。","影媚元巳，和風上除。","雲開翠帟，水鶩鮮居。","林渚縈暎，煙霞卷舒。","花飄粉蝶，藻躍文魚。","沿波式宴，其樂只且。"]', '["京洛皇居，芳禊春餘。","影媚元巳，和风上除。","云开翠帟，水鶩鲜居。","林渚縈暎，煙霞卷舒。","花飄粉蝶，藻躍文鱼。","沿波式宴，其乐只且。"]', '诗', 'shi', '', NULL, '三月三日宴王明府山亭 崔知賢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73f08ddb-4bad-4f23-8017-600c13c6b1cd', '三月三日宴王明府山亭', '三月三日宴王明府山亭', '15411f27-3b00-4720-89d5-0add5d985323', '唐', '["日惟上巳，時亨有巢。","中尊引桂，芳筵籍茅。","書僮橐筆，膳夫行炰。","煙霏萬雉，花明四郊。","沼蘋白帶，山花紫苞。","同人聚飲，千載神交。"]', '["日惟上巳，时亨有巢。","中尊引桂，芳筵籍茅。","书僮橐笔，膳夫行炰。","煙霏万雉，花明四郊。","沼蘋白带，山花紫苞。","同人聚饮，千載神交。"]', '诗', 'shi', '', NULL, '三月三日宴王明府山亭 席元明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24bd0a93-c88c-4e63-a17b-622607387de0', '晦日宴高氏林亭', '晦日宴高氏林亭', '30c865e4-ff7b-4558-b4f2-ffa111fac0ae', '唐', '["欲知行有樂，芳尊對物華。","地接安仁縣，園是季倫家。","柳處雲疑葉，梅間雪似花。","日落歸途遠，留興伴煙霞。"]', '["欲知行有乐，芳尊对物华。","地接安仁縣，园是季倫家。","柳处云疑葉，梅间雪似花。","日落归途远，留兴伴煙霞。"]', '诗', 'shi', '', NULL, '晦日宴高氏林亭 韓仲宣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f023ffc-e9fe-4261-8c25-0f3a2cd635de', '晦日重宴', '晦日重宴', '30c865e4-ff7b-4558-b4f2-ffa111fac0ae', '唐', '["鳳苑先吹晚，龍樓夕照披。","陳遵已投轄，山公正坐池。","落日催金奏，飛霞送玉巵。","此時陪綺席，不醉欲何爲。"]', '["鳳苑先吹晚，龙楼夕照披。","陳遵已投轄，山公正坐池。","落日催金奏，飞霞送玉巵。","此时陪綺席，不醉欲何爲。"]', '诗', 'shi', '', NULL, '晦日重宴 韓仲宣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72233e48-4d10-4360-8dce-5d2044594ef8', '上元夜效小庾體', '上元夜效小庾體', '30c865e4-ff7b-4558-b4f2-ffa111fac0ae', '唐', '["他鄉月夜人，相伴看燈輪。","光隨九華出，影共百枝新。","歌鐘盛北里，車馬沸南鄰。","今宵何處好？惟有洛城春。"]', '["他乡月夜人，相伴看灯輪。","光隨九华出，影共百枝新。","歌鐘盛北里，车马沸南鄰。","今宵何处好？惟有洛城春。"]', '诗', 'shi', '', NULL, '上元夜效小庾體 韓仲宣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f229ca05-ff53-49de-b96a-931bfe645833', '三月三日宴王明府山亭', '三月三日宴王明府山亭', '30c865e4-ff7b-4558-b4f2-ffa111fac0ae', '唐', '["河濱上巳，洛汭春華。","碧池涵日，翠斝澄霞。","溝垂細柳，岸擁平沙。","歌鶯響樹，舞蝶驚花。","雲浮寶馬，水韻香車。","熟記行樂，淹留景斜。"]', '["河濱上巳，洛汭春华。","碧池涵日，翠斝澄霞。","溝垂細柳，岸擁平沙。","歌鶯响樹，舞蝶驚花。","云浮寶马，水韻香车。","熟記行乐，淹留景斜。"]', '诗', 'shi', '', NULL, '三月三日宴王明府山亭 韓仲宣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aa2468a-862d-452c-ad4d-e7e6ec83635f', '晦日宴高氏林亭', '晦日宴高氏林亭', 'c42a20cd-002e-4921-bec0-2dff2833c24c', '唐', '["勝地臨雞浦，高會偶龍沙。","御柳驚春色，仙筇掩月華。","門邀千里馭，杯泛九光霞。","日落山亭晚，雷送七香車。"]', '["勝地臨雞浦，高會偶龙沙。","御柳驚春色，仙筇掩月华。","门邀千里馭，杯泛九光霞。","日落山亭晚，雷送七香车。"]', '诗', 'shi', '', NULL, '晦日宴高氏林亭 周彥昭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5d81b06-c71c-4994-a6c7-5520b507821a', '晦日宴高氏林亭', '晦日宴高氏林亭', '16bb726f-c298-4de2-9df8-f98683f02f25', '唐', '["溫洛年光早，皇州景望華。","連鑣尋上路，乘興入山家。","輕苔網危石，春水架平沙。","賞極林塘暮，處處起煙霞。"]', '["溫洛年光早，皇州景望华。","連鑣尋上路，乘兴入山家。","轻苔網危石，春水架平沙。","賞極林塘暮，处处起煙霞。"]', '诗', 'shi', '', NULL, '晦日宴高氏林亭 高球 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b73a722-dad8-4e17-8509-642113227482', '三月三日宴王[明]府山亭', '三月三日宴王[明]府山亭', '16bb726f-c298-4de2-9df8-f98683f02f25', '唐', '["洛城春禊，元巳芳年。","季倫園裏，逸少亭前。","曲中舉白，談際生玄。","陸離軒蓋，淒清管弦。","萍疎波蕩，柳弱風牽。","未淹歡趣，林溪夕煙。"]', '["洛城春禊，元巳芳年。","季倫园裏，逸少亭前。","曲中舉白，談際生玄。","陸離軒蓋，淒清管弦。","萍疎波蕩，柳弱风牽。","未淹歡趣，林溪夕煙。"]', '诗', 'shi', '', NULL, '三月三日宴王[明]府山亭 高球 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55da3012-4d45-4fb6-ade9-1a7a0b421c22', '晦日宴高氏林亭', '晦日宴高氏林亭', '342355e1-0bd0-4d74-8f00-f4bf62126ebe', '唐', '["上序春暉麗，中園物候華。","高才盛文雅，逸興滿煙霞。","參差金谷樹，皎鏡碧塘沙。","蕭散林亭晚，倒載欲還家。"]', '["上序春暉丽，中园物候华。","高才盛文雅，逸兴满煙霞。","參差金谷樹，皎镜碧塘沙。","蕭散林亭晚，倒載欲還家。"]', '诗', 'shi', '', NULL, '晦日宴高氏林亭 弓嗣初 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c2c293e-2e79-4a03-8fe7-fd97fb6ef824', '晦日重宴', '晦日重宴', '342355e1-0bd0-4d74-8f00-f4bf62126ebe', '唐', '["年華藹芳隰，春溜滿新池。","促賞依三友，延歡寄一巵。","鳥聲隨管變，花影逐風移。","行樂方無極，淹留惜晚曦。"]', '["年华藹芳隰，春溜满新池。","促賞依三友，延歡寄一巵。","鸟声隨管变，花影逐风移。","行乐方無極，淹留惜晚曦。"]', '诗', 'shi', '', NULL, '晦日重宴 弓嗣初 shi');
